function getAionDepartmentPulseSummaryItems(departmentKey = getAionBoardroomSelectedDepartmentPulseKey()) {
  const key = normaliseAionDepartmentPilotKey(departmentKey);
  const pulse = getBoardroomPulse();
  const center = getBoardroomCenter();
  const runtime = getBoardroomRuntime();

  const cash = asRecord(pulse.cash) || {};
  const sales = asRecord(pulse.sales) || {};
  const ops = asRecord(pulse.ops) || {};
  const finance = asRecord(pulse.finance) || {};
  const runtimeRuns = safeArray(runtime.runs);
  const runtimeApprovals = safeArray(runtime.approvals);
  const pendingApprovals = runtimeApprovals.filter((item) => item?.status === "pending").length;

  if (key === "sales") {
    return [
      { label: "Revenue", value: formatBoardroomEuro(sales.revenue ?? center.revenue ?? "—"), sub: "Sales value" },
      { label: "Orders", value: sales.orders ?? "—", sub: "Current orders" },
      { label: "Conversion", value: formatBoardroomPercent(sales.conversionRate ?? sales.conversion_rate ?? "—"), sub: "Lead conversion" },
      { label: "Pipeline", value: center.pipeline ?? "—", sub: "Open work" },
      { label: "Follow-up", value: pendingApprovals, sub: "Needs review" },
      { label: "Runs", value: runtimeRuns.length, sub: "Activity" },
    ];
  }

  if (key === "marketing") {
    return [
      { label: "Leads", value: sales.leads ?? sales.orders ?? "—", sub: "Captured demand" },
      { label: "Campaigns", value: runtimeRuns.length, sub: "Draft/preview runs" },
      { label: "Conversion", value: formatBoardroomPercent(sales.conversionRate ?? sales.conversion_rate ?? "—"), sub: "Sales handoff" },
      { label: "Budget", value: formatBoardroomEuro(finance.marketingBudget ?? finance.marketing_budget ?? "—"), sub: "Safe spend" },
      { label: "Proof", value: "—", sub: "Evidence count" },
      { label: "Approvals", value: pendingApprovals, sub: "Pending" },
    ];
  }

  if (key === "operations") {
    return [
      { label: "Ops", value: ops.backlog ?? center.pipeline ?? "—", sub: "Workload" },
      { label: "Fulfilment", value: formatBoardroomPercent(ops.fulfilmentRate ?? ops.fulfilment_rate ?? "—"), sub: "Delivery rate" },
      { label: "Capacity", value: ops.capacity ?? "—", sub: "Available" },
      { label: "Bottlenecks", value: ops.bottlenecks ?? "—", sub: "Known issues" },
      { label: "Automation", value: ops.automationCandidates ?? ops.automation_candidates ?? "—", sub: "Candidates" },
      { label: "Runs", value: runtimeRuns.length, sub: "Activity" },
    ];
  }

  if (key === "support") {
    return [
      { label: "Issues", value: ops.supportIssues ?? ops.support_issues ?? "—", sub: "Open issues" },
      { label: "Response", value: ops.responseRate ?? ops.response_rate ?? "—", sub: "Speed" },
      { label: "Quality", value: ops.serviceQuality ?? ops.service_quality ?? "—", sub: "Signal" },
      { label: "Templates", value: ops.supportTemplates ?? ops.support_templates ?? "—", sub: "Available" },
      { label: "Receipts", value: pendingApprovals, sub: "Review items" },
      { label: "Runs", value: runtimeRuns.length, sub: "Activity" },
    ];
  }


  if (key === "finance") {
    return [
      { label: "Cash", value: formatBoardroomEuro(cash.onHand ?? cash.on_hand ?? center.cash ?? "—"), sub: `Runway ${cash.runwayDays ?? cash.runway_days ?? "—"}d` },
      { label: "Revenue", value: formatBoardroomEuro(sales.revenue ?? center.revenue ?? "—"), sub: `Orders ${sales.orders ?? "—"} · Conv ${sales.conversionRate ?? sales.conversion_rate ?? "—"}%` },
      { label: "Costs", value: formatBoardroomEuro(finance.costs ?? finance.monthly_costs ?? "—"), sub: "Known costs" },
      { label: "Debtors", value: finance.debtorDays ?? finance.debtor_days ?? "—", sub: `Creditor ${finance.creditorDays ?? finance.creditor_days ?? "—"}` },
      { label: "Margin", value: formatBoardroomPercent(finance.grossMarginPct ?? finance.gross_margin_pct ?? "—"), sub: "Gross margin" },
      { label: "Runs", value: runtimeRuns.length, sub: `${pendingApprovals} approval${pendingApprovals === 1 ? "" : "s"}` },
    ];
  }

  return [
    { label: "Cash", value: formatBoardroomEuro(cash.onHand ?? cash.on_hand ?? center.cash ?? "—"), sub: `Runway ${cash.runwayDays ?? cash.runway_days ?? "—"}d` },
    { label: "Revenue", value: formatBoardroomEuro(sales.revenue ?? center.revenue ?? "—"), sub: `Orders ${sales.orders ?? "—"} · Conv ${sales.conversionRate ?? sales.conversion_rate ?? "—"}%` },
    { label: "Costs", value: formatBoardroomEuro(finance.costs ?? finance.monthly_costs ?? "—"), sub: "Known costs" },
    { label: "Debtors", value: finance.debtorDays ?? finance.debtor_days ?? "—", sub: `Creditor ${finance.creditorDays ?? finance.creditor_days ?? "—"}` },
    { label: "Margin", value: formatBoardroomPercent(finance.grossMarginPct ?? finance.gross_margin_pct ?? "—"), sub: "Gross margin" },
    { label: "Runs", value: runtimeRuns.length, sub: `${pendingApprovals} approval${pendingApprovals === 1 ? "" : "s"}` },
  ];
}

