function renderBoardroomDepartmentIntelligencePanel() {
  let ledger = {};

  try {
    if (typeof getAionDepartmentIntelligence === "function") {
      ledger = getAionDepartmentIntelligence();
    } else {
      const raw = localStorage.getItem("aion.departmentIntelligence.v1") || "{}";
      ledger = JSON.parse(raw);
    }
  } catch {
    ledger = {};
  }

  const departments = ["marketing", "sales", "finance", "operations", "support"];

  const rows = departments.map((department) => {
    const entry = ledger && typeof ledger === "object" ? ledger[department] || {} : {};
    const status = entry.status || "needs_discovery";
    const summary = entry.boardroom_summary || "No department intelligence captured yet.";

    return `
      <div class="list-item">
        <div class="list-item-title">${escapeHtml(runtimeShared.getDepartmentLabel(department))}</div>
        <div class="list-item-sub">${escapeHtml(status)} · ${escapeHtml(summary)}</div>
      </div>
    `;
  }).join("");

  return `
    <section class="panel" data-aion-boardroom-department-intelligence-fallback-v1="true" style="background:#ffffff;">
      <div class="surface-eyebrow">Department Intelligence</div>
      <div class="panel-title">Department Intelligence Ledger</div>
      <div class="helper-text">
        Safe Boardroom fallback reading <code>aion.departmentIntelligence.v1</code>.
      </div>
      <div class="list-wrap" style="margin-top:10px;">
        ${rows}
      </div>
    </section>
  `;
}

