/* AION PATCH: Boardroom view toggle authority v1 */
if (!window.__aionBoardroomViewToggleAuthorityV1) {
  window.__aionBoardroomViewToggleAuthorityV1 = true;

  document.addEventListener("click", (event) => {
    const button = event.target?.closest?.("[data-boardroom-view]");
    if (!button) return;

    const mode = String(button.getAttribute("data-boardroom-view") || "").trim().toLowerCase();
    if (!["spatial", "dashboard"].includes(mode)) return;

    event.preventDefault();
    event.stopPropagation();

    try {
      state.boardroomViewMode = mode;
      window.__aionBoardroomManualViewModeV1 = mode;
      localStorage.setItem("aion.boardroomViewMode.v1", mode);
    } catch {}

    if (typeof requestRender === "function") requestRender();
    else if (typeof render === "function") render();
  }, true);

  console.log("[AION] Boardroom view toggle authority v1 installed");
}


