function focusAionVaultBoardroomProvidersV1() {
  const panel = document.querySelector('[data-aion-vault-ai-providers="true"]');
  if (!panel) return false;

  panel.setAttribute("data-aion-vault-boardroom-focus", "true");
  panel.scrollIntoView?.({ behavior: "smooth", block: "start" });

  window.setTimeout(() => {
    const providerSelect = panel.querySelector('[data-aion-vault-ai-provider-select="true"]');
    try { providerSelect?.focus?.({ preventScroll: true }); } catch { providerSelect?.focus?.(); }
  }, 240);

  window.setTimeout(() => {
    panel.removeAttribute("data-aion-vault-boardroom-focus");
  }, 2600);

  return true;
}

function openAionVaultBoardroomProvidersV1() {
  if (typeof window.setAionSidebarActiveTabHardV1 === "function") {
    window.setAionSidebarActiveTabHardV1("vault");
  } else {
  const nextTab = typeof setActiveTab === "function" ? setActiveTab("vault") : "vault";
  state.activeTab = nextTab;

    try {
      if (typeof safeAionDesktopPatch === "function") safeAionDesktopPatch({ activeTab: nextTab });
      desktopStore?.persistCacheSoon?.(50);
    } catch {}

    if (typeof render === "function") render();
    else if (typeof requestRender === "function") requestRender();
  }

  [0, 80, 220, 520].forEach((delay) => {
    window.setTimeout(() => focusAionVaultBoardroomProvidersV1(), delay);
  });
}

function openAionExecutiveDepartmentFromStickyHeaderV1(departmentKey = "") {
  const key = String(departmentKey || "").trim().toLowerCase();
  const allowed = new Set([
    "marketing",
    "sales",
    "finance",
    "operations",
    "support",
    "hr",
    "products_services",
    "pilot",
    ...getAionDesktopCustomDepartmentsV1().map((department) => String(department?.id || "").toLowerCase()),
  ]);
  if (!allowed.has(key)) return false;

  try {
    const isCustomDepartment = getAionDesktopCustomDepartmentsV1().some((department) => String(department?.id || "").toLowerCase() === key);
    if (!isCustomDepartment && typeof setLiveAgentsWorkspace === "function") {
      setLiveAgentsWorkspace(key, {
        preferredView: typeof LIVE_AGENT_VIEWS === "object" ? LIVE_AGENT_VIEWS.STREAM : "stream",
        openReplay: false,
      });
    }

    window.__aionPreferredLiveAgentDepartment = key;
    window.__aionLiveAgentsFocusDepartment = key;
    window.__aionO16ASelectedLiveAgentsDepartment = key;
    window.__aionO14A6ClickedDepartmentPilot = key;
    window.__aionO14A6ActiveDepartmentPilot = key;
    window.__aionActiveDepartmentPilot = key;
    window.__aionSelectedDepartmentPilot = key;
    state.activeTab = "live_agents";
    state.activeZone = key;

    localStorage.setItem("aion.liveAgents.selectedDepartment", key);
    localStorage.setItem("aion.selectedLiveDepartment", key);
    localStorage.setItem("aion.departmentPilot.selected", key);
    localStorage.setItem("aion.forcedMainTab.v2", "live_agents");

    if (typeof window.setAionSidebarActiveTabHardV1 === "function") {
      window.setAionSidebarActiveTabHardV1("live_agents");
    } else {
      window.__aionForcedMainTabV2 = "live_agents";
      requestRender?.();
    }
    return true;
  } catch (error) {
    console.warn("[AION] Executive shortcut failed", key, error);
    return false;
  }
}

if (!window.__aionBoardroomStickyTeamHeaderV1Installed) {
  window.__aionBoardroomStickyTeamHeaderV1Installed = true;

  /* The legacy O14M authority listens on window pointerdown and cancels the
     later click after changing only the highlight. Register first, on the
     same phase, so this complete route transaction wins atomically. */
  window.addEventListener("pointerdown", (event) => {
    const createDepartment = event.target?.closest?.('[data-aion-executive-secondary-action="create-custom-department"]');
    if (createDepartment) {
      event.preventDefault();
      event.stopPropagation();
      event.stopImmediatePropagation?.();
      window.__aionDesktopCustomDepartmentCreatorV1 = true;
      requestRender?.();
      return;
    }

    const aionPilot = event.target?.closest?.("[data-aion-board-member-pilot='true']");
    if (aionPilot) {
      event.preventDefault();
      event.stopPropagation();
      event.stopImmediatePropagation?.();
      openAionExecutiveDepartmentFromStickyHeaderV1("pilot");
      return;
    }

    const executiveMember = event.target?.closest?.("[data-aion-boardroom-sticky-member]");
    if (!executiveMember) return;
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation?.();
    openAionExecutiveDepartmentFromStickyHeaderV1(
      executiveMember.getAttribute("data-aion-boardroom-sticky-member") || ""
    );
  }, true);

  document.addEventListener("click", (event) => {
    const aionPilot = event.target?.closest?.("[data-aion-board-member-pilot='true']");
    if (aionPilot) {
      event.preventDefault();
      event.stopPropagation();
      event.stopImmediatePropagation?.();
      openAionExecutiveDepartmentFromStickyHeaderV1("pilot");
      return;
    }

    const executiveMember = event.target?.closest?.("[data-aion-boardroom-sticky-member]");
    if (executiveMember) {
      event.preventDefault();
      event.stopPropagation();
      event.stopImmediatePropagation?.();
      const departmentKey = executiveMember.getAttribute("data-aion-boardroom-sticky-member") || "";
      openAionExecutiveDepartmentFromStickyHeaderV1(departmentKey);
      return;
    }

    const boardMember = event.target?.closest?.("[data-aion-board-member-direct-line]");
    if (boardMember) {
      event.preventDefault();
      event.stopPropagation();
      const providerId = normaliseAionBoardProviderKeyV1(
        boardMember.getAttribute("data-aion-board-member-direct-line") || ""
      );
      const currentId = normaliseAionBoardProviderKeyV1(window.__aionBoardMemberDirectLineV1?.provider_id || "");
      window.__aionBoardMemberDirectLineV1 = currentId === providerId
        ? null
        : { provider_id: providerId, loading: false, draft: "", response: "", error: "" };
      requestRender?.();
      window.setTimeout(() => {
        try { document.querySelector(`[data-aion-board-direct-line-input="${providerId}"]`)?.focus?.(); } catch {}
      }, 40);
      return;
    }

    const closeDirectLine = event.target?.closest?.("[data-aion-board-direct-line-close='true']");
    if (closeDirectLine) {
      event.preventDefault();
      event.stopPropagation();
      window.__aionBoardMemberDirectLineV1 = null;
      requestRender?.();
      return;
    }

    const sendDirectLine = event.target?.closest?.("[data-aion-board-direct-line-send]");
    if (sendDirectLine) {
      event.preventDefault();
      event.stopPropagation();
      const providerId = sendDirectLine.getAttribute("data-aion-board-direct-line-send") || "";
      const input = document.querySelector(`[data-aion-board-direct-line-input="${providerId}"]`);
      sendAionBoardMemberDirectLineV1(providerId, input?.value || "");
      return;
    }

    const createDepartment = event.target?.closest?.('[data-aion-executive-secondary-action="create-custom-department"]');
    if (createDepartment) {
      event.preventDefault();
      event.stopPropagation();
      window.__aionDesktopCustomDepartmentCreatorV1 = true;
      requestRender?.();
      return;
    }

    const closeCustomDepartmentCreator = event.target?.closest?.('[data-aion-custom-department-close="true"]');
    if (closeCustomDepartmentCreator) {
      event.preventDefault();
      window.__aionDesktopCustomDepartmentCreatorV1 = false;
      requestRender?.();
      return;
    }

    const continueCustomDepartmentCreator = event.target?.closest?.('[data-aion-custom-department-confirm="true"]');
    if (continueCustomDepartmentCreator) {
      event.preventDefault();
      const name = document.querySelector('[data-aion-custom-department-name="true"]')?.value?.trim() || "New department";
      window.__aionDesktopCustomDepartmentCreatorV1 = false;
      state.message = `${name} is ready to create. Confirm it from your paired phone so the Node can verify founder authority.`;
      state.messageTone = "info";
      requestRender?.();
      return;
    }

    const addProvider = event.target?.closest?.(
      '[data-aion-executive-secondary-action="provider-council-add-key"], [data-aion-provider-council-add-key="true"]'
    );
    if (addProvider) {
      event.preventDefault();
      event.stopPropagation();
      openAionVaultBoardroomProvidersV1();
      return;
    }

    const button = event.target?.closest?.("[data-aion-executive-header-action='toggle-boardroom-full-room']");
    if (!button) return;
    event.preventDefault();
    window.__aionBoardroomFullRoomExpandedV2 = !(window.__aionBoardroomFullRoomExpandedV2 === true);
    if (typeof requestRender === "function") requestRender();
    else if (typeof render === "function") render();
  }, true);

  document.addEventListener("change", (event) => {
    const select = event.target?.closest?.('[data-aion-custom-department-select="true"]');
    if (!select || !select.value) return;
    event.preventDefault();
    openAionExecutiveDepartmentFromStickyHeaderV1(select.value);
  }, true);

  document.addEventListener("keydown", (event) => {
    const input = event.target?.closest?.("[data-aion-board-direct-line-input]");
    if (!input || event.key !== "Enter" || event.shiftKey) return;
    event.preventDefault();
    event.stopPropagation();
    const providerId = input.getAttribute("data-aion-board-direct-line-input") || "";
    sendAionBoardMemberDirectLineV1(providerId, input.value || "");
  }, true);
}


/* AION PATCH: Safe Provider Council Panel fallback v1
 * ----------------------------------------------------------
 * Boardroom must never blank because the provider council panel helper
 * is missing. This fallback reads the provider council list if available
 * and otherwise shows a safe unavailable state.
 */
function renderAionProviderCouncilPanelFallbackV1() {
  let providers = [];

  try {
    if (typeof getAionProviderCouncilState === "function") {
      const raw = getAionProviderCouncilState();
      providers = Array.isArray(raw)
        ? raw
        : Array.isArray(raw?.providers)
          ? raw.providers
          : [];
    }
  } catch {}

  const providerRows = providers.length
    ? providers.map((provider) => {
        const name = provider?.name || provider?.provider || provider?.provider_id || provider?.id || "Provider";
        const status = provider?.status || provider?.connection_status || provider?.state || (provider?.connected ? "connected" : "unknown");
        const model = provider?.model || provider?.model_id || provider?.default_model || "";
        return `
          <div class="list-item">
            <div class="list-item-title">${escapeHtml(name)}</div>
            <div class="list-item-sub">${escapeHtml(status)}${model ? ` · ${escapeHtml(model)}` : ""}</div>
          </div>
        `;
      }).join("")
    : `
      <div class="list-item">
        <div class="list-item-title">Provider council not loaded</div>
        <div class="list-item-sub">
          Open Vault to connect OpenAI, Gemini, local Ollama/Gemma or other providers. Boardroom can still render without this panel.
        </div>
      </div>
    `;

  return `
    <section class="panel" data-aion-provider-council-panel-fallback-v1="true" style="background:#ffffff;">
      <div class="surface-eyebrow">AI Provider Council</div>
      <div class="panel-title">Provider Council</div>
      <div class="helper-text">
        Safe Boardroom fallback. This panel is display-only until the canonical Provider Council renderer is restored.
      </div>
      <div class="list-wrap" style="margin-top:10px;">
        ${providerRows}
      </div>
    </section>
  `;
}

function renderAionProviderCouncilPanelSafeV1(...args) {
  try {
    if (
      typeof window !== "undefined" &&
      typeof window.renderAionProviderCouncilPanel === "function" &&
      window.renderAionProviderCouncilPanel !== renderAionProviderCouncilPanelSafeV1
    ) {
      return window.renderAionProviderCouncilPanel(...args);
    }
  } catch (error) {
    console.warn("[AION] canonical provider council panel failed safely", error);
  }

  return renderAionProviderCouncilPanelFallbackV1(...args);
}


async function openAionBoardroomWorldV1() {
  window.__aionBoardroomFullRoomExpandedV2 = false;
  const members = getAionStickyBoardMembersV1(getBoardroomSnapshot()).map((member) => ({
    id: member.key,
    label: member.label,
    role: member.key === "aion" ? "Pilot" : "AI Board member",
    connected: member.connected !== false,
  }));
  let result;
  try {
    result = await window.aionDesktop?.launchSpatialBoardroom?.({ members });
  } catch (error) {
    result = { ok: false, error: "native_launch_failed", message: String(error?.message || error) };
  }
  window.__aionNativeBoardroomLaunchV1 = result || { ok: false, error: "desktop_bridge_unavailable" };
  if (result?.ok) {
    safeAionDesktopPatch?.({
      message: result.status === "already_running" ? "Spatial Boardroom is already open." : "Spatial Boardroom opened.",
      messageTone: "success",
    });
  } else {
    safeAionDesktopPatch?.({
      message: result?.message || "The native Spatial Boardroom is not built yet. The text Boardroom remains available.",
      messageTone: "warning",
    });
  }
  return result || { ok: false, error: "desktop_bridge_unavailable" };
}

window.openAionBoardroomWorldV1 = openAionBoardroomWorldV1;

function previewAionBoardroomWorldV1() {
  window.__aionBoardroomWorldEmbeddedV1 = true;
  requestRender?.();
  window.setTimeout(() => document
    .querySelector('[data-aion-boardroom-world-embedded="true"]')
    ?.scrollIntoView?.({ behavior: "smooth", block: "start" }), 60);
  return { ok: true, mode: "embedded_preview" };
}

window.previewAionBoardroomWorldV1 = previewAionBoardroomWorldV1;

function handleAionSpatialBoardroomActionV1(action = {}) {
  const memberId = normaliseAionBoardProviderKeyV1(action.member_id || "");
  if (action.type === "meeting_overview") return true;
  if (!memberId) return false;
  if (memberId === "aion") {
    return openAionExecutiveDepartmentFromStickyHeaderV1("pilot");
  }
  const snapshot = getBoardroomSnapshot();
  const member = getAionStickyBoardMembersV1(snapshot).find((item) => item.key === memberId);
  if (action.type === "open_board_member_chat" && !member) {
    safeAionDesktopPatch?.({ message: `${action.label || memberId} is not connected to this Boardroom.`, messageTone: "warning" });
    return false;
  }
  window.AionBoardroomSeatConversation?.open?.({
    seatId: action.type === "open_executive_chat" ? `seat_${memberId}` : `seat_provider_${memberId}`,
    key: memberId,
    teamMode: action.type === "open_executive_chat" ? "executive" : "board",
    label: action.label || member?.label || memberId,
    role: action.role || (action.type === "open_executive_chat" ? "Department-specific AION agent" : "Connected Board member"),
    providerId: memberId,
    snapshot,
  });
  return true;
}

window.handleAionSpatialBoardroomActionV1 = handleAionSpatialBoardroomActionV1;
if (!window.__aionSpatialBoardroomActionListenerV1) {
  window.__aionSpatialBoardroomActionListenerV1 = window.aionDesktop?.onSpatialBoardroomAction?.(
    handleAionSpatialBoardroomActionV1,
  ) || true;
}

function closeAionBoardroomWorldV1() {
  window.__aionBoardroomWorldEmbeddedV1 = false;
  if (typeof requestRender === "function") requestRender();
  else if (typeof render === "function") render();
  return { ok: true, mode: "boardroom" };
}

window.closeAionBoardroomWorldV1 = closeAionBoardroomWorldV1;


