/* PHASE 21X LOCK: Real frontend Pilot cockpit mount */


/* PHASE 21N LOCK: Pilot frontend interaction smoke */

function getAionPilotActiveDepartmentScope() {
  const recordContext = window.__aionPilotRecordContext;
  if (recordContext && String(recordContext.department || "").toLowerCase() === "sales") {
    return "sales";
  }
  let selected = "pilot";
  try {
    selected = typeof getSelectedLiveDepartmentKey === "function"
      ? String(getSelectedLiveDepartmentKey() || "pilot").toLowerCase()
      : "pilot";
  } catch {}

  if (["marketing", "sales", "finance", "operations", "support", "hr"].includes(selected)) {
    return selected;
  }
  return "pilot";
}

function getAionPilotInteractionStateKey() {
  const scope = getAionPilotActiveDepartmentScope();
  const recordContext = window.__aionPilotRecordContext;
  const recordId = String(recordContext?.opportunity_id || recordContext?.record_id || "").trim();
  return recordId ? `${scope}.customer.${recordId}` : scope;
}

function getAionPilotFrontendInteractionState() {
  const scope = getAionPilotActiveDepartmentScope();
  const stateKey = getAionPilotInteractionStateKey();
  if (!window.__aionPilotFrontendInteractionStates) {
    window.__aionPilotFrontendInteractionStates = {};
    if (window.__aionPilotFrontendInteractionState) {
      window.__aionPilotFrontendInteractionStates.pilot = window.__aionPilotFrontendInteractionState;
    }
  }

  const previousScope = window.__aionPilotLastInteractionStateKey;
  if (previousScope && window.__aionPilotFrontendInteractionStates[previousScope]) {
    try {
      localStorage.setItem(
        `aion.pilot.runtimeState.${previousScope}.v3`,
        JSON.stringify(window.__aionPilotFrontendInteractionStates[previousScope]),
      );
    } catch {}
  }

  if (!window.__aionPilotFrontendInteractionStates[stateKey]) {
    let storedState = null;
    try {
      const storageKey = stateKey === scope
        ? `aion.pilot.runtimeState.${scope}.v3`
        : `aion.pilot.runtimeState.${stateKey}.v3`;
      storedState = JSON.parse(localStorage.getItem(storageKey) || "null");
    } catch {}
    window.__aionPilotFrontendInteractionStates[stateKey] = storedState && typeof storedState === "object" ? storedState : {
      status: "idle",
      last_request: "",
      draft_created: false,
      department_scope: scope,
      stream_events: [],
      artifact_status: "draft_preview",
      artifact_hash: "sha256:preview_artifact_hash",
      receipt_hash: "sha256:preview_receipt_hash",
      replay_hash: "sha256:preview_replay_hash",
      proof_hash: "sha256:preview_proof_hash",
      blocked_live_actions: [
        "external_send",
        "production_deploy",
        "payment",
        "public_post",
        "booking",
        "escrow",
      ],
    };
  }

  window.__aionPilotLastInteractionStateKey = stateKey;
  window.__aionPilotLastDepartmentScope = scope;
  window.__aionPilotFrontendInteractionState = window.__aionPilotFrontendInteractionStates[stateKey];
  return window.__aionPilotFrontendInteractionStates[stateKey];
}

function classifyAionPilotRequestMode(requestText = "") {
  const text = String(requestText || "").trim();
  const lower = text.toLowerCase();
  const questionLike =
    /\?$/.test(text) ||
    /^(?:who|what|why|when|where|which|how|is|are|was|were|do|does|did|can|could|would|should)\b/i.test(text) ||
    /^(?:tell me|explain|describe|summari[sz]e|help me understand|give me information)\b/i.test(text);
  const liveActionVerb = "send|publish|deploy|pay|purchase|buy|book|refund|delete|remove|install|connect|upload|download|schedule|run|execute|launch|submit|approve|reject|email|message|call|contact|post";
  // Only treat a live-action word as an execution request when it is used as
  // the user's command.  Draft content can legitimately contain phrases such
  // as “explain why the customer should purchase it”; that must not be
  // mistaken for an instruction to make a purchase.
  const externalAction =
    new RegExp(`^(?:please\\s+)?(?:${liveActionVerb})\\b`, "i").test(lower) ||
    new RegExp(`^(?:can|could|would|will)\\s+you\\s+(?:please\\s+)?(?:${liveActionVerb})\\b`, "i").test(lower) ||
    new RegExp(`\\b(?:and|then|go ahead and)\\s+(?:please\\s+)?(?:${liveActionVerb})\\b`, "i").test(lower) ||
    new RegExp(`\\b(?:i want|i need|i'd like)\\s+you\\s+to\\s+(?:${liveActionVerb})\\b`, "i").test(lower);
  const productionRequest = /\b(?:create|build|make|prepare|draft|write|generate|design|edit|research|analyse|analyze|summari[sz]e)\b/i.test(lower);
  const mode = externalAction
    ? "governed_action"
    : productionRequest
      ? "safe_draft"
      : questionLike
        ? "direct_answer"
        : "safe_draft";

  return {
    mode,
    question_like: questionLike,
    external_action: externalAction,
    production_request: productionRequest,
  };
}

function buildAionPilotDirectKnowledgeAnswer(requestText = "", matches = []) {
  const asksForDifference = /\b(?:differ|different|difference|differentiator|unique|special|advantage|stand out)\b/i.test(String(requestText || ""));
  const unsafeClaim = /(?:synthetic test material|owner must review|for owner review|prohibited wording|must not strengthen|made entirely from|every competing|rust[- ]proof for life|maintenance[- ]free|guaranteed for \d+ years|patent protected or patented|certified for any)/i;
  const approvedMatches = (Array.isArray(matches) ? matches : [])
    .filter((claim) => String(claim?.text || "").trim())
    .filter((claim) => !unsafeClaim.test(String(claim?.text || "")))
    .filter((claim, index, rows) => rows.findIndex((candidate) => String(candidate?.text || "").trim().toLowerCase() === String(claim?.text || "").trim().toLowerCase()) === index)
    .sort((left, right) => {
      if (!asksForDifference) return Number(right?.retrieval_score || 0) - Number(left?.retrieval_score || 0);
      const relevance = (claim) => {
        const text = String(claim?.text || "");
        if (/\b(?:core differentiator|differentiator|different|distinguish|stand out)\b/i.test(text)) return 4;
        if (/\b(?:combination|primary promise|positioned between|advantage)\b/i.test(text)) return 3;
        return 0;
      };
      return relevance(right) - relevance(left) || Number(right?.retrieval_score || 0) - Number(left?.retrieval_score || 0);
    })
    .slice(0, 6);

  if (!approvedMatches.length) {
    return {
      answer: `I do not have enough approved company knowledge to answer “${String(requestText || "that question").trim()}” reliably. Add or approve the relevant information in Business Brain and I can answer it without inventing details.`,
      claims: [],
    };
  }

  const facts = approvedMatches.map((claim) => `• ${String(claim.text || "").trim()}`);
  return {
    answer: [
      "Based on the approved knowledge in this company’s Business Brain:",
      "",
      ...facts,
      "",
      "These are owner-approved company facts, not a general web answer.",
    ].join("\n"),
    claims: approvedMatches,
  };
}

async function answerAionPilotDirectQuestion(requestText = "", pilotState = getAionPilotFrontendInteractionState()) {
  const actorScope = pilotState.department_scope || getAionPilotActiveDepartmentScope() || "pilot";
  pilotState.status = "answering_question";
  pilotState.interaction_mode = "direct_answer";
  pilotState.last_request = String(requestText || "").trim();
  pilotState.draft_created = false;
  pilotState.plan = null;
  pilotState.contract_status = "not_required_read_only";
  pilotState.safe_work_status = "not_required_read_only";
  pilotState.safe_work_approved = false;
  pilotState.direct_answer_text = "Checking approved company knowledge…";
  pilotState.direct_answer_claims = [];
  pilotState.stream_events = [{
    type: "direct_question",
    label: "Read-only question received",
    detail: pilotState.last_request,
    status: "retrieving_approved_knowledge",
  }];
  requestRender?.();

  try {
    const result = await window.AionBusinessContainerClient?.searchBusinessKnowledge?.(
      pilotState.last_request,
      actorScope,
      12,
    );
    if (!result || !Array.isArray(result.matches)) {
      throw new Error("The local Business Brain search is unavailable.");
    }
    const direct = buildAionPilotDirectKnowledgeAnswer(pilotState.last_request, result.matches);
    pilotState.status = direct.claims.length ? "answered" : "knowledge_needed";
    pilotState.direct_answer_text = direct.answer;
    pilotState.direct_answer_claims = direct.claims;
    pilotState.business_knowledge_context = direct.claims;
    pilotState.business_knowledge_receipt = result.receipt || null;
    pilotState.business_knowledge_status = direct.claims.length ? "retrieved" : "no_match";
    pilotState.receipt_hash = result.receipt?.query_hash || "";
    pilotState.stream_events.push({
      type: "direct_answer",
      label: direct.claims.length ? `${direct.claims.length} approved company facts used` : "Approved knowledge is incomplete",
      detail: direct.claims.length ? "Question answered directly; no execution or approval was required." : "Pilot stopped rather than inventing a company answer.",
      status: direct.claims.length ? "source_backed" : "knowledge_needed",
    });
  } catch (error) {
    pilotState.status = "answer_unavailable";
    pilotState.business_knowledge_status = "unavailable";
    pilotState.business_knowledge_error = String(error?.message || error || "Business knowledge retrieval failed");
    pilotState.direct_answer_text = "I could not reach the local Business Brain, so I have not invented an answer. Refresh Pilot and try again.";
    pilotState.stream_events.push({
      type: "direct_answer_error",
      label: "Business Brain unavailable",
      detail: pilotState.business_knowledge_error,
      status: "stopped_safely",
    });
  }

  pilotState.command_mode = "new_mission";
  pilotState.command_input_text = "";
  requestRender?.();
  window.setTimeout(() => speakAionPilotText(pilotState.direct_answer_text), 120);
  return pilotState;
}

async function createAionPilotSafeDraft(requestText = "", pilotState = getAionPilotFrontendInteractionState()) {
  const actorScope = pilotState.department_scope || getAionPilotActiveDepartmentScope() || "pilot";
  const unsafeClaim = /(?:synthetic test material|owner must review|for owner review|prohibited wording|must not strengthen|made entirely from|every competing|rust[- ]proof for life|maintenance[- ]free|guaranteed for \d+ years|patent protected or patented|certified for any)/i;
  pilotState.status = "producing_draft";
  pilotState.interaction_mode = "safe_draft";
  pilotState.last_request = String(requestText || "").trim();
  pilotState.draft_created = true;
  pilotState.plan = buildAionPilotUniversalPlan(pilotState.last_request);
  pilotState.contract_status = "not_required_safe_draft";
  pilotState.safe_work_status = "running_safe_draft";
  pilotState.safe_work_approved = false;
  pilotState.generated_output_text = "";
  pilotState.step_outputs = [];
  pilotState.direct_answer_text = "";
  pilotState.direct_answer_claims = [];
  pilotState.stream_events = [{
    type: "safe_draft_request",
    label: "Safe draft requested",
    detail: "Creating the requested artifact now. Nothing will be sent, published or executed.",
    status: "drafting",
  }];
  requestRender?.();

  try {
    const knowledge = await window.AionBusinessContainerClient?.searchBusinessKnowledge?.(
      pilotState.last_request,
      actorScope,
      12,
    );
    const facts = (Array.isArray(knowledge?.matches) ? knowledge.matches : [])
      .filter((claim) => String(claim?.text || "").trim())
      .filter((claim) => !unsafeClaim.test(String(claim?.text || "")))
      .filter((claim, index, rows) => rows.findIndex((candidate) => String(candidate?.text || "").trim().toLowerCase() === String(claim?.text || "").trim().toLowerCase()) === index)
      .slice(0, 12)
      .map((claim) => ({
        claim_id: claim.claim_id,
        text: claim.text,
        source_hash: claim.source_hash,
        scopes: claim.scopes,
      }));
    pilotState.business_knowledge_context = facts;
    pilotState.business_knowledge_receipt = knowledge?.receipt || null;
    pilotState.business_knowledge_status = facts.length ? "retrieved" : "no_match";
    pilotState.stream_events.push({
      type: "business_knowledge_retrieval",
      label: facts.length ? `${facts.length} approved company facts recalled` : "No approved company facts matched",
      detail: facts.length ? "The drafting model may use these source-backed facts." : "The drafting model must mark company-specific gaps instead of inventing them.",
      status: facts.length ? "source_backed" : "no_match",
    });
    requestRender?.();

    const [boardroomContextResult, organisationResult] = await Promise.allSettled([
      window.AionBusinessContainerClient?.getBoardroomContext?.(),
      window.AionBusinessContainerClient?.getOrganizationAuthority?.(),
    ]);
    const boardroomEnvelope = boardroomContextResult.status === "fulfilled"
      ? (boardroomContextResult.value?.context || {})
      : {};
    const identity = boardroomEnvelope.business_identity || boardroomEnvelope.business_structure?.identity || {};
    const structureIdentity = boardroomEnvelope.business_structure?.identity || {};
    const people = organisationResult.status === "fulfilled" && Array.isArray(organisationResult.value?.model?.people)
      ? organisationResult.value.model.people
      : [];
    const sender = people.find((person) => person?.status === "active" && (person?.role_ids || []).includes("role.owner_director"))
      || people.find((person) => person?.status === "active")
      || {};
    const businessContext = {
      business_name: identity.trading_name || structureIdentity.public_brand_name || structureIdentity.business_name || "",
      legal_name: identity.legal_name || structureIdentity.legal_name || "",
      website_url: identity.website_url || structureIdentity.website_url || "",
      primary_email: identity.primary_email || structureIdentity.primary_email || "",
      business_type: identity.business_type || structureIdentity.business_type || "",
      sector: identity.sector || "",
      sender_name: sender.name || identity.owner || structureIdentity.founder_name || "",
      sender_title: sender.job_title || sender.position_title || "",
      sender_email: sender.email || identity.primary_email || structureIdentity.primary_email || "",
    };
    Object.keys(businessContext).forEach((key) => {
      if (!String(businessContext[key] || "").trim()) delete businessContext[key];
    });
    pilotState.business_identity_context = businessContext;
    pilotState.stream_events.push({
      type: "business_identity_retrieval",
      label: Object.keys(businessContext).length
        ? `${Object.keys(businessContext).length} verified business identity fields recalled`
        : "No verified business identity fields found",
      detail: Object.keys(businessContext).length
        ? "Known company and sender details will be used automatically; absent contact details remain explicit gaps."
        : "Pilot will not invent company or sender identity details.",
      status: Object.keys(businessContext).length ? "source_backed" : "no_match",
    });
    requestRender?.();

    const selectedProviders = typeof getAionLiveSelectedBoardroomProviderIdsV2 === "function"
      ? getAionLiveSelectedBoardroomProviderIdsV2()
      : [];
    const businessId = window.AionBusinessContainerClient?.resolveBusinessId?.() || "home-fixed";
    const response = await fetch("http://127.0.0.1:8080/api/boardroom/pilot-draft", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        business_id: businessId,
        request: pilotState.last_request,
        actor_scope: actorScope,
        approved_facts: facts,
        business_context: businessContext,
        requested_providers: selectedProviders,
      }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || payload.status !== "draft_ready" || !String(payload.draft || "").trim()) {
      throw new Error(payload.reason || `draft_provider_http_${response.status}`);
    }

    const outputText = String(payload.draft || "").trim();
    pilotState.status = "draft_ready";
    pilotState.safe_work_status = "completed_preview";
    pilotState.artifact_status = "draft_preview_not_sent";
    pilotState.generated_output_text = outputText;
    pilotState.artifact_hash = payload.receipt_hash || "";
    pilotState.receipt_hash = payload.receipt_hash || "";
    pilotState.draft_provider_id = payload.provider_id || "";
    pilotState.draft_provider_label = payload.provider_label || payload.provider_id || "connected model";
    pilotState.draft_model = payload.model || "";
    pilotState.business_context_fields_used = Array.isArray(payload.business_context_fields_used)
      ? payload.business_context_fields_used
      : [];
    pilotState.draft_risks = Array.isArray(payload.risks) ? payload.risks : [];
    pilotState.draft_missing_inputs = Array.isArray(payload.missing_inputs) ? payload.missing_inputs : [];
    pilotState.step_outputs = [{
      step_number: 1,
      step_id: "safe_draft_output",
      title: "Draft response",
      status: "draft_ready_not_sent",
      output_text: outputText,
      artifact_hash: payload.receipt_hash || "",
      receipt_hash: payload.receipt_hash || "",
      open: true,
    }];
    pilotState.stream_events.push({
      type: "safe_draft_ready",
      label: "Complete draft produced",
      detail: `${pilotState.draft_provider_label}${pilotState.draft_model ? ` · ${pilotState.draft_model}` : ""} · ${facts.length} approved facts and ${pilotState.business_context_fields_used.length} verified identity fields used · nothing sent`,
      status: "draft_ready_not_sent",
    });
  } catch (error) {
    pilotState.status = "draft_unavailable";
    pilotState.safe_work_status = "failed_safely";
    pilotState.generated_output_text = "";
    pilotState.step_outputs = [];
    pilotState.draft_error = String(error?.message || error || "Draft generation failed");
    pilotState.stream_events.push({
      type: "safe_draft_error",
      label: "Draft could not be produced",
      detail: `${pilotState.draft_error}. No substitute response was invented and no external action occurred.`,
      status: "stopped_safely",
    });
  }

  pilotState.command_mode = "mission_thread";
  pilotState.command_input_text = "";
  requestRender?.();
  if (pilotState.status === "draft_ready") {
    window.setTimeout(() => speakAionPilotText("The complete draft is ready for your review. Nothing has been sent."), 120);
  }
  return pilotState;
}

function parseAionPilotEmailDraft(outputText = "") {
  const text = String(outputText || "").trim();
  const subjectMatch = text.match(/^\s*Subject:\s*(.+?)\s*(?:\r?\n)+/i);
  return {
    subject: String(subjectMatch?.[1] || "Message from Aion").trim(),
    body: subjectMatch ? text.slice(subjectMatch[0].length).trim() : text,
  };
}

function extractAionPilotEmailAddress(text = "") {
  return String(text || "").match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0] || "";
}

function isAionPilotCurrentDraftSendRequest(text = "") {
  return /\b(?:send|email|message)\b/i.test(String(text || "")) &&
    /\b(?:that|this|the|current|draft|email|message)\b/i.test(String(text || ""));
}

const AION_PILOT_ACTION_CAPABILITIES = [
  { action: "email_send", label: "Send email", adapter: "Gmail", implemented: true, pattern: /\b(?:send|email)\b.*\b(?:email|message|draft|it|this|that)\b|\bsend\b.*@[a-z0-9.-]+\.[a-z]{2,}/i },
  { action: "message_send", label: "Send a chat message", adapter: "Messaging gateway", implemented: false, pattern: /\b(?:send|post)\b.*\b(?:slack|whatsapp|telegram|teams|discord|message|dm)\b/i },
  { action: "phone_call", label: "Make a phone call", adapter: "Voice / telephony gateway", implemented: false, pattern: /\b(?:call|phone|ring)\b.*\b(?:customer|client|supplier|person|them|him|her|number|phone)\b/i },
  { action: "invoice_send", label: "Send an invoice", adapter: "Accounting connector", implemented: false, pattern: /\b(?:send|issue)\b.*\binvoice\b/i },
  { action: "invoice_create", label: "Create an invoice", adapter: "Accounting connector", implemented: false, pattern: /\b(?:create|raise|prepare|make)\b.*\binvoice\b/i },
  { action: "payment", label: "Make a payment", adapter: "Payments connector", implemented: false, pattern: /\b(?:pay|settle|transfer)\b.*\b(?:invoice|bill|supplier|vendor|£|\$|€|gbp|usd|eur)\b/i },
  { action: "purchase", label: "Make a purchase", adapter: "Payments connector", implemented: false, pattern: /\b(?:buy|purchase|order)\b.*\b(?:product|stock|materials?|item|equipment|subscription)\b/i },
  { action: "publish", label: "Publish content", adapter: "Publishing connector", implemented: false, pattern: /\b(?:publish|post)\b.*\b(?:website|social|linkedin|facebook|instagram|x|content|article)\b/i },
];

function resolveAionPilotRequestedCapability(text = "") {
  const request = String(text || "").trim();
  return AION_PILOT_ACTION_CAPABILITIES.find((capability) => capability.pattern.test(request)) || null;
}

async function prepareAionPilotEmailFollowup(requestText = "", pilotState = getAionPilotFrontendInteractionState()) {
  const existing = pilotState.pending_email_action || {};
  const draft = parseAionPilotEmailDraft(existing.body ? `Subject: ${existing.subject}\n\n${existing.body}` : pilotState.generated_output_text);
  const recipient = extractAionPilotEmailAddress(requestText) || String(existing.to || "");
  pilotState.interaction_mode = "email_followup";
  pilotState.command_input_text = "";
  pilotState.pending_email_action = { ...existing, ...draft, to: recipient };
  pilotState.last_request = String(requestText || pilotState.last_request || "").trim();
  pilotState.direct_answer_text = "";
  pilotState.direct_answer_claims = [];

  if (!recipient) {
    pilotState.status = "awaiting_email_recipient";
    pilotState.email_action_error = "";
    pilotState.stream_events = [
      ...(Array.isArray(pilotState.stream_events) ? pilotState.stream_events : []),
      { type: "email_recipient_required", label: "Recipient required", detail: "Pilot retained the current draft and is waiting for the destination email address.", status: "waiting_for_user" },
    ];
    requestRender?.();
    window.setTimeout(() => speakAionPilotText("What email address should I send it to?"), 120);
    return pilotState;
  }

  pilotState.status = "preparing_email_approval";
  pilotState.email_action_error = "";
  requestRender?.();
  try {
    const gmailHealthResponse = await fetch("http://127.0.0.1:8080/api/local-node/connectors/gmail/health");
    const gmailHealth = await gmailHealthResponse.json().catch(() => ({}));
    if (!gmailHealthResponse.ok || gmailHealth.auth_status !== "connected") {
      const reason = gmailHealth.auth_status === "reauthorization_required"
        ? "Gmail needs to be reconnected in Vault before I can send this message. I have kept the draft and recipient."
        : "Gmail is not connected in Vault. I have kept the draft and recipient.";
      throw new Error(reason);
    }
    const businessId = window.AionBusinessContainerClient?.resolveBusinessId?.() || "home-fixed";
    const activeActor = window.AionSalesRevenue?.getActiveActor?.() || null;
    const response = await fetch(`http://127.0.0.1:8080/api/local-node/pilot/email/prepare?workspace_id=${encodeURIComponent(businessId)}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ to: recipient, subject: draft.subject, body: draft.body, requested_by: activeActor?.person_id || "aion_central_pilot" }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || payload.ok !== true) {
      const reason = payload.reason === "blocked_by_owner"
        ? "Email sending is disabled by your standing authority policy. I will not ask again unless you change it in Authority."
        : payload.reason;
      throw new Error(reason || `email_prepare_http_${response.status}`);
    }
    pilotState.pending_email_action = { ...pilotState.pending_email_action, to: recipient, approval_id: payload.approval_id, payload_hash: payload.payload_hash, authority: payload.authority || null };
    const standingAuthority = payload.authority?.authorized === true;
    pilotState.status = standingAuthority ? "sending_email" : "email_approval_required";
    pilotState.stream_events.push({
      type: "email_exact_payload_frozen",
      label: standingAuthority ? "Standing email authority applied" : "Exact Gmail payload ready",
      detail: `${recipient} · ${draft.subject}`,
      status: standingAuthority ? "standing_authority" : "approval_required",
    });
    if (standingAuthority) {
      requestRender?.();
      return executeAionPilotApprovedEmailSend(pilotState, false);
    }
  } catch (error) {
    pilotState.status = "email_prepare_failed";
    pilotState.email_action_error = String(error?.message || error || "Could not prepare the Gmail approval");
  }
  requestRender?.();
  return pilotState;
}

async function executeAionPilotApprovedEmailSend(pilotState = getAionPilotFrontendInteractionState(), approvalGranted = true) {
  const action = pilotState.pending_email_action || {};
  if (!action.approval_id || !action.payload_hash) return pilotState;
  pilotState.status = "sending_email";
  pilotState.email_action_error = "";
  requestRender?.();
  try {
    const businessId = window.AionBusinessContainerClient?.resolveBusinessId?.() || "home-fixed";
    const activeActor = window.AionSalesRevenue?.getActiveActor?.() || null;
    const response = await fetch(`http://127.0.0.1:8080/api/local-node/pilot/email/${encodeURIComponent(action.approval_id)}/send?workspace_id=${encodeURIComponent(businessId)}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ payload_hash: action.payload_hash, executed_by: activeActor?.person_id || "aion_central_pilot", approval_granted: approvalGranted === true }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || payload.ok !== true || payload.sent !== true) throw new Error(payload.reason || payload.error || `gmail_send_http_${response.status}`);
    pilotState.status = "email_sent";
    pilotState.email_send_receipt = payload;
    pilotState.receipt_hash = payload.receipt_hash || pilotState.receipt_hash;
    pilotState.stream_events.push({ type: "gmail_email_sent", label: "Email sent through Gmail", detail: `${action.to} · ${action.subject}${activeActor?.name ? ` · approved and sent by ${activeActor.name}` : ""}`, status: "executed_with_receipt" });
    try {
      if (action.opportunity_id && typeof window.AionSalesRevenue?.recordQuoteEmailOutcome === "function") {
        await window.AionSalesRevenue.recordQuoteEmailOutcome({
          opportunity_id: action.opportunity_id,
          to: action.to,
          subject: action.subject,
          approval_granted: approvalGranted === true,
          receipt: payload,
        });
      }
    } catch (auditError) {
      pilotState.stream_events.push({ type: "customer_quote_audit_pending", label: "Email sent; customer audit needs attention", detail: String(auditError?.message || auditError), status: "audit_write_failed" });
    }
    window.setTimeout(() => speakAionPilotText(`The email has been sent to ${action.to}.`), 120);
  } catch (error) {
    pilotState.status = "email_send_failed";
    pilotState.email_action_error = String(error?.message || error || "Gmail send failed");
  }
  requestRender?.();
  return pilotState;
}

async function createAionPilotFrontendDraftMission() {
  const pilotState = getAionPilotFrontendInteractionState();
  const recordContext = window.__aionPilotRecordContext;
  const input = recordContext?.opportunity_id
    ? document.querySelector("[data-aion-customer-scoped-pilot-runtime] [data-aion-pilot-mission-input]")
    : document.querySelector("[data-aion-pilot-mission-input]");
  const persistentInput = document.querySelector("[data-aion-phase23y-persistent-pilot-terminal-input]");
  const requestText = String(input?.value || persistentInput?.value || pilotState.last_request || "").trim() || "Build me a PDF document with X data";
  const customerVoiceTurn = window.__aionPilotLastInputWasVoice === true;
  window.__aionPilotLastInputWasVoice = false;

  const requestMode = classifyAionPilotRequestMode(requestText);
  const activePilotDepartmentScope = getAionPilotActiveDepartmentScope();
  pilotState.department_scope = ["aion", "pilot"].includes(activePilotDepartmentScope)
    ? "pilot"
    : activePilotDepartmentScope;
  if (recordContext?.opportunity_id && typeof window.AionSalesRevenue?.handlePilotInstruction === "function") {
    if (customerVoiceTurn) setAionO21ELiveMicStatus({ status: "pilot_thinking", recording: false, last_error: null });
    const scopedResult = await window.AionSalesRevenue.handlePilotInstruction(requestText, recordContext);
    if (scopedResult?.handled === true) {
      if (scopedResult.action === "prepare_quote_email") {
        pilotState.generated_output_text = `Subject: ${String(scopedResult.email_subject || "Your quotation").trim()}\n\n${String(scopedResult.email_body || "").trim()}`;
        pilotState.pending_email_action = { to: String(scopedResult.email_to || "").trim(), subject: String(scopedResult.email_subject || "Your quotation").trim(), body: String(scopedResult.email_body || "").trim(), opportunity_id: String(recordContext.opportunity_id || "").trim() };
        pilotState.last_request = requestText;
        window.__aionPilotAutoTurnTaking = false;
        return prepareAionPilotEmailFollowup(scopedResult.email_to ? `Send the quotation to ${scopedResult.email_to}` : "Send the quotation", pilotState);
      }
      pilotState.last_request = requestText;
      pilotState.command_input_text = "";
      pilotState.interaction_mode = "direct_answer";
      pilotState.status = scopedResult.status || "customer_record_updated";
      pilotState.direct_answer_text = String(scopedResult.message || "The customer record draft has been updated.");
      pilotState.direct_answer_claims = [];
      pilotState.draft_created = false;
      pilotState.record_context = { ...recordContext };
      pilotState.stream_events = [{
        type: "customer_scoped_pilot_turn",
        label: scopedResult.label || "Customer record updated",
        detail: `${recordContext.customer_name || "Selected customer"} · ${recordContext.opportunity_id}`,
        status: scopedResult.status || "customer_record_updated",
      }];
      requestRender?.();
      if (scopedResult.continue_voice === true && customerVoiceTurn) {
        window.__aionPilotVoiceConversationCancelled = false;
        window.setTimeout(() => continueAionCustomerVoiceConversation(pilotState.direct_answer_text), 120);
      } else {
        if (customerVoiceTurn) window.__aionPilotAutoTurnTaking = false;
        window.setTimeout(() => speakAionPilotText(pilotState.direct_answer_text), 120);
      }
      return pilotState;
    }
  }
  const hasRetainedDraft = Boolean(String(pilotState.generated_output_text || "").trim());
  if (
    (pilotState.interaction_mode === "email_followup" && pilotState.status === "awaiting_email_recipient") ||
    (hasRetainedDraft && isAionPilotCurrentDraftSendRequest(requestText))
  ) {
    return prepareAionPilotEmailFollowup(requestText, pilotState);
  }
  const requestedCapability = resolveAionPilotRequestedCapability(requestText);
  if (requestedCapability && requestedCapability.implemented !== true) {
    pilotState.last_request = requestText;
    pilotState.command_input_text = "";
    pilotState.interaction_mode = "capability_check";
    pilotState.status = "capability_unavailable";
    pilotState.requested_capability = requestedCapability;
    pilotState.draft_created = false;
    pilotState.direct_answer_text = "";
    pilotState.generated_output_text = "";
    pilotState.stream_events = [{
      type: "capability_resolution",
      label: requestedCapability.label,
      detail: `${requestedCapability.adapter} is required and is not yet installed as a live execution adapter.`,
      status: "capability_unavailable",
    }];
    requestRender?.();
    return pilotState;
  }
  if (requestMode.mode === "direct_answer") {
    return answerAionPilotDirectQuestion(requestText, pilotState);
  }
  if (requestMode.mode === "safe_draft") {
    return createAionPilotSafeDraft(requestText, pilotState);
  }

  pilotState.status = "plan_ready";
  if (applyAionPilotCommandBarRevisionIfActive(requestText)) {
    return pilotState;
  }

  pilotState.last_request = requestText;
  pilotState.interaction_mode = "governed_action";
  pilotState.direct_answer_text = "";
  pilotState.direct_answer_claims = [];
  pilotState.draft_created = true;
  pilotState.plan = buildAionPilotUniversalPlan(requestText);
  if (
    pilotState.department_scope !== "pilot" &&
    typeof updateAionDepartmentIntelligence === "function"
  ) {
    updateAionDepartmentIntelligence(pilotState.department_scope, {
      status: "plan_ready",
      plan: {
        title: pilotState.plan?.title || "Department Pilot plan",
        task_type: pilotState.plan?.task_type || "general_task",
        goal: requestText,
        approval_required: true,
        live_external_actions_blocked: true,
        source: "central_pilot_department_scope",
      },
      boardroom_summary: `${runtimeShared.getDepartmentLabel(pilotState.department_scope)} Pilot has prepared a scoped plan preview. No live external action has been taken.`,
      last_updated: new Date().toISOString(),
    });
  }
  pilotState.artifact_status = "draft_preview";
  pilotState.artifact_hash = "sha256:frontend_draft_artifact_preview";
  pilotState.receipt_hash = "sha256:frontend_draft_receipt_preview";
  pilotState.replay_hash = "sha256:frontend_draft_replay_preview";
  pilotState.proof_hash = "sha256:frontend_draft_proof_preview";
  pilotState.contract_status = "draft_contract";
  pilotState.safe_work_status = "waiting_approval";
  pilotState.safe_work_approved = false;
  pilotState.generated_output_text = "";
  pilotState.step_outputs = [];
  pilotState.current_step_index = 0;
  pilotState.backend_artifact_status = "";
  pilotState.backend_artifact_error = "";
  pilotState.output_panel_open = false;
  pilotState.output_panel_kind = "";
  pilotState.output_panel_title = "";
  pilotState.output_panel_body = "";
  const universalPlan = pilotState.plan || buildAionPilotUniversalPlan(requestText);

  pilotState.stream_events = [
    {
      type: "mission_composer",
      label: "Work package created",
      detail: requestText,
      status: "draft_only",
    },
    {
      type: "artifact_preview",
      label: getAionPilotOutputPreparedLabel(universalPlan),
      detail: getAionPilotOutputPreparedDetail(universalPlan),
      status: "draft_preview",
    },
    {
      type: "safety_block",
      label: "Live external actions blocked",
      detail: "No send, deploy, payment, post, booking or escrow without exact approval",
      status: "blocked",
    },
    {
      type: "central_aion_assessment_hook",
      label: "AION assessment hook prepared",
      detail: `Assessment confidence ${universalPlan.central_business_assessment?.confidence || "none"} · action proposals ${(universalPlan.central_execution_queue_proposal || []).length}`,
      status: "proposal_only",
    },
  ];

  hydrateAionPilotPlanWithBusinessKnowledge(requestText, pilotState.department_scope, pilotState);


  if (typeof fetchAionLrmPilotContextPreviewIntoPilotState === "function") {
    fetchAionLrmPilotContextPreviewIntoPilotState({
      business_id: "home-fixed",
      mission_id: "pilot_demo_pdf_mission",
      mission_run_id: "pilot_demo_run_preview",
    }).catch((error) => {
      const state = getAionPilotFrontendInteractionState();
      state.lrm_context_status = "error";
      state.lrm_context_error = String(error?.message || error || "LRM context preview failed");
      if (typeof requestRender === "function") {
        requestRender();
      }
    });
  }

  if (typeof requestRender === "function") {
    requestRender();
  }

  window.setTimeout(() => {
    speakAionPilotText(`I have prepared the ${universalPlan.title || "work package"}. Review the plan and approve only the safe work you want me to run.`);
  }, 120);

  return pilotState;
}

window.createAionPilotFrontendDraftMission = createAionPilotFrontendDraftMission;

async function hydrateAionPilotPlanWithBusinessKnowledge(requestText, actorScope = "pilot", pilotState = getAionPilotFrontendInteractionState()) {
  pilotState.business_knowledge_status = "retrieving";
  try {
    const result = await window.AionBusinessContainerClient?.searchBusinessKnowledge?.(requestText, actorScope || "pilot", 8);
    const matches = Array.isArray(result?.matches) ? result.matches : [];
    pilotState.business_knowledge_status = "retrieved";
    pilotState.business_knowledge_context = matches.map((claim) => ({
      claim_id: claim.claim_id,
      text: claim.text,
      scopes: claim.scopes,
      confidentiality: claim.confidentiality,
      source_hash: claim.source_hash,
      retrieval_score: claim.retrieval_score,
    }));
    pilotState.business_knowledge_receipt = result?.receipt || null;
    if (pilotState.plan) {
      pilotState.plan.business_knowledge_context = pilotState.business_knowledge_context;
      pilotState.plan.business_knowledge_receipt = pilotState.business_knowledge_receipt;
    }
    pilotState.stream_events = Array.isArray(pilotState.stream_events) ? pilotState.stream_events : [];
    pilotState.stream_events.push({
      type: "business_knowledge_retrieval",
      label: matches.length ? `${matches.length} approved company facts recalled` : "No approved company knowledge matched",
      detail: matches.length ? `Source-backed context attached under ${actorScope || "pilot"} permissions` : "Pilot will use the existing Business Map and identify missing knowledge instead of inventing it",
      status: matches.length ? "source_backed" : "no_match",
    });
  } catch (error) {
    pilotState.business_knowledge_status = "unavailable";
    pilotState.business_knowledge_context = [];
    pilotState.business_knowledge_error = String(error?.message || error || "Business knowledge retrieval failed");
  }
  requestRender?.();
  return pilotState.business_knowledge_context || [];
}

function renderAionPilotFrontendStreamEvents(pilotState = getAionPilotFrontendInteractionState()) {
  const events = Array.isArray(pilotState.stream_events) ? pilotState.stream_events : [];

  if (!events.length) {
    return `
      <p>Private reasoning hidden.</p>
      <p>Visible actions, receipts, paths and blocked actions will appear here.</p>
    `;
  }

  return `
    <div data-aion-pilot-visible-stream-events>
      ${events.map((event) => `
        <div class="aion-pilot-map-node" data-aion-pilot-stream-event="${escapeHtml(event.type)}">
          <strong>${escapeHtml(event.label)}</strong>
          <div class="aion-pilot-meta-row"><span>Status</span><code>${escapeHtml(event.status)}</code></div>
          <div class="aion-pilot-meta-row"><span>Detail</span><code>${escapeHtml(event.detail)}</code></div>
        </div>
      `).join("")}
    </div>
  `;
}

/* END PHASE 21N LOCK */



/* PHASE 21O LOCK: Universal Pilot task stream simple dashboard */

function classifyAionPilotUniversalTask(requestText = "") {
  const text = String(requestText || "").toLowerCase();

  const hasAny = (signals) => signals.some((signal) => text.includes(signal));

  const marketingPlanSignals = [
    "marketing plan",
    "marketing strategy",
    "marketing roadmap",
    "execute the marketing",
    "execute marketing",
    "grow the business",
    "growth plan",
    "lead generation plan",
    "lead-gen plan",
    "customer acquisition plan",
  ];

  const socialSignals = [
    "follower",
    "twitter",
    "x campaign",
    "x.com",
    "social campaign",
    "social media",
    "social content",
    "content calendar",
    "post ideas",
  ];

  const advertisingSignals = [
    "advertising",
    "advert ",
    "ad ",
    "ads ",
    "campaign",
    "facebook",
    "google",
    "meta ads",
    "google ads",
  ];

  if (hasAny(marketingPlanSignals)) {
    return {
      task_type: "marketing_plan",
      title: "Create marketing plan",
      output_label: "Marketing plan draft",
      risk_flags: ["public posting", "ad spend", "customer contact", "account access"],
    };
  }

  if (hasAny(socialSignals)) {
    return {
      task_type: "growth_social",
      title: "Grow social audience",
      output_label: "Growth plan and content drafts",
      risk_flags: ["public posting", "account access", "ad spend", "direct messaging"],
    };
  }

  if (text.includes("spreadsheet") || text.includes("model") || text.includes("forecast") || text.includes("pricing")) {
    return {
      task_type: "spreadsheet",
      title: "Create business spreadsheet",
      output_label: "Spreadsheet draft",
      risk_flags: ["financial assumptions", "commercial decision support"],
    };
  }

  if (text.includes("website") || text.includes("landing page") || text.includes("site")) {
    return {
      task_type: "website_preview",
      title: "Build website preview",
      output_label: "Website preview draft",
      risk_flags: ["deployment", "domain purchase", "public publishing"],
    };
  }

  if (hasAny(advertisingSignals)) {
    return {
      task_type: "advertising",
      title: "Create advertising campaign draft",
      output_label: "Campaign preview and ad drafts",
      risk_flags: ["ad spend", "public publishing", "account access"],
    };
  }

  if (
    text.includes("business plan") ||
    text.includes("businessplan") ||
    text.includes("business model") ||
    text.includes("business strategy")
  ) {
    return {
      task_type: "business_plan",
      title: "Create business plan",
      output_label: "Business plan draft",
      risk_flags: ["commercial assumptions", "pricing", "publishing or sending"],
    };
  }

  if (text.includes("pdf") || text.includes("document") || text.includes("report")) {
    return {
      task_type: "document",
      title: "Create document",
      output_label: "Document/PDF draft",
      risk_flags: ["source quality", "publishing or sending"],
    };
  }

  return {
    task_type: "general_task",
    title: "Complete custom business task",
    output_label: "Draft output",
    risk_flags: ["unknown external side effects", "approval boundaries"],
  };
}


/* PHASE 25H LOCK: Central AION Assessment Hook */

function buildAionCentralAssessmentInputBundle(requestText = "") {
  const foundation =
    typeof getApprovedSmallBusinessFoundationContext === "function"
      ? getApprovedSmallBusinessFoundationContext()
      : {};

  const departmentIntelligence =
    typeof getAionDepartmentIntelligence === "function"
      ? getAionDepartmentIntelligence()
      : {};

  const boardroomSnapshot =
    typeof getBoardroomSnapshot === "function"
      ? getBoardroomSnapshot()
      : {};

  const boardroomRuntime =
    typeof getBoardroomRuntime === "function"
      ? getBoardroomRuntime()
      : {};

  const assessmentFeed =
    typeof buildAionDepartmentAssessmentFeed === "function"
      ? buildAionDepartmentAssessmentFeed()
      : {};

  const crossDepartmentReview =
    typeof buildAionBoardroomCrossDepartmentReview === "function"
      ? buildAionBoardroomCrossDepartmentReview()
      : {};

  const departmentEvidence = {};
  const departmentReceipts = {};
  const departmentRuns = {};

  getAionCoreDepartmentKeys().forEach((departmentKey) => {
    const entry = departmentIntelligence[departmentKey] || {};
    departmentEvidence[departmentKey] = Array.isArray(entry.evidence) ? entry.evidence : [];
    departmentReceipts[departmentKey] = Array.isArray(entry.receipts) ? entry.receipts : [];
    departmentRuns[departmentKey] = Array.isArray(entry.runs) ? entry.runs : [];
  });

  return {
    request_text: String(requestText || "").trim(),
    business_foundation: foundation,
    department_intelligence: departmentIntelligence,
    boardroom_snapshot: boardroomSnapshot,
    boardroom_runtime: boardroomRuntime,
    department_assessment_feed: assessmentFeed,
    cross_department_review: crossDepartmentReview,
    department_evidence: departmentEvidence,
    department_receipts: departmentReceipts,
    department_runs: departmentRuns,
    runtime_runs: safeArray(boardroomRuntime.runs),
    runtime_approvals: safeArray(boardroomRuntime.approvals),
    generated_at: new Date().toISOString(),
    safety_boundary: [
      "assessment_only",
      "proposal_only",
      "approval_required_before_execution",
      "no_live_external_side_effects",
    ],
  };
}

function buildAionCentralBusinessAssessment(inputBundle = {}) {
  const foundation = asRecord(inputBundle.business_foundation) || {};
  const crossReview = asRecord(inputBundle.cross_department_review) || {};
  const feed = asRecord(inputBundle.department_assessment_feed) || {};
  const conflicts = safeArray(crossReview.conflicts);
  const missing = safeArray(crossReview.missing_departments);
  const partial = safeArray(crossReview.partial_departments);
  const complete = safeArray(crossReview.complete_departments);

  const confidence = crossReview.confidence || feed.confidence || "none";
  const businessName =
    foundation.business_name ||
    foundation.name ||
    foundation.trading_name ||
    state.workspaceId ||
    "the business";

  const recommendations = [
    ...safeArray(crossReview.opportunities),
    ...safeArray(crossReview.recommended_next_questions),
  ];

  return {
    title: `AION assessment for ${businessName}`,
    business_name: businessName,
    confidence,
    scope:
      confidence === "full"
        ? "full_business"
        : complete.length || partial.length
          ? "partial_business"
          : "insufficient_data",
    complete_departments: complete,
    partial_departments: partial,
    missing_departments: missing,
    conflicts,
    recommendations,
    summary:
      crossReview.summary ||
      (complete.length || partial.length
        ? `AION can produce a ${confidence} assessment from available department intelligence.`
        : "AION needs department discovery, plans or results before a useful business assessment."),
    created_at: new Date().toISOString(),
    no_live_external_action: true,
  };
}

function buildAionCentralApprovalRequiredActionPlan(inputBundle = {}, assessment = {}) {
  const recommendations = safeArray(assessment.recommendations);
  const conflicts = safeArray(assessment.conflicts);

  const recommendationItems = recommendations.map((item, index) => ({
    id: `central_recommendation_${index + 1}`,
    title: String(item || `Recommendation ${index + 1}`),
    source: "cross_department_review",
    approval_required: true,
    status: "proposal_only",
    no_live_external_action: true,
  }));

  const conflictItems = conflicts.map((item, index) => ({
    id: item.id || `central_conflict_${index + 1}`,
    title: item.summary || item.id || `Conflict ${index + 1}`,
    source: "cross_department_conflict",
    severity: item.severity || "medium",
    departments: safeArray(item.departments),
    approval_required: true,
    status: "proposal_only",
    no_live_external_action: true,
  }));

  return {
    status: "approval_required",
    source: "central_aion_assessment_hook",
    items: [...conflictItems, ...recommendationItems],
    approval_boundary: [
      "No emails",
      "No public posts",
      "No ad spend",
      "No bookings",
      "No payments",
      "No invoices",
      "No deployments",
      "No external writes",
    ],
    created_at: new Date().toISOString(),
  };
}

function buildAionCentralPilotExecutionQueueProposal(actionPlan = {}) {
  const items = safeArray(actionPlan.items);

  return items.map((item, index) => ({
    id: item.id || `central_pilot_proposed_task_${index + 1}`,
    title: item.title || `Central Pilot proposed task ${index + 1}`,
    source: item.source || "central_aion_assessment_hook",
    status: "waiting_human_approval",
    safety: "proposal_only",
    approval_required: true,
    no_live_external_action: true,
  }));
}

function buildAionCentralAssessmentHook(requestText = "") {
  const inputBundle = buildAionCentralAssessmentInputBundle(requestText);
  const assessment = buildAionCentralBusinessAssessment(inputBundle);
  const actionPlan = buildAionCentralApprovalRequiredActionPlan(inputBundle, assessment);
  const executionQueueProposal = buildAionCentralPilotExecutionQueueProposal(actionPlan);

  return {
    input_bundle: inputBundle,
    assessment,
    action_plan: actionPlan,
    execution_queue_proposal: executionQueueProposal,
    status: "assessment_ready",
    created_at: new Date().toISOString(),
  };
}

function renderAionCentralAssessmentHookPanel(plan = null) {
  const safePlan = plan || buildAionPilotUniversalPlan("");
  const hook =
    safePlan.central_aion_assessment_hook ||
    buildAionCentralAssessmentHook(safePlan.goal || "");

  const assessment = asRecord(hook.assessment) || {};
  const actionPlan = asRecord(hook.action_plan) || {};
  const queue = safeArray(hook.execution_queue_proposal);
  const conflicts = safeArray(assessment.conflicts);

  return `
    <section
      class="panel large-panel"
      data-aion-phase25h-central-assessment-hook="true"
      style="background:#ffffff;"
    >
      <div class="panel-title">Central AION Assessment Hook</div>
      <div class="helper-text">
        Central AION reads the business foundation, Department Intelligence Ledger, Boardroom snapshot, runs, evidence, receipts and cross-department review before proposing any action.
      </div>

      <div class="card-grid" style="margin-top:12px;">
        ${renderDashboardMetricCard("Assessment", assessment.confidence || "none", assessment.scope || "not ready")}
        ${renderDashboardMetricCard("Conflicts", conflicts.length, "Cross-department risks")}
        ${renderDashboardMetricCard("Action Plan", safeArray(actionPlan.items).length, actionPlan.status || "proposal_only")}
        ${renderDashboardMetricCard("Pilot Queue", queue.length, "Waiting approval")}
      </div>

      <div class="notice warning" style="margin-top:12px;">
        ${escapeHtml(assessment.summary || "AION assessment is waiting for department data.")}
      </div>

      ${
        queue.length
          ? `
            <div class="list-wrap" style="margin-top:12px;">
              ${queue.map((item) => `
                <div class="list-item">
                  <div class="list-item-title">${escapeHtml(item.title || "Proposed task")}</div>
                  <div class="list-item-sub">Central Pilot proposal. Human approval required before any execution.</div>
                  <div class="badge-row">
                    ${renderStatusBadge(item.status || "waiting_human_approval")}
                    <span class="badge">${escapeHtml(item.safety || "proposal_only")}</span>
                    <span class="badge">No live external action</span>
                  </div>
                </div>
              `).join("")}
            </div>
          `
          : `<div class="empty-state" style="margin-top:12px;">No central execution queue proposal yet.</div>`
      }
    </section>
  `;
}


const AION_CENTRAL_APPROVED_BOARDROOM_ACTIONS_STORAGE_KEY = "aion.centralApprovedBoardroomActions";
const AION_CENTRAL_PILOT_QUEUE_STORAGE_KEY = "aion.centralPilotQueue";

function readAionCentralPilotStorageObject(storageKey = "") {
  try {
    const raw = window.localStorage?.getItem(storageKey);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch (_error) {
    return {};
  }
}

function writeAionCentralPilotStorageObject(storageKey = "", value = {}) {
  try {
    window.localStorage?.setItem(storageKey, JSON.stringify(value || {}));
  } catch (_error) {
    // Local preview storage only.
  }
  return value || {};
}

function getAionCentralApprovedBoardroomActions() {
  const existing =
    state.centralApprovedBoardroomActions &&
    typeof state.centralApprovedBoardroomActions === "object" &&
    !Array.isArray(state.centralApprovedBoardroomActions)
      ? state.centralApprovedBoardroomActions
      : readAionCentralPilotStorageObject(AION_CENTRAL_APPROVED_BOARDROOM_ACTIONS_STORAGE_KEY);

  state.centralApprovedBoardroomActions = existing;
  return existing;
}

function saveAionCentralApprovedBoardroomActions(next = {}) {
  const value = next && typeof next === "object" && !Array.isArray(next) ? next : {};
  state.centralApprovedBoardroomActions = value;
  return writeAionCentralPilotStorageObject(AION_CENTRAL_APPROVED_BOARDROOM_ACTIONS_STORAGE_KEY, value);
}

function getAionCentralPilotQueue() {
  const existing =
    state.centralPilotQueue &&
    typeof state.centralPilotQueue === "object" &&
    !Array.isArray(state.centralPilotQueue)
      ? state.centralPilotQueue
      : readAionCentralPilotStorageObject(AION_CENTRAL_PILOT_QUEUE_STORAGE_KEY);

  state.centralPilotQueue = existing;
  return existing;
}

function saveAionCentralPilotQueue(next = {}) {
  const value = next && typeof next === "object" && !Array.isArray(next) ? next : {};
  state.centralPilotQueue = value;
  return writeAionCentralPilotStorageObject(AION_CENTRAL_PILOT_QUEUE_STORAGE_KEY, value);
}

function approveAionCentralBoardroomAction(actionId = "", sourceHook = null) {
  const id = String(actionId || "").trim();
  if (!id) return null;

  const hook = sourceHook || buildAionCentralAssessmentHook("");
  const actionPlan = asRecord(hook.action_plan) || {};
  const proposedItems = safeArray(actionPlan.items);
  const proposed = proposedItems.find((item) => String(item?.id || "") === id);

  if (!proposed) return null;

  const now = new Date().toISOString();
  const approvedActions = getAionCentralApprovedBoardroomActions();

  const approved = {
    ...proposed,
    id,
    status: "approved",
    approved_at: now,
    approved_by: "human_operator",
    source: proposed.source || "central_aion_assessment_hook",
    approval_required: true,
    no_live_external_action: true,
  };

  approvedActions[id] = approved;
  saveAionCentralApprovedBoardroomActions(approvedActions);

  const queue = buildAionCentralApprovedPilotQueue({ render: false });
  saveAionCentralPilotQueue(queue);

  if (typeof requestRender === "function") {
    requestRender();
  }

  return approved;
}

function buildAionCentralApprovedPilotQueue(options = {}) {
  const approvedActions = getAionCentralApprovedBoardroomActions();
  const existingQueue = getAionCentralPilotQueue();
  const now = new Date().toISOString();

  const tasks = Object.values(approvedActions).map((action, index) => {
    const existing = existingQueue[action.id] || {};
    return {
      ...existing,
      id: action.id || `central_approved_action_${index + 1}`,
      title: action.title || `Approved Boardroom action ${index + 1}`,
      source: action.source || "central_aion_assessment_hook",
      departments: safeArray(action.departments),
      severity: action.severity || "",
      status: existing.status || "approved_safe_preview",
      safety: "internal_preview_only",
      approval_boundary: "no_live_external_side_effects",
      approval_required: true,
      no_live_external_action: true,
      approved_at: action.approved_at || now,
      updated_at: now,
    };
  });

  const nextQueue = Object.fromEntries(tasks.map((task) => [task.id, task]));
  saveAionCentralPilotQueue(nextQueue);

  if (options.render !== false && typeof requestRender === "function") {
    requestRender();
  }

  return nextQueue;
}

function getAionCentralPilotNextApprovedTask() {
  const queue = getAionCentralPilotQueue();
  return Object.values(queue).find((item) => {
    const status = String(item?.status || "").toLowerCase();
    return status === "approved_safe_preview" || status === "queued_safe_preview";
  }) || null;
}

function runAionCentralPilotApprovedTask(taskId = "") {
  const queue = getAionCentralPilotQueue();
  const id = String(taskId || "").trim() || String(getAionCentralPilotNextApprovedTask()?.id || "");
  if (!id || !queue[id]) return null;

  const now = new Date().toISOString();
  const task = queue[id];

  const completedTask = {
    ...task,
    status: "completed_preview",
    completed_at: now,
    updated_at: now,
    result_summary: `${task.title || "Approved Boardroom action"} completed as a guarded internal preview. No live external action was taken.`,
  };

  queue[id] = completedTask;
  saveAionCentralPilotQueue(queue);

  safeArray(task.departments).forEach((departmentKey) => {
    const key = normaliseAionDepartmentPilotKey(departmentKey);
    if (!key) return;

    const ledger = getAionDepartmentIntelligence();
    const entry = ledger[key] || normaliseAionDepartmentIntelligenceEntry(key, {});
    const existingResults =
      entry.results && typeof entry.results === "object" && !Array.isArray(entry.results)
        ? entry.results
        : {};

    const resultRecord = {
      id: `${key}_${id}_central_result`,
      department_key: key,
      central_task_id: id,
      title: completedTask.title,
      status: "results_available",
      result_type: "central_boardroom_action_preview",
      summary: completedTask.result_summary,
      created_at: now,
      no_live_external_action: true,
    };

    const evidenceRecord = {
      id: `${key}_${id}_central_evidence`,
      department_key: key,
      central_task_id: id,
      evidence_type: "central_boardroom_action_result",
      title: completedTask.title,
      summary: completedTask.result_summary,
      created_at: now,
      provenance: "central_aion_assessment_hook",
    };

    const receiptRecord = {
      id: `${key}_${id}_central_receipt`,
      department_key: key,
      central_task_id: id,
      receipt_type: "central_safe_internal_preview",
      status: "draft_receipt",
      created_at: now,
      no_live_external_action: true,
    };

    updateAionDepartmentIntelligence(key, {
      status: "central_action_preview_complete",
      results: {
        ...existingResults,
        latest_central_preview: resultRecord,
        central_preview_history: [
          ...(Array.isArray(existingResults.central_preview_history) ? existingResults.central_preview_history : []),
          resultRecord,
        ],
      },
      evidence: [...(Array.isArray(entry.evidence) ? entry.evidence : []), evidenceRecord],
      receipts: [...(Array.isArray(entry.receipts) ? entry.receipts : []), receiptRecord],
      boardroom_summary: `${runtimeShared.getDepartmentLabel(key)} received central AION approved action result: ${completedTask.title}. No live external action was taken.`,
      confidence: "useful",
      last_updated: now,
    });
  });

  const pilotState =
    typeof getAionPilotFrontendInteractionState === "function"
      ? getAionPilotFrontendInteractionState()
      : null;

  if (pilotState) {
    pilotState.status = "central_approved_task_completed";
    pilotState.central_pilot_queue = queue;
    pilotState.stream_events = [
      ...(Array.isArray(pilotState.stream_events) ? pilotState.stream_events : []),
      {
        type: "central_approved_boardroom_action",
        label: "Approved Boardroom action completed",
        detail: completedTask.result_summary,
        status: "completed_preview",
      },
    ];
  }

  if (typeof requestRender === "function") {
    requestRender();
  }

  return completedTask;
}


/* AION GOAL LOOP CANVAS PHASE D3: Central Pilot Safe Task Queue from Goal Loop Graph */
function getAionActiveGoalLoopGraphForCentralPilotQueue() {
  const graph =
    (typeof window !== "undefined" && window.__aionWorkflowGraph) ||
    (typeof window !== "undefined" && window.__aionGoalLoopWorkflowGraph) ||
    null;

  const isGoalLoop =
    graph?.canvas_type === "goal_loop" ||
    graph?.active_canvas_intent === "goal_loop" ||
    graph?.goal_loop_contract?.goal_loop_id;

  return isGoalLoop ? graph : null;
}

function buildAionGoalLoopCentralPilotTaskQueue() {
  const graph = getAionActiveGoalLoopGraphForCentralPilotQueue();
  const nodes = Array.isArray(graph?.nodes) ? graph.nodes : [];

  const businessLabel =
    typeof getAionWorkflowCanvasHeaderBusinessLabel === "function"
      ? getAionWorkflowCanvasHeaderBusinessLabel()
      : "Business status pending verification";

  const businessContainer =
    typeof getAionWorkflowBusinessContainerId === "function"
      ? getAionWorkflowBusinessContainerId()
      : "business_not_registered";

  const goalLoopId = String(graph?.goal_loop_id || graph?.goal_loop_contract?.goal_loop_id || "not_staged");
  const boardGoal = graph?.goal_loop_contract?.board_goal || {};
  const boardGoalTitle = String(boardGoal.title || boardGoal.goal || "No Boardroom goal staged");

  const agentTaskNodes = nodes.filter((node) => {
    const type = String(node?.node_type || node?.type || node?.data?.node_type || node?.data?.type || "").trim();
    return type === "agent_task";
  });

  const tasks = agentTaskNodes.map((node, index) => {
    const department = normaliseAionDepartmentPilotKey(
      node?.department ||
      node?.data?.department ||
      node?.meta?.department ||
      node?.config?.department ||
      node?.config?.department_goal?.department ||
      "pilot"
    );

    const title = String(node?.title || node?.label || `${department} Goal Loop task`);
    const departmentContext =
      typeof getAionActiveGoalLoopDepartmentContext === "function"
        ? getAionActiveGoalLoopDepartmentContext(department)
        : null;

    return {
      id: String(node?.id || `${goalLoopId}_${department}_central_safe_task_${index + 1}`),
      source_node_id: String(node?.id || ""),
      source_node_type: "agent_task",
      source: "goal_loop_graph_agent_task",
      goal_loop_id: goalLoopId,
      board_goal: boardGoalTitle,
      business_label: businessLabel,
      business_container: businessContainer,
      department,
      department_label:
        typeof runtimeShared !== "undefined" && runtimeShared.getDepartmentLabel
          ? runtimeShared.getDepartmentLabel(department)
          : department,
      department_child_canvas_id: String(departmentContext?.child_canvas_id || node?.child_canvas_id || ""),
      title,
      detail: String(
        node?.description ||
        node?.detail ||
        node?.config?.detail ||
        node?.config?.department_goal?.sub_goal ||
        departmentContext?.department_sub_goal ||
        "Safe internal Goal Loop task preview."
      ),
      status: "waiting_human_approval",
      queue_status: "preview_ready",
      lane: "goal_loop_safe_internal_task",
      safety: "internal_preview_only",
      approval_required: true,
      preview_only: true,
      execution_blocked: true,
      no_live_external_action: true,
      external_side_effects: false,
      message_sent: false,
      booking_created: false,
      payment_created: false,
      persistence_required: false,
      route_mutation_required: false,
      creates_second_pilot: false,
      creates_second_canvas: false,
    };
  });

  const grouped = tasks.reduce((acc, task) => {
    const key = task.department || "pilot";
    acc[key] = acc[key] || [];
    acc[key].push(task);
    return acc;
  }, {});

  return {
    schema_version: "aion.goal_loop.central_pilot_safe_task_queue.v1",
    status: graph ? "goal_loop_safe_queue_ready" : "no_active_goal_loop",
    business_label: businessLabel,
    business_container: businessContainer,
    goal_loop_id: goalLoopId,
    board_goal: boardGoalTitle,
    task_count: tasks.length,
    departments: Object.keys(grouped),
    tasks,
    grouped_by_department: grouped,
    preview_only: true,
    approval_required: true,
    execution_blocked: true,
    no_live_external_action: true,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    persistence_required: false,
    route_mutation_required: false,
    uses_existing_central_pilot: true,
    creates_second_pilot: false,
    creates_second_canvas: false,
  };
}

function getAionGoalLoopCentralPilotTaskQueue() {
  const queue = buildAionGoalLoopCentralPilotTaskQueue();

  if (typeof window !== "undefined") {
    const pilotState =
      typeof getAionPilotFrontendInteractionState === "function"
        ? getAionPilotFrontendInteractionState()
        : null;

    if (pilotState) {
      pilotState.goal_loop_central_safe_task_queue = queue;
      pilotState.goal_loop_central_safe_task_queue_status = queue.status;
    }
  }

  return queue;
}


/* AION GOAL LOOP CANVAS PHASE D4: Department Task Queue Writeback Preview */
const AION_GOAL_LOOP_DEPARTMENT_TASK_STATUS_VALUES = [
  "staged",
  "awaiting_approval",
  "approved",
  "running",
  "blocked",
  "completed",
  "failed",
];

function buildAionGoalLoopDepartmentTaskQueueWritebackPatch(departmentKey = "", options = {}) {
  const key = normaliseAionDepartmentPilotKey(departmentKey);
  const queue =
    options.queue && typeof options.queue === "object"
      ? options.queue
      : typeof getAionGoalLoopCentralPilotTaskQueue === "function"
        ? getAionGoalLoopCentralPilotTaskQueue()
        : { grouped_by_department: {}, tasks: [] };

  const grouped = queue.grouped_by_department && typeof queue.grouped_by_department === "object"
    ? queue.grouped_by_department
    : {};

  const tasks = Array.isArray(grouped[key])
    ? grouped[key]
    : Array.isArray(queue.tasks)
      ? queue.tasks.filter((task) => normaliseAionDepartmentPilotKey(task?.department || "") === key)
      : [];

  const existingEntry =
    typeof getAionDepartmentLedgerEntry === "function"
      ? getAionDepartmentLedgerEntry(key)
      : typeof getAionDepartmentPilotLedgerEntry === "function"
        ? getAionDepartmentPilotLedgerEntry(key)
        : {};

  const existingTasks = Array.isArray(existingEntry?.tasks) ? existingEntry.tasks : [];
  const now = new Date().toISOString();

  const previewTasks = tasks.map((task, index) => ({
    id: String(task.id || `${key}_goal_loop_preview_task_${index + 1}`),
    title: String(task.title || `Goal Loop task ${index + 1}`),
    detail: String(task.detail || "Goal Loop safe internal task preview."),
    department_key: key,
    source: "goal_loop_central_pilot_safe_queue",
    source_goal_loop_id: String(task.goal_loop_id || queue.goal_loop_id || "not_staged"),
    source_node_id: String(task.source_node_id || ""),
    source_node_type: String(task.source_node_type || "agent_task"),
    department_child_canvas_id: String(task.department_child_canvas_id || ""),
    status: "staged",
    task_status_values: AION_GOAL_LOOP_DEPARTMENT_TASK_STATUS_VALUES,
    approval_state: "awaiting_approval",
    approval_required: true,
    safety: "internal_preview_only",
    preview_only: true,
    execution_blocked: true,
    no_live_external_action: true,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    persistence_required: false,
    ledger_mutation_required: false,
    route_mutation_required: false,
    provenance: {
      source: "goal_loop_graph_agent_task",
      generated_by: "central_pilot_goal_loop_queue_preview",
      department_key: key,
      preview_generated_at: now,
      business_container: String(task.business_container || queue.business_container || "business_not_registered"),
      business_label: String(task.business_label || queue.business_label || "Business status pending verification"),
    },
  }));

  const mergedPreviewTasks = [
    ...existingTasks,
    ...previewTasks,
  ];

  return {
    schema_version: "aion.goal_loop.department_task_queue_writeback_preview.v1",
    department_key: key,
    business_label: String(queue.business_label || "Business status pending verification"),
    business_container: String(queue.business_container || "business_not_registered"),
    goal_loop_id: String(queue.goal_loop_id || "not_staged"),
    board_goal: String(queue.board_goal || "No Boardroom goal staged"),
    status: previewTasks.length ? "writeback_preview_ready" : "no_goal_loop_tasks_for_department",
    task_status_values: AION_GOAL_LOOP_DEPARTMENT_TASK_STATUS_VALUES,
    preview_task_count: previewTasks.length,
    existing_task_count: existingTasks.length,
    resulting_task_count_preview: mergedPreviewTasks.length,
    preview_tasks: previewTasks,
    ledger_patch_preview: {
      status: previewTasks.length ? "goal_loop_task_queue_preview_ready" : existingEntry?.status || "no_goal_loop_task_queue",
      department_key: key,
      tasks: mergedPreviewTasks,
      goal_loop_task_queue_preview: {
        goal_loop_id: String(queue.goal_loop_id || "not_staged"),
        board_goal: String(queue.board_goal || "No Boardroom goal staged"),
        task_count: previewTasks.length,
        generated_at: now,
        source: "central_pilot_goal_loop_safe_task_queue",
      },
      boardroom_summary: previewTasks.length
        ? `${runtimeShared.getDepartmentLabel(key)} has ${previewTasks.length} Goal Loop task preview(s) staged for review. No ledger mutation or live external action has occurred.`
        : `${runtimeShared.getDepartmentLabel(key)} has no Goal Loop task previews staged.`,
      last_updated_preview: now,
    },
    goal_loop_graph_patch_preview: {
      goal_loop_id: String(queue.goal_loop_id || "not_staged"),
      department_key: key,
      node_status_updates: previewTasks.map((task) => ({
        node_id: task.source_node_id,
        status: "staged",
        approval_state: "awaiting_approval",
        writeback_preview: true,
        updated_at: now,
      })),
      progress_rollup_patch: {
        department: key,
        status: previewTasks.length ? "tasks_staged_preview" : "no_tasks_staged",
        task_count: previewTasks.length,
        completed_task_count: 0,
        evidence_count: 0,
        confidence: previewTasks.length ? "partial" : "unknown",
        last_updated_preview: now,
      },
    },
    preview_only: true,
    execution_blocked: true,
    persistence_required: false,
    ledger_mutation_required: false,
    route_mutation_required: false,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    uses_existing_department_ledger: true,
    uses_existing_central_pilot: true,
    creates_second_pilot: false,
    creates_second_canvas: false,
  };
}

function previewAionGoalLoopDepartmentTaskQueueWriteback(options = {}) {
  const queue =
    options.queue && typeof options.queue === "object"
      ? options.queue
      : typeof getAionGoalLoopCentralPilotTaskQueue === "function"
        ? getAionGoalLoopCentralPilotTaskQueue()
        : { grouped_by_department: {}, tasks: [] };

  const departments = Object.keys(queue.grouped_by_department || {});
  const patches = departments.map((department) =>
    buildAionGoalLoopDepartmentTaskQueueWritebackPatch(department, { queue })
  );

  const preview = {
    schema_version: "aion.goal_loop.department_task_queue_writeback_preview_bundle.v1",
    status: patches.length ? "department_writeback_preview_ready" : "no_department_writeback_preview",
    business_label: String(queue.business_label || "Business status pending verification"),
    business_container: String(queue.business_container || "business_not_registered"),
    goal_loop_id: String(queue.goal_loop_id || "not_staged"),
    board_goal: String(queue.board_goal || "No Boardroom goal staged"),
    department_count: patches.length,
    total_preview_task_count: patches.reduce((total, patch) => total + Number(patch.preview_task_count || 0), 0),
    patches,
    preview_only: true,
    execution_blocked: true,
    persistence_required: false,
    ledger_mutation_required: false,
    route_mutation_required: false,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    uses_existing_department_ledger: true,
    uses_existing_central_pilot: true,
    creates_second_pilot: false,
    creates_second_canvas: false,
  };

  if (typeof window !== "undefined") {
    window.__aionGoalLoopDepartmentTaskQueueWritebackPreview = preview;

    const pilotState =
      typeof getAionPilotFrontendInteractionState === "function"
        ? getAionPilotFrontendInteractionState()
        : null;

    if (pilotState) {
      pilotState.goal_loop_department_task_queue_writeback_preview = preview;
      pilotState.goal_loop_department_task_queue_writeback_preview_status = preview.status;
    }
  }

  return preview;
}


/* AION GOAL LOOP CANVAS PHASE E1: Measurement Schema */
const AION_GOAL_LOOP_METRIC_TRENDS = [
  "improving",
  "flat",
  "declining",
  "unknown",
];

const AION_GOAL_LOOP_METRIC_CONFIDENCE_LEVELS = [
  "unknown",
  "partial",
  "verified",
];

const AION_GOAL_LOOP_METRIC_SOURCES = [
  "manual",
  "connector_placeholder",
];

function buildAionGoalLoopMetricSchema(overrides = {}) {
  const department = normaliseAionDepartmentPilotKey(overrides.department || "marketing");
  const goalId = String(overrides.goal_id || overrides.goalId || "goal_not_staged");
  const sourceNodeId = String(overrides.source_node_id || overrides.sourceNodeId || "");

  return {
    schema_version: "aion.goal_loop_metric.v1",
    metric_id: String(overrides.metric_id || overrides.metricId || `${goalId}_${department}_metric_preview`),
    goal_id: goalId,
    department,
    source_node_id: sourceNodeId,
    name: String(overrides.name || "goal_loop_metric"),
    target: overrides.target ?? null,
    actual: overrides.actual ?? null,
    unit: String(overrides.unit || ""),
    trend: AION_GOAL_LOOP_METRIC_TRENDS.includes(String(overrides.trend || "unknown"))
      ? String(overrides.trend || "unknown")
      : "unknown",
    confidence: AION_GOAL_LOOP_METRIC_CONFIDENCE_LEVELS.includes(String(overrides.confidence || "unknown"))
      ? String(overrides.confidence || "unknown")
      : "unknown",
    source: AION_GOAL_LOOP_METRIC_SOURCES.includes(String(overrides.source || "manual"))
      ? String(overrides.source || "manual")
      : "manual",
    evidence_ids: Array.isArray(overrides.evidence_ids) ? overrides.evidence_ids.map(String) : [],
    status: String(overrides.status || "schema_only"),
    manual_entry_supported: true,
    connector_placeholder_supported: true,
    connector_call_required: false,
    preview_only: true,
    execution_blocked: true,
    persistence_required: false,
    external_side_effects: false,
  };
}

function buildAionGoalLoopDepartmentMetricSet(departmentKey = "", options = {}) {
  const key = normaliseAionDepartmentPilotKey(departmentKey);
  const graph =
    options.graph && typeof options.graph === "object"
      ? options.graph
      : typeof getAionActiveGoalLoopGraphForCentralPilotQueue === "function"
        ? getAionActiveGoalLoopGraphForCentralPilotQueue()
        : null;

  const nodes = Array.isArray(graph?.nodes) ? graph.nodes : [];
  const goalId = String(graph?.goal_loop_contract?.board_goal?.goal_id || graph?.goal_loop_id || graph?.goal_loop_contract?.goal_loop_id || "goal_not_staged");

  const measurementNodes = nodes.filter((node) => {
    const nodeDepartment = normaliseAionDepartmentPilotKey(
      node?.department ||
      node?.data?.department ||
      node?.meta?.department ||
      node?.config?.department ||
      node?.config?.department_goal?.department ||
      ""
    );
    const nodeType = String(node?.node_type || node?.type || node?.data?.node_type || node?.data?.type || "");
    return nodeDepartment === key && nodeType === "measurement_plan";
  });

  const fallbackMetric = buildAionGoalLoopMetricSchema({
    metric_id: `${goalId}_${key}_manual_metric_placeholder`,
    goal_id: goalId,
    department: key,
    source_node_id: measurementNodes[0]?.id || "",
    name: `${key}_goal_progress`,
    target: null,
    actual: null,
    unit: "",
    trend: "unknown",
    confidence: "unknown",
    source: "manual",
    evidence_ids: [],
  });

  const metrics = measurementNodes.length
    ? measurementNodes.map((node, index) => buildAionGoalLoopMetricSchema({
        metric_id: `${goalId}_${key}_metric_${index + 1}`,
        goal_id: goalId,
        department: key,
        source_node_id: node.id || "",
        name: String(node?.config?.metric_name || node?.metric_name || node?.title || `${key}_metric_${index + 1}`)
          .toLowerCase()
          .replace(/[^a-z0-9]+/g, "_")
          .replace(/^_+|_+$/g, "")
          .slice(0, 80) || `${key}_metric_${index + 1}`,
        target: node?.config?.target ?? null,
        actual: null,
        unit: String(node?.config?.unit || ""),
        trend: "unknown",
        confidence: "unknown",
        source: "manual",
        evidence_ids: [],
      }))
    : [fallbackMetric];

  return {
    schema_version: "aion.goal_loop_department_metric_set.v1",
    department: key,
    goal_id: goalId,
    source: "goal_loop_measurement_plan_nodes",
    metric_count: metrics.length,
    metrics,
    manual_entry_supported: true,
    connector_placeholder_supported: true,
    connector_call_required: false,
    preview_only: true,
    execution_blocked: true,
    persistence_required: false,
    external_side_effects: false,
  };
}

function attachAionGoalLoopMetricsToGraph(options = {}) {
  const graph =
    options.graph && typeof options.graph === "object"
      ? options.graph
      : typeof getAionActiveGoalLoopGraphForCentralPilotQueue === "function"
        ? getAionActiveGoalLoopGraphForCentralPilotQueue()
        : null;

  const departments = Array.isArray(graph?.department_child_canvases)
    ? graph.department_child_canvases.map((canvas) => normaliseAionDepartmentPilotKey(canvas.department || "")).filter(Boolean)
    : ["marketing", "sales", "finance", "operations", "support"];

  const uniqueDepartments = Array.from(new Set(departments));
  const metricSets = uniqueDepartments.map((department) =>
    buildAionGoalLoopDepartmentMetricSet(department, { graph })
  );

  const metrics = metricSets.flatMap((set) => Array.isArray(set.metrics) ? set.metrics : []);

  const attachment = {
    schema_version: "aion.goal_loop_measurement_attachment.v1",
    status: graph ? "measurement_schema_attached_preview" : "no_active_goal_loop",
    goal_loop_id: String(graph?.goal_loop_id || graph?.goal_loop_contract?.goal_loop_id || "not_staged"),
    department_count: uniqueDepartments.length,
    metric_count: metrics.length,
    metric_trends: AION_GOAL_LOOP_METRIC_TRENDS,
    metric_confidence_levels: AION_GOAL_LOOP_METRIC_CONFIDENCE_LEVELS,
    metric_sources: AION_GOAL_LOOP_METRIC_SOURCES,
    department_metric_sets: metricSets,
    goal_loop_metrics: metrics,
    manual_entry_supported: true,
    connector_placeholder_supported: true,
    connector_call_required: false,
    preview_only: true,
    execution_blocked: true,
    persistence_required: false,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
  };

  if (graph && typeof graph === "object") {
    graph.goal_loop_metrics = metrics;
    graph.goal_loop_metric_sets = metricSets;
    graph.goal_loop_measurement_attachment = attachment;

    if (graph.goal_loop_contract && typeof graph.goal_loop_contract === "object") {
      graph.goal_loop_contract.goal_loop_metrics = metrics;
      graph.goal_loop_contract.goal_loop_metric_sets = metricSets;
    }

    if (typeof window !== "undefined") {
      window.__aionGoalLoopMeasurementAttachment = attachment;
      window.__aionWorkflowGraph = graph;
      window.__aionGoalLoopWorkflowGraph = graph;
    }
  }

  return attachment;
}


/* AION GOAL LOOP CANVAS PHASE E2: Manual Result Capture Preview */
function buildAionGoalLoopManualResultSnapshot(options = {}) {
  const attachment =
    options.attachment && typeof options.attachment === "object"
      ? options.attachment
      : typeof attachAionGoalLoopMetricsToGraph === "function"
        ? attachAionGoalLoopMetricsToGraph()
        : { goal_loop_metrics: [], goal_loop_id: "not_staged" };

  const metrics = Array.isArray(attachment.goal_loop_metrics) ? attachment.goal_loop_metrics : [];
  const selectedMetric = options.metric && typeof options.metric === "object"
    ? options.metric
    : metrics[0] || buildAionGoalLoopMetricSchema({});

  const department = normaliseAionDepartmentPilotKey(options.department || selectedMetric.department || "marketing");
  const now = new Date().toISOString();
  const actualValue = options.actual ?? selectedMetric.actual ?? "";
  const confidence = AION_GOAL_LOOP_METRIC_CONFIDENCE_LEVELS.includes(String(options.confidence || "partial"))
    ? String(options.confidence || "partial")
    : "partial";

  return {
    schema_version: "aion.goal_loop_manual_result_snapshot.v1",
    result_id: String(options.result_id || `${selectedMetric.metric_id || "metric"}_manual_result_preview`),
    goal_loop_id: String(options.goal_loop_id || attachment.goal_loop_id || "not_staged"),
    goal_id: String(selectedMetric.goal_id || "goal_not_staged"),
    metric_id: String(selectedMetric.metric_id || ""),
    department,
    source_node_id: String(selectedMetric.source_node_id || ""),
    metric_name: String(selectedMetric.name || "goal_loop_metric"),
    target: selectedMetric.target ?? null,
    actual: actualValue,
    unit: String(selectedMetric.unit || ""),
    confidence,
    note: String(options.note || "Manual result preview. Replace with real value during approved capture."),
    evidence_note: String(options.evidence_note || "Evidence placeholder. Attach proof/evidence in later phase."),
    evidence_ids: Array.isArray(options.evidence_ids) ? options.evidence_ids.map(String) : [],
    source: "manual",
    capture_mode: "manual_preview",
    status: "manual_result_preview",
    captured_at_preview: now,
    preview_only: true,
    connector_call_required: false,
    ledger_mutation_required: false,
    persistence_required: false,
    execution_blocked: true,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
    provenance: {
      source: "goal_loop_manual_result_capture_preview",
      generated_by: "aion_goal_loop_phase_e2",
      generated_at: now,
      department,
      metric_id: String(selectedMetric.metric_id || ""),
    },
  };
}

function previewAionGoalLoopManualResultCapture(options = {}) {
  const attachment =
    options.attachment && typeof options.attachment === "object"
      ? options.attachment
      : typeof attachAionGoalLoopMetricsToGraph === "function"
        ? attachAionGoalLoopMetricsToGraph()
        : { goal_loop_metrics: [], goal_loop_id: "not_staged" };

  const metrics = Array.isArray(attachment.goal_loop_metrics) ? attachment.goal_loop_metrics : [];
  const snapshots = metrics.map((metric) =>
    buildAionGoalLoopManualResultSnapshot({
      ...options,
      metric,
      department: metric.department,
      attachment,
    })
  );

  const resultSnapshots = snapshots.length
    ? snapshots
    : [buildAionGoalLoopManualResultSnapshot({ ...options, attachment })];

  const graphResultPatchPreview = {
    schema_version: "aion.goal_loop_manual_result_graph_patch_preview.v1",
    goal_loop_id: String(attachment.goal_loop_id || "not_staged"),
    result_count: resultSnapshots.length,
    result_node_updates: resultSnapshots.map((result) => ({
      result_id: result.result_id,
      metric_id: result.metric_id,
      department: result.department,
      source_node_id: result.source_node_id,
      status: "manual_result_preview",
      actual: result.actual,
      confidence: result.confidence,
      evidence_ids: result.evidence_ids,
      writeback_preview: true,
      updated_at_preview: result.captured_at_preview,
    })),
    preview_only: true,
    persistence_required: false,
    execution_blocked: true,
  };

  const departmentLedgerResultPatchPreview = resultSnapshots.reduce((acc, result) => {
    const key = normaliseAionDepartmentPilotKey(result.department || "");
    acc[key] = acc[key] || {
      department_key: key,
      status: "manual_result_preview_ready",
      results: [],
      boardroom_summary: `${runtimeShared.getDepartmentLabel(key)} has manual Goal Loop result preview(s). No ledger mutation has occurred.`,
      ledger_mutation_required: false,
      persistence_required: false,
      preview_only: true,
    };

    acc[key].results.push({
      result_id: result.result_id,
      metric_id: result.metric_id,
      metric_name: result.metric_name,
      actual: result.actual,
      target: result.target,
      unit: result.unit,
      confidence: result.confidence,
      note: result.note,
      evidence_note: result.evidence_note,
      source: "manual",
      status: "manual_result_preview",
      captured_at_preview: result.captured_at_preview,
    });

    return acc;
  }, {});

  const boardroomResultPreview = {
    schema_version: "aion.goal_loop_boardroom_manual_result_preview.v1",
    goal_loop_id: String(attachment.goal_loop_id || "not_staged"),
    status: resultSnapshots.length ? "manual_results_ready_for_boardroom_preview" : "no_manual_results",
    result_count: resultSnapshots.length,
    departments: Object.keys(departmentLedgerResultPatchPreview),
    summary: `${resultSnapshots.length} manual result preview(s) prepared for Boardroom review. No execution or persistence has occurred.`,
    requires_review: true,
    preview_only: true,
  };

  const preview = {
    schema_version: "aion.goal_loop_manual_result_capture_preview.v1",
    status: "manual_result_capture_preview_ready",
    goal_loop_id: String(attachment.goal_loop_id || "not_staged"),
    result_snapshots: resultSnapshots,
    graph_result_patch_preview: graphResultPatchPreview,
    department_ledger_result_patch_preview: departmentLedgerResultPatchPreview,
    boardroom_result_preview: boardroomResultPreview,
    preview_only: true,
    connector_call_required: false,
    ledger_mutation_required: false,
    persistence_required: false,
    execution_blocked: true,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
  };

  if (typeof window !== "undefined") {
    window.__aionGoalLoopManualResultCapturePreview = preview;
  }

  return preview;
}


/* AION GOAL LOOP CANVAS PHASE E3: Evaluation Engine Preview */
const AION_GOAL_LOOP_EVALUATION_STATUSES = [
  "on_track",
  "off_track",
  "blocked",
  "unknown",
  "complete",
];

const AION_GOAL_LOOP_EVALUATION_NEXT_ACTIONS = [
  "continue_loop",
  "propose_ab_test",
  "pause_loop",
  "mark_complete",
  "request_more_data",
];

function evaluateAionGoalLoopMetricResult(result = {}, metric = {}) {
  const safeResult = result && typeof result === "object" && !Array.isArray(result) ? result : {};
  const safeMetric = metric && typeof metric === "object" && !Array.isArray(metric) ? metric : {};

  const targetRaw = safeResult.target ?? safeMetric.target;
  const actualRaw = safeResult.actual ?? safeMetric.actual;
  const target = Number(targetRaw);
  const actual = Number(actualRaw);
  const hasTarget = targetRaw !== null && targetRaw !== "" && Number.isFinite(target);
  const hasActual = actualRaw !== null && actualRaw !== "" && Number.isFinite(actual);

  const confidence = AION_GOAL_LOOP_METRIC_CONFIDENCE_LEVELS.includes(String(safeResult.confidence || safeMetric.confidence || "unknown"))
    ? String(safeResult.confidence || safeMetric.confidence || "unknown")
    : "unknown";

  const department = normaliseAionDepartmentPilotKey(safeResult.department || safeMetric.department || "marketing");
  const metricName = String(safeResult.metric_name || safeMetric.name || "goal_loop_metric");
  const unit = String(safeResult.unit || safeMetric.unit || "");

  if (!hasTarget || !hasActual) {
    return {
      status: "unknown",
      reason: `Metric ${metricName} does not have both a target and an actual value yet.`,
      recommendation: "Request more data before deciding whether the loop is working.",
      next_action: "request_more_data",
      confidence,
      department,
      metric_id: String(safeResult.metric_id || safeMetric.metric_id || ""),
      goal_id: String(safeResult.goal_id || safeMetric.goal_id || "goal_not_staged"),
      evidence_ids: Array.isArray(safeResult.evidence_ids) ? safeResult.evidence_ids.map(String) : [],
      target: targetRaw ?? null,
      actual: actualRaw ?? null,
      unit,
      preview_only: true,
    };
  }

  const lowerIsBetter = /cost|spend|complaint|cancel|churn|delay|time|defect|refund|risk/i.test(metricName);
  const isComplete = lowerIsBetter ? actual <= target : actual >= target;
  const delta = actual - target;
  const deltaAbs = Math.abs(delta);
  const deltaPct = target === 0 ? null : delta / target;

  if (isComplete) {
    return {
      status: "on_track",
      reason: lowerIsBetter
        ? `${metricName} is at or below target (${actual}${unit ? ` ${unit}` : ""} vs ${target}${unit ? ` ${unit}` : ""}).`
        : `${metricName} is at or above target (${actual}${unit ? ` ${unit}` : ""} vs ${target}${unit ? ` ${unit}` : ""}).`,
      recommendation: "Continue the current loop and keep measuring before scaling decisions.",
      next_action: confidence === "verified" ? "mark_complete" : "continue_loop",
      confidence,
      department,
      metric_id: String(safeResult.metric_id || safeMetric.metric_id || ""),
      goal_id: String(safeResult.goal_id || safeMetric.goal_id || "goal_not_staged"),
      evidence_ids: Array.isArray(safeResult.evidence_ids) ? safeResult.evidence_ids.map(String) : [],
      target,
      actual,
      unit,
      delta,
      delta_abs: deltaAbs,
      delta_pct: deltaPct,
      preview_only: true,
    };
  }

  return {
    status: "off_track",
    reason: lowerIsBetter
      ? `${metricName} is above target (${actual}${unit ? ` ${unit}` : ""} vs ${target}${unit ? ` ${unit}` : ""}).`
      : `${metricName} is below target (${actual}${unit ? ` ${unit}` : ""} vs ${target}${unit ? ` ${unit}` : ""}).`,
    recommendation: "Propose an improvement loop or A/B test before increasing commitment.",
    next_action: "propose_ab_test",
    confidence,
    department,
    metric_id: String(safeResult.metric_id || safeMetric.metric_id || ""),
    goal_id: String(safeResult.goal_id || safeMetric.goal_id || "goal_not_staged"),
    evidence_ids: Array.isArray(safeResult.evidence_ids) ? safeResult.evidence_ids.map(String) : [],
    target,
    actual,
    unit,
    delta,
    delta_abs: deltaAbs,
    delta_pct: deltaPct,
    preview_only: true,
  };
}

function buildAionGoalLoopEvaluationPreview(options = {}) {
  const manualPreview =
    options.manual_preview && typeof options.manual_preview === "object"
      ? options.manual_preview
      : typeof previewAionGoalLoopManualResultCapture === "function"
        ? previewAionGoalLoopManualResultCapture()
        : { result_snapshots: [], goal_loop_id: "not_staged" };

  const resultSnapshots = Array.isArray(manualPreview.result_snapshots) ? manualPreview.result_snapshots : [];
  const now = new Date().toISOString();

  const evaluations = resultSnapshots.map((result, index) => {
    const evaluation = evaluateAionGoalLoopMetricResult(result, {});
    return {
      schema_version: "aion.goal_loop_evaluation.v1",
      evaluation_id: String(options.evaluation_id || `${result.result_id || "result"}_evaluation_preview_${index + 1}`),
      goal_loop_id: String(manualPreview.goal_loop_id || result.goal_loop_id || "not_staged"),
      goal_id: evaluation.goal_id,
      department: evaluation.department,
      metric_id: evaluation.metric_id,
      status: evaluation.status,
      reason: evaluation.reason,
      recommendation: evaluation.recommendation,
      next_action: evaluation.next_action,
      confidence: evaluation.confidence,
      target: evaluation.target ?? null,
      actual: evaluation.actual ?? null,
      unit: evaluation.unit || "",
      evidence_ids: evaluation.evidence_ids,
      source_result_id: String(result.result_id || ""),
      evaluated_at_preview: now,
      preview_only: true,
      graph_mutation_required: false,
      persistence_required: false,
      execution_blocked: true,
      external_side_effects: false,
      provenance: {
        source: "goal_loop_manual_result_capture_preview",
        generated_by: "aion_goal_loop_phase_e3",
        generated_at: now,
      },
    };
  });

  const statusCounts = evaluations.reduce((acc, evaluation) => {
    acc[evaluation.status] = (acc[evaluation.status] || 0) + 1;
    return acc;
  }, {});

  const nextActionCounts = evaluations.reduce((acc, evaluation) => {
    acc[evaluation.next_action] = (acc[evaluation.next_action] || 0) + 1;
    return acc;
  }, {});

  const boardroomEvaluationSummary = {
    schema_version: "aion.goal_loop_boardroom_evaluation_summary.v1",
    goal_loop_id: String(manualPreview.goal_loop_id || "not_staged"),
    status: evaluations.length ? "evaluation_preview_ready" : "no_evaluation_inputs",
    evaluation_count: evaluations.length,
    status_counts: statusCounts,
    next_action_counts: nextActionCounts,
    requires_board_review: evaluations.some((item) => ["off_track", "blocked", "unknown"].includes(item.status)),
    recommended_board_action:
      nextActionCounts.propose_ab_test ? "review_ab_test_proposals" :
      nextActionCounts.request_more_data ? "request_more_data" :
      nextActionCounts.pause_loop ? "review_pause" :
      nextActionCounts.mark_complete ? "review_completion" :
      "continue_loop",
    preview_only: true,
  };

  const preview = {
    schema_version: "aion.goal_loop_evaluation_preview_bundle.v1",
    status: evaluations.length ? "evaluation_preview_ready" : "no_evaluation_inputs",
    goal_loop_id: String(manualPreview.goal_loop_id || "not_staged"),
    evaluation_statuses: AION_GOAL_LOOP_EVALUATION_STATUSES,
    evaluation_next_actions: AION_GOAL_LOOP_EVALUATION_NEXT_ACTIONS,
    evaluation_count: evaluations.length,
    evaluations,
    boardroom_evaluation_summary: boardroomEvaluationSummary,
    graph_evaluation_patch_preview: {
      goal_loop_id: String(manualPreview.goal_loop_id || "not_staged"),
      evaluation_node_updates: evaluations.map((evaluation) => ({
        evaluation_id: evaluation.evaluation_id,
        department: evaluation.department,
        metric_id: evaluation.metric_id,
        status: evaluation.status,
        next_action: evaluation.next_action,
        confidence: evaluation.confidence,
        writeback_preview: true,
        updated_at_preview: now,
      })),
      preview_only: true,
      graph_mutation_required: false,
    },
    preview_only: true,
    graph_mutation_required: false,
    persistence_required: false,
    execution_blocked: true,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
  };

  if (typeof window !== "undefined") {
    window.__aionGoalLoopEvaluationPreview = preview;
  }

  return preview;
}


/* AION GOAL LOOP CANVAS PHASE F1: A/B Test Node Support */
const AION_GOAL_LOOP_AB_TEST_LIFECYCLE_STATUSES = [
  "proposed",
  "approved",
  "running",
  "measuring",
  "evaluated",
  "winner_selected",
  "next_test_proposed",
  "complete",
];

function buildAionGoalLoopAbTestNode(options = {}) {
  const evaluationPreview =
    options.evaluation_preview && typeof options.evaluation_preview === "object"
      ? options.evaluation_preview
      : typeof buildAionGoalLoopEvaluationPreview === "function"
        ? buildAionGoalLoopEvaluationPreview()
        : { evaluations: [], goal_loop_id: "not_staged" };

  const evaluations = Array.isArray(evaluationPreview.evaluations) ? evaluationPreview.evaluations : [];
  const sourceEvaluation =
    options.evaluation && typeof options.evaluation === "object"
      ? options.evaluation
      : evaluations.find((item) => item.next_action === "propose_ab_test") || evaluations[0] || {};

  const department = normaliseAionDepartmentPilotKey(options.department || sourceEvaluation.department || "marketing");
  const now = new Date().toISOString();

  return {
    schema_version: "aion.goal_loop_ab_test_node.v1",
    node_id: String(options.node_id || `${sourceEvaluation.evaluation_id || "evaluation"}_ab_test_preview`),
    node_type: "ab_test",
    goal_loop_id: String(options.goal_loop_id || evaluationPreview.goal_loop_id || sourceEvaluation.goal_loop_id || "not_staged"),
    goal_id: String(options.goal_id || sourceEvaluation.goal_id || "goal_not_staged"),
    department,
    source_evaluation_id: String(sourceEvaluation.evaluation_id || ""),
    source_metric_id: String(sourceEvaluation.metric_id || ""),
    title: String(options.title || `${runtimeShared.getDepartmentLabel(department)} A/B test preview`),
    hypothesis: String(
      options.hypothesis ||
      sourceEvaluation.recommendation ||
      "Testing a controlled variant may improve the Goal Loop metric before scaling."
    ),
    variant_a: {
      id: "variant_a",
      label: String(options.variant_a_label || "Current approach"),
      description: String(options.variant_a_description || "Baseline/control version of the current loop."),
    },
    variant_b: {
      id: "variant_b",
      label: String(options.variant_b_label || "Improvement variant"),
      description: String(options.variant_b_description || "Proposed changed version to test against the baseline."),
    },
    success_metric: {
      metric_id: String(options.metric_id || sourceEvaluation.metric_id || ""),
      name: String(options.success_metric || sourceEvaluation.metric_id || "goal_loop_success_metric"),
      target: sourceEvaluation.target ?? null,
      unit: String(sourceEvaluation.unit || ""),
      confidence: String(sourceEvaluation.confidence || "partial"),
    },
    test_duration: String(options.test_duration || "7 days preview"),
    lifecycle_status: "proposed",
    approval_state: "awaiting_board_approval",
    result_capture_placeholder: {
      status: "not_captured",
      variant_a_actual: null,
      variant_b_actual: null,
      confidence: "unknown",
      evidence_ids: [],
      preview_only: true,
    },
    winner_decision_placeholder: {
      status: "not_selected",
      winner: "unknown",
      reason: "Winner can only be selected after approved measurement.",
      preview_only: true,
    },
    next_variant_proposal_placeholder: {
      status: "not_proposed",
      proposal: "",
      preview_only: true,
    },
    boardroom_ab_summary: {
      status: "ab_test_proposal_ready",
      required_board_decision: "Approve, adjust, reject or request more data before running any test.",
      summary: `${runtimeShared.getDepartmentLabel(department)} has an A/B test proposal linked to the Goal Loop evaluation.`,
      preview_only: true,
    },
    created_at_preview: now,
    preview_only: true,
    approval_required: true,
    campaign_launch_required: false,
    connector_call_required: false,
    execution_blocked: true,
    persistence_required: false,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
    provenance: {
      source: "goal_loop_evaluation_preview",
      generated_by: "aion_goal_loop_phase_f1",
      generated_at: now,
      source_evaluation_id: String(sourceEvaluation.evaluation_id || ""),
      department,
    },
  };
}

function buildAionGoalLoopAbTestLifecyclePreview(options = {}) {
  const evaluationPreview =
    options.evaluation_preview && typeof options.evaluation_preview === "object"
      ? options.evaluation_preview
      : typeof buildAionGoalLoopEvaluationPreview === "function"
        ? buildAionGoalLoopEvaluationPreview()
        : { evaluations: [], goal_loop_id: "not_staged" };

  const evaluations = Array.isArray(evaluationPreview.evaluations) ? evaluationPreview.evaluations : [];
  const abCandidates = evaluations.filter((evaluation) =>
    evaluation.next_action === "propose_ab_test" ||
    evaluation.status === "off_track"
  );

  const nodes = (abCandidates.length ? abCandidates : evaluations.slice(0, 1)).map((evaluation) =>
    buildAionGoalLoopAbTestNode({ evaluation, evaluation_preview: evaluationPreview })
  );

  const lifecycleSteps = AION_GOAL_LOOP_AB_TEST_LIFECYCLE_STATUSES.map((status, index) => ({
    step_index: index + 1,
    status,
    label: status.replace(/_/g, " "),
    preview_only: true,
    approval_required: ["approved", "running", "measuring"].includes(status),
    execution_blocked: true,
  }));

  const preview = {
    schema_version: "aion.goal_loop_ab_test_lifecycle_preview.v1",
    status: nodes.length ? "ab_test_lifecycle_preview_ready" : "no_ab_test_candidates",
    goal_loop_id: String(evaluationPreview.goal_loop_id || "not_staged"),
    lifecycle_statuses: AION_GOAL_LOOP_AB_TEST_LIFECYCLE_STATUSES,
    lifecycle_steps: lifecycleSteps,
    ab_test_count: nodes.length,
    ab_test_nodes: nodes,
    boardroom_ab_summary: {
      schema_version: "aion.goal_loop_boardroom_ab_summary.v1",
      goal_loop_id: String(evaluationPreview.goal_loop_id || "not_staged"),
      status: nodes.length ? "ab_test_proposals_ready_for_boardroom" : "no_ab_test_proposals",
      proposal_count: nodes.length,
      required_board_review: nodes.length > 0,
      summary: nodes.length
        ? `${nodes.length} A/B test proposal(s) are ready for Boardroom review. No test has been launched.`
        : "No A/B test proposals are ready yet.",
      preview_only: true,
    },
    graph_ab_test_patch_preview: {
      goal_loop_id: String(evaluationPreview.goal_loop_id || "not_staged"),
      ab_test_node_additions: nodes.map((node) => ({
        node_id: node.node_id,
        node_type: "ab_test",
        department: node.department,
        source_evaluation_id: node.source_evaluation_id,
        lifecycle_status: node.lifecycle_status,
        approval_state: node.approval_state,
        writeback_preview: true,
      })),
      preview_only: true,
      graph_mutation_required: false,
    },
    preview_only: true,
    approval_required: true,
    campaign_launch_required: false,
    connector_call_required: false,
    execution_blocked: true,
    persistence_required: false,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
  };

  if (typeof window !== "undefined") {
    window.__aionGoalLoopAbTestLifecyclePreview = preview;
  }

  return preview;
}


/* AION GOAL LOOP CANVAS PHASE F2: Generate A/B Test from Evaluation */
function buildAionGoalLoopAbTestProposalFromEvaluation(evaluation = {}, options = {}) {
  const safeEvaluation =
    evaluation && typeof evaluation === "object" && !Array.isArray(evaluation)
      ? evaluation
      : {};

  const department = normaliseAionDepartmentPilotKey(
    options.department ||
    safeEvaluation.department ||
    "marketing"
  );

  const now = new Date().toISOString();
  const evaluationId = String(safeEvaluation.evaluation_id || options.evaluation_id || "evaluation_preview");
  const goalLoopId = String(options.goal_loop_id || safeEvaluation.goal_loop_id || "not_staged");
  const goalId = String(options.goal_id || safeEvaluation.goal_id || "goal_not_staged");
  const metricId = String(options.metric_id || safeEvaluation.metric_id || "");
  const recommendation = String(
    options.recommendation ||
    safeEvaluation.recommendation ||
    "Test a controlled improvement before scaling."
  );

  const variantA = {
    id: "variant_a",
    label: String(options.variant_a_label || "Current approach"),
    description: String(
      options.variant_a_description ||
      "Keep the current department loop unchanged as the control."
    ),
    source: "baseline",
    preview_only: true,
  };

  const variantB = {
    id: "variant_b",
    label: String(options.variant_b_label || "Recommended improvement"),
    description: String(
      options.variant_b_description ||
      recommendation ||
      "Apply the recommended improvement as the challenger variant."
    ),
    source: "evaluation_recommendation",
    preview_only: true,
  };

  return {
    schema_version: "aion.goal_loop_ab_test_generated_from_evaluation.v1",
    proposal_id: String(options.proposal_id || `${evaluationId}_generated_ab_test_preview`),
    node_id: String(options.node_id || `${evaluationId}_ab_test_generated_node_preview`),
    node_type: "ab_test",
    goal_loop_id: goalLoopId,
    goal_id: goalId,
    department,
    source_evaluation_id: evaluationId,
    source_metric_id: metricId,
    source_status: String(safeEvaluation.status || "unknown"),
    source_next_action: String(safeEvaluation.next_action || "propose_ab_test"),
    title: String(options.title || `${runtimeShared.getDepartmentLabel(department)} generated A/B test`),
    hypothesis: String(
      options.hypothesis ||
      `If ${runtimeShared.getDepartmentLabel(department)} applies the recommended improvement, the Goal Loop metric should move closer to target.`
    ),
    variant_a: variantA,
    variant_b: variantB,
    success_metric: {
      metric_id: metricId,
      name: String(options.success_metric || metricId || "goal_loop_success_metric"),
      target: safeEvaluation.target ?? null,
      actual_baseline: safeEvaluation.actual ?? null,
      unit: String(safeEvaluation.unit || ""),
      confidence: String(safeEvaluation.confidence || "partial"),
    },
    test_duration: String(options.test_duration || "7 days preview"),
    approval_requirement: {
      required: true,
      required_by: "boardroom",
      reason: "Generated A/B test proposals must be reviewed before execution.",
      approval_state: "awaiting_board_approval",
    },
    boardroom_review_item: {
      schema_version: "aion.goal_loop_boardroom_review_item.v1",
      review_id: String(options.review_id || `${evaluationId}_ab_test_boardroom_review`),
      review_type: "generated_ab_test_proposal",
      status: "needs_board_decision",
      title: `Review generated A/B test for ${runtimeShared.getDepartmentLabel(department)}`,
      summary: recommendation,
      required_decision: "Approve, adjust, reject or request more data.",
      source_evaluation_id: evaluationId,
      goal_loop_id: goalLoopId,
      department,
      preview_only: true,
    },
    graph_patch_preview: {
      goal_loop_id: goalLoopId,
      add_node: {
        node_id: String(options.node_id || `${evaluationId}_ab_test_generated_node_preview`),
        node_type: "ab_test",
        department,
        source_evaluation_id: evaluationId,
        source_metric_id: metricId,
        approval_state: "awaiting_board_approval",
        preview_only: true,
      },
      add_edges: [
        {
          from: evaluationId,
          to: String(options.node_id || `${evaluationId}_ab_test_generated_node_preview`),
          relation: "proposes_ab_test",
          preview_only: true,
        },
      ],
      preview_only: true,
      graph_mutation_required: false,
    },
    created_at_preview: now,
    preview_only: true,
    approval_required: true,
    campaign_launch_required: false,
    connector_call_required: false,
    execution_blocked: true,
    persistence_required: false,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
    provenance: {
      source: "goal_loop_evaluation_preview",
      generated_by: "aion_goal_loop_phase_f2",
      generated_at: now,
      source_evaluation_id: evaluationId,
      department,
    },
  };
}

function previewAionGoalLoopGeneratedAbTestsFromEvaluation(options = {}) {
  const evaluationPreview =
    options.evaluation_preview && typeof options.evaluation_preview === "object"
      ? options.evaluation_preview
      : typeof buildAionGoalLoopEvaluationPreview === "function"
        ? buildAionGoalLoopEvaluationPreview()
        : { evaluations: [], goal_loop_id: "not_staged" };

  const evaluations = Array.isArray(evaluationPreview.evaluations)
    ? evaluationPreview.evaluations
    : [];

  const candidates = evaluations.filter((evaluation) =>
    evaluation.next_action === "propose_ab_test" ||
    evaluation.status === "off_track"
  );

  const generatedProposals = candidates.map((evaluation) =>
    buildAionGoalLoopAbTestProposalFromEvaluation(evaluation, {
      goal_loop_id: evaluationPreview.goal_loop_id || evaluation.goal_loop_id || "not_staged",
    })
  );

  const preview = {
    schema_version: "aion.goal_loop_generated_ab_tests_from_evaluation_preview.v1",
    status: generatedProposals.length
      ? "generated_ab_test_proposals_ready"
      : "no_generated_ab_test_candidates",
    goal_loop_id: String(evaluationPreview.goal_loop_id || "not_staged"),
    source_evaluation_count: evaluations.length,
    candidate_count: candidates.length,
    generated_proposal_count: generatedProposals.length,
    generated_ab_test_proposals: generatedProposals,
    boardroom_review_items: generatedProposals.map((proposal) => proposal.boardroom_review_item),
    graph_patch_preview: {
      goal_loop_id: String(evaluationPreview.goal_loop_id || "not_staged"),
      node_additions: generatedProposals.map((proposal) => proposal.graph_patch_preview.add_node),
      edge_additions: generatedProposals.flatMap((proposal) => proposal.graph_patch_preview.add_edges),
      preview_only: true,
      graph_mutation_required: false,
    },
    preview_only: true,
    approval_required: true,
    campaign_launch_required: false,
    connector_call_required: false,
    execution_blocked: true,
    persistence_required: false,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
  };

  if (typeof window !== "undefined") {
    window.__aionGoalLoopGeneratedAbTestsFromEvaluationPreview = preview;
  }

  return preview;
}


/* AION GOAL LOOP CANVAS PHASE G1: Feedback to Boardroom Node */
function buildAionGoalLoopFeedbackToBoardNode(input = {}, options = {}) {
  const safeInput = input && typeof input === "object" && !Array.isArray(input) ? input : {};
  const now = new Date().toISOString();

  const evaluationPreview =
    options.evaluation_preview && typeof options.evaluation_preview === "object"
      ? options.evaluation_preview
      : typeof buildAionGoalLoopEvaluationPreview === "function"
        ? buildAionGoalLoopEvaluationPreview()
        : { evaluations: [], goal_loop_id: "not_staged" };

  const generatedAbPreview =
    options.generated_ab_preview && typeof options.generated_ab_preview === "object"
      ? options.generated_ab_preview
      : typeof previewAionGoalLoopGeneratedAbTestsFromEvaluation === "function"
        ? previewAionGoalLoopGeneratedAbTestsFromEvaluation({ evaluation_preview: evaluationPreview })
        : { generated_ab_test_proposals: [] };

  const evaluations = Array.isArray(evaluationPreview.evaluations)
    ? evaluationPreview.evaluations
    : [];

  const generatedProposals = Array.isArray(generatedAbPreview.generated_ab_test_proposals)
    ? generatedAbPreview.generated_ab_test_proposals
    : [];

  const sourceEvaluation =
    safeInput.evaluation && typeof safeInput.evaluation === "object"
      ? safeInput.evaluation
      : evaluations.find((item) => ["off_track", "blocked", "unknown"].includes(item.status)) ||
        evaluations[0] ||
        {};

  const department = normaliseAionDepartmentPilotKey(
    safeInput.department ||
    sourceEvaluation.department ||
    "marketing"
  );

  const departmentEvaluations = evaluations.filter((item) =>
    normaliseAionDepartmentPilotKey(item.department || "") === department
  );

  const departmentProposals = generatedProposals.filter((item) =>
    normaliseAionDepartmentPilotKey(item.department || "") === department
  );

  const goalLoopId = String(
    safeInput.goal_loop_id ||
    evaluationPreview.goal_loop_id ||
    sourceEvaluation.goal_loop_id ||
    "not_staged"
  );

  const goalId = String(
    safeInput.goal_id ||
    sourceEvaluation.goal_id ||
    departmentEvaluations[0]?.goal_id ||
    "goal_not_staged"
  );

  const feedbackId = String(
    safeInput.feedback_id ||
    `${goalLoopId}_${department}_feedback_to_board_preview`
  );

  const metrics = departmentEvaluations.map((evaluation) => ({
    metric_id: String(evaluation.metric_id || ""),
    status: String(evaluation.status || "unknown"),
    target: evaluation.target ?? null,
    actual: evaluation.actual ?? null,
    unit: String(evaluation.unit || ""),
    confidence: String(evaluation.confidence || "unknown"),
    next_action: String(evaluation.next_action || "request_more_data"),
    preview_only: true,
  }));

  const risks = departmentEvaluations
    .filter((evaluation) => ["off_track", "blocked", "unknown"].includes(evaluation.status))
    .map((evaluation) => ({
      risk_id: `${evaluation.evaluation_id || evaluation.metric_id || "metric"}_risk_preview`,
      severity:
        evaluation.status === "blocked"
          ? "high"
          : evaluation.status === "off_track"
            ? "medium"
            : "low",
      summary: String(evaluation.reason || "Metric needs review."),
      recommendation: String(evaluation.recommendation || "Request Boardroom review."),
      preview_only: true,
    }));

  const evidenceIds = Array.from(new Set(
    departmentEvaluations.flatMap((evaluation) =>
      Array.isArray(evaluation.evidence_ids) ? evaluation.evidence_ids.map(String) : []
    )
  ));

  const needsAttention = departmentEvaluations.some((evaluation) =>
    ["off_track", "blocked", "unknown"].includes(evaluation.status)
  );

  const hasGeneratedAb = departmentProposals.length > 0;

  const status = String(
    safeInput.status ||
    (needsAttention ? "needs_attention" : "on_track")
  );

  const recommendation = String(
    safeInput.recommendation ||
    departmentProposals[0]?.boardroom_review_item?.summary ||
    sourceEvaluation.recommendation ||
    (needsAttention
      ? "Review department loop before scaling."
      : "Continue the current department loop and keep measuring.")
  );

  const requiredDecision = String(
    safeInput.required_board_decision ||
    (hasGeneratedAb
      ? "Approve, adjust, reject or request more data for the generated A/B test."
      : needsAttention
        ? "Decide whether to continue, adjust, pause or request more data."
        : "Confirm whether the department loop should continue or be marked complete.")
  );

  return {
    schema_version: "aion.goal_loop_feedback_to_board.v1",
    feedback_id: feedbackId,
    node_id: String(safeInput.node_id || `${feedbackId}_node`),
    node_type: "feedback_to_board",
    goal_loop_id: goalLoopId,
    goal_id: goalId,
    department,
    department_status: status,
    summary: String(
      safeInput.summary ||
      `${runtimeShared.getDepartmentLabel(department)} feedback is ready for Boardroom review.`
    ),
    metrics,
    risks,
    evidence_ids: evidenceIds,
    recommendation,
    required_board_decision: requiredDecision,
    source_evaluation_ids: departmentEvaluations.map((evaluation) => String(evaluation.evaluation_id || "")),
    source_ab_test_proposal_ids: departmentProposals.map((proposal) => String(proposal.proposal_id || "")),
    boardroom_review_item: {
      schema_version: "aion.goal_loop_boardroom_review_item.v1",
      review_id: String(safeInput.review_id || `${feedbackId}_boardroom_review`),
      review_type: "department_feedback_to_board",
      status: "needs_board_decision",
      title: `Review ${runtimeShared.getDepartmentLabel(department)} feedback`,
      summary: String(
        safeInput.summary ||
        `${runtimeShared.getDepartmentLabel(department)} has submitted Goal Loop feedback.`
      ),
      required_decision: requiredDecision,
      goal_loop_id: goalLoopId,
      goal_id: goalId,
      department,
      evidence_ids: evidenceIds,
      preview_only: true,
    },
    graph_patch_preview: {
      goal_loop_id: goalLoopId,
      add_or_update_node: {
        node_id: String(safeInput.node_id || `${feedbackId}_node`),
        node_type: "feedback_to_board",
        department,
        status,
        required_board_decision: requiredDecision,
        preview_only: true,
      },
      add_edges: [
        ...departmentEvaluations.map((evaluation) => ({
          from: String(evaluation.evaluation_id || evaluation.metric_id || "evaluation_preview"),
          to: String(safeInput.node_id || `${feedbackId}_node`),
          relation: "reports_feedback_to_board",
          preview_only: true,
        })),
        ...departmentProposals.map((proposal) => ({
          from: String(proposal.node_id || proposal.proposal_id || "ab_test_proposal_preview"),
          to: String(safeInput.node_id || `${feedbackId}_node`),
          relation: "included_in_board_feedback",
          preview_only: true,
        })),
      ],
      preview_only: true,
      graph_mutation_required: false,
    },
    created_at_preview: now,
    updated_at_preview: now,
    preview_only: true,
    graph_mutation_required: false,
    persistence_required: false,
    execution_blocked: true,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
    provenance: {
      source: "goal_loop_department_evaluation_preview",
      generated_by: "aion_goal_loop_phase_g1",
      generated_at: now,
      department,
      source_evaluation_count: departmentEvaluations.length,
      source_ab_test_proposal_count: departmentProposals.length,
    },
  };
}

function previewAionGoalLoopFeedbackToBoard(options = {}) {
  const evaluationPreview =
    options.evaluation_preview && typeof options.evaluation_preview === "object"
      ? options.evaluation_preview
      : typeof buildAionGoalLoopEvaluationPreview === "function"
        ? buildAionGoalLoopEvaluationPreview()
        : { evaluations: [], goal_loop_id: "not_staged" };

  const evaluations = Array.isArray(evaluationPreview.evaluations)
    ? evaluationPreview.evaluations
    : [];

  const departments = Array.from(new Set(
    evaluations
      .map((evaluation) => normaliseAionDepartmentPilotKey(evaluation.department || "marketing"))
      .filter(Boolean)
  ));

  const safeDepartments = departments.length
    ? departments
    : ["marketing", "sales", "finance", "operations", "support"];

  const feedbackNodes = safeDepartments.map((department) =>
    buildAionGoalLoopFeedbackToBoardNode({ department }, {
      evaluation_preview: evaluationPreview,
    })
  );

  const preview = {
    schema_version: "aion.goal_loop_feedback_to_board_preview.v1",
    status: feedbackNodes.length ? "feedback_to_board_preview_ready" : "no_feedback_available",
    goal_loop_id: String(evaluationPreview.goal_loop_id || "not_staged"),
    department_count: safeDepartments.length,
    feedback_count: feedbackNodes.length,
    feedback_nodes: feedbackNodes,
    boardroom_review_items: feedbackNodes.map((node) => node.boardroom_review_item),
    graph_patch_preview: {
      goal_loop_id: String(evaluationPreview.goal_loop_id || "not_staged"),
      node_updates: feedbackNodes.map((node) => node.graph_patch_preview.add_or_update_node),
      edge_additions: feedbackNodes.flatMap((node) => node.graph_patch_preview.add_edges),
      preview_only: true,
      graph_mutation_required: false,
    },
    preview_only: true,
    graph_mutation_required: false,
    persistence_required: false,
    execution_blocked: true,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
  };

  if (typeof window !== "undefined") {
    window.__aionGoalLoopFeedbackToBoardPreview = preview;
  }

  return preview;
}


/* AION GOAL LOOP CANVAS PHASE G2: Boardroom Decision on Feedback */
const AION_GOAL_LOOP_BOARDROOM_FEEDBACK_DECISIONS = [
  "accept",
  "reject",
  "adjust",
  "request_more_data",
];

function normaliseAionGoalLoopBoardroomFeedbackDecision(value = "") {
  const decision = String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");

  return AION_GOAL_LOOP_BOARDROOM_FEEDBACK_DECISIONS.includes(decision)
    ? decision
    : "request_more_data";
}

function buildAionGoalLoopBoardroomFeedbackDecision(feedbackNode = {}, options = {}) {
  const safeFeedback =
    feedbackNode && typeof feedbackNode === "object" && !Array.isArray(feedbackNode)
      ? feedbackNode
      : {};

  const now = new Date().toISOString();
  const department = normaliseAionDepartmentPilotKey(
    options.department ||
    safeFeedback.department ||
    "marketing"
  );

  const decision = normaliseAionGoalLoopBoardroomFeedbackDecision(
    options.decision ||
    safeFeedback.decision ||
    "request_more_data"
  );

  const goalLoopId = String(options.goal_loop_id || safeFeedback.goal_loop_id || "not_staged");
  const goalId = String(options.goal_id || safeFeedback.goal_id || "goal_not_staged");
  const feedbackId = String(options.feedback_id || safeFeedback.feedback_id || `${department}_feedback_preview`);
  const decisionId = String(options.decision_id || `${feedbackId}_${decision}_board_decision_preview`);

  const decisionLabels = {
    accept: "Boardroom accepts the department feedback and continues the loop.",
    reject: "Boardroom rejects the proposed department feedback path.",
    adjust: "Boardroom adjusts the department loop before continuation.",
    request_more_data: "Boardroom requests more data before deciding.",
  };

  const continuationPath = {
    accept: "continue_loop",
    reject: "pause_or_rework_loop",
    adjust: "create_board_adjustment",
    request_more_data: "request_more_data",
  }[decision];

  return {
    schema_version: "aion.goal_loop_boardroom_feedback_decision.v1",
    decision_id: decisionId,
    node_id: String(options.node_id || `${decisionId}_node`),
    node_type: "board_adjustment",
    goal_loop_id: goalLoopId,
    goal_id: goalId,
    feedback_id: feedbackId,
    department,
    decision,
    decision_label: decisionLabels[decision],
    decision_note: String(
      options.decision_note ||
      safeFeedback.required_board_decision ||
      decisionLabels[decision]
    ),
    continuation_path: continuationPath,
    adjustment_summary: String(
      options.adjustment_summary ||
      (decision === "adjust"
        ? "Adjust the department loop before continuing."
        : "")
    ),
    requested_data: decision === "request_more_data"
      ? [
          "latest_metric_value",
          "confidence_label",
          "supporting_evidence",
        ]
      : [],
    boardroom_action_preview: {
      action_type: "boardroom_feedback_decision",
      allowed_actions: AION_GOAL_LOOP_BOARDROOM_FEEDBACK_DECISIONS,
      selected_action: decision,
      status: "decision_preview_ready",
      approval_required: decision === "accept" || decision === "adjust",
      execution_allowed: false,
      preview_only: true,
    },
    graph_patch_preview: {
      goal_loop_id: goalLoopId,
      update_feedback_node: {
        node_id: String(safeFeedback.node_id || feedbackId),
        feedback_id: feedbackId,
        boardroom_decision: decision,
        boardroom_decision_id: decisionId,
        status: decision === "reject" ? "rejected" : "board_reviewed",
        preview_only: true,
      },
      add_or_update_node: {
        node_id: String(options.node_id || `${decisionId}_node`),
        node_type: "board_adjustment",
        department,
        decision,
        continuation_path: continuationPath,
        preview_only: true,
      },
      add_edges: [
        {
          from: String(safeFeedback.node_id || feedbackId),
          to: String(options.node_id || `${decisionId}_node`),
          relation: "board_decides_feedback",
          preview_only: true,
        },
      ],
      preview_only: true,
      graph_mutation_required: false,
    },
    audit_preview: {
      schema_version: "aion.goal_loop_boardroom_decision_audit_preview.v1",
      actor: "boardroom",
      source: "feedback_to_board",
      decision_id: decisionId,
      feedback_id: feedbackId,
      department,
      decision,
      created_at_preview: now,
      provenance_required: true,
      receipt_required_on_persistence: true,
      preview_only: true,
    },
    created_at_preview: now,
    updated_at_preview: now,
    preview_only: true,
    graph_mutation_required: false,
    persistence_required: false,
    execution_blocked: true,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
    provenance: {
      source: "goal_loop_feedback_to_board_preview",
      generated_by: "aion_goal_loop_phase_g2",
      generated_at: now,
      feedback_id: feedbackId,
      department,
      decision,
    },
  };
}

function previewAionGoalLoopBoardroomFeedbackDecision(options = {}) {
  const feedbackPreview =
    options.feedback_preview && typeof options.feedback_preview === "object"
      ? options.feedback_preview
      : typeof previewAionGoalLoopFeedbackToBoard === "function"
        ? previewAionGoalLoopFeedbackToBoard()
        : { feedback_nodes: [], goal_loop_id: "not_staged" };

  const feedbackNodes = Array.isArray(feedbackPreview.feedback_nodes)
    ? feedbackPreview.feedback_nodes
    : [];

  const decisions = feedbackNodes.map((feedbackNode) =>
    buildAionGoalLoopBoardroomFeedbackDecision(feedbackNode, {
      decision:
        feedbackNode.department_status === "needs_attention"
          ? "adjust"
          : "accept",
      goal_loop_id: feedbackPreview.goal_loop_id || feedbackNode.goal_loop_id || "not_staged",
    })
  );

  const preview = {
    schema_version: "aion.goal_loop_boardroom_feedback_decision_preview.v1",
    status: decisions.length
      ? "boardroom_feedback_decisions_preview_ready"
      : "no_feedback_decisions_available",
    goal_loop_id: String(feedbackPreview.goal_loop_id || "not_staged"),
    feedback_count: feedbackNodes.length,
    decision_count: decisions.length,
    allowed_actions: AION_GOAL_LOOP_BOARDROOM_FEEDBACK_DECISIONS,
    decisions,
    board_adjustment_nodes: decisions.map((decision) => decision.graph_patch_preview.add_or_update_node),
    graph_patch_preview: {
      goal_loop_id: String(feedbackPreview.goal_loop_id || "not_staged"),
      feedback_updates: decisions.map((decision) => decision.graph_patch_preview.update_feedback_node),
      node_updates: decisions.map((decision) => decision.graph_patch_preview.add_or_update_node),
      edge_additions: decisions.flatMap((decision) => decision.graph_patch_preview.add_edges),
      preview_only: true,
      graph_mutation_required: false,
    },
    audit_previews: decisions.map((decision) => decision.audit_preview),
    preview_only: true,
    graph_mutation_required: false,
    persistence_required: false,
    execution_blocked: true,
    external_side_effects: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
  };

  if (typeof window !== "undefined") {
    window.__aionGoalLoopBoardroomFeedbackDecisionPreview = preview;
  }

  return preview;
}


