    artifact_id: `${goalLoopId}_${item.artifact_type}_${index + 1}_persistence_plan`,
    business_container_id: businessContainerId,
    goal_loop_id: goalLoopId,
    write_required_now: false,
    persistence_preview_only: true,
    preview_only: true,
