    business_container_id: businessContainerId,
    goal_loop_id: goalLoopId,
    container_path: `${businessContainerId}/aion/goal-loops/${goalLoopId}/departments/${department}`,
    stores: [
      "department_canvas",
      "department_tasks",
      "department_metrics",
      "department_results",
      "department_feedback",
    ],
    write_required_now: false,
