/* AION GOAL LOOP CANVAS PHASE M2: Boardroom Decision Capture Preview */
const AION_GOAL_LOOP_BOARDROOM_DECISION_CAPTURE_STATES = [
  "draft",
  "approved",
  "rejected",
  "adjust",
  "request_more_data",
  "blocked",
];

function normaliseAionGoalLoopBoardroomDecisionCaptureState(value = "") {
  const state = String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");

  return AION_GOAL_LOOP_BOARDROOM_DECISION_CAPTURE_STATES.includes(state)
    ? state
    : "draft";
}

function buildAionGoalLoopBoardroomDecisionCapture(options = {}) {
  const now = new Date().toISOString();

  const executivePackage =
    options.executive_package && typeof options.executive_package === "object"
      ? options.executive_package
      : typeof previewAionGoalLoopExecutiveDecisionPackage === "function"
        ? previewAionGoalLoopExecutiveDecisionPackage()
        : {
            business_container_id: "business_not_registered",
            goal_loop_id: "not_staged",
            package_id: "not_staged_executive_decision_package_preview",
            final_recommendation: { recommended_outcome: "request_more_data" },
          };

  const approvalPreview =
    options.approval_preview && typeof options.approval_preview === "object"
      ? options.approval_preview
      : typeof previewAionGoalLoopApprovalGateIntegration === "function"
        ? previewAionGoalLoopApprovalGateIntegration()
        : {
            approval_requests: [],
          };

  const evidencePreview =
    options.evidence_preview && typeof options.evidence_preview === "object"
      ? options.evidence_preview
      : typeof previewAionGoalLoopEvidenceProofReceipts === "function"
        ? previewAionGoalLoopEvidenceProofReceipts()
        : {
            evidence_receipts: [],
            proof_receipt_previews: [],
          };

  const revisionPreview =
    options.revision_preview && typeof options.revision_preview === "object"
      ? options.revision_preview
      : typeof previewAionGoalLoopRevisionHistory === "function"
        ? previewAionGoalLoopRevisionHistory()
        : {
            revision_entries: [],
          };

  const businessContainerId = String(
    options.business_container_id ||
    executivePackage.business_container_id ||
    "business_not_registered"
  );

  const goalLoopId = String(
    options.goal_loop_id ||
    executivePackage.goal_loop_id ||
    "not_staged"
  );

  const selectedDecisionOutcome = String(
    options.selected_decision_outcome ||
    executivePackage.final_recommendation?.recommended_outcome ||
    "request_more_data"
  );

  const decisionState = normaliseAionGoalLoopBoardroomDecisionCaptureState(
    options.decision_state ||
    (
      selectedDecisionOutcome === "approve_closeout" || selectedDecisionOutcome === "approve_next_action"
        ? "approved"
        : selectedDecisionOutcome === "resolve_blockers_first"
          ? "blocked"
          : selectedDecisionOutcome === "request_more_data"
            ? "request_more_data"
            : selectedDecisionOutcome === "pause_goal_loop" || selectedDecisionOutcome === "extend_goal_loop"
              ? "adjust"
              : selectedDecisionOutcome === "archive_goal_loop"
                ? "approved"
                : "draft"
    )
  );

  const decisionId = String(
    options.decision_id ||
    `${goalLoopId}_${selectedDecisionOutcome}_boardroom_decision_capture_preview`
  );

  const approvalRequests = Array.isArray(approvalPreview.approval_requests)
    ? approvalPreview.approval_requests
    : [];

  const evidenceReceipts = Array.isArray(evidencePreview.evidence_receipts)
    ? evidencePreview.evidence_receipts
    : [];

  const proofReceipts = Array.isArray(evidencePreview.proof_receipt_previews)
    ? evidencePreview.proof_receipt_previews
    : [];

  const revisionEntries = Array.isArray(revisionPreview.revision_entries)
    ? revisionPreview.revision_entries
    : [];

  return {
    schema_version: "aion.goal_loop_boardroom_decision_capture.v1",
    status: "boardroom_decision_capture_preview_ready",
    decision_id: decisionId,
    business_container_id: businessContainerId,
    goal_loop_id: goalLoopId,
    package_reference: {
      package_id: String(executivePackage.package_id || `${goalLoopId}_executive_decision_package_preview`),
      package_schema: "aion.goal_loop_executive_decision_package.v1",
      recommended_outcome: executivePackage.final_recommendation?.recommended_outcome || selectedDecisionOutcome,
      preview_only: true,
    },
    selected_decision_outcome: selectedDecisionOutcome,
    decision_state: decisionState,
    decision_reason: String(
      options.decision_reason ||
      executivePackage.final_recommendation?.rationale ||
      "Boardroom decision capture preview generated from the executive package recommendation."
    ),
    decision_actor_metadata: {
      actor: String(options.actor || "ceo_or_boardroom_preview"),
      actor_role: String(options.actor_role || "boardroom_decision_maker"),
      source_surface: "existing_boardroom_and_central_pilot",
      decided_at_preview: now,
      provenance_required: true,
      preview_only: true,
    },
    approval_gate_reference: {
      approval_request_count: approvalRequests.length,
      approval_ids: approvalRequests.map((request) => request.approval_id).filter(Boolean),
      approval_write_required_later: true,
      execution_still_blocked: true,
      preview_only: true,
    },
    evidence_proof_reference: {
      evidence_receipt_count: evidenceReceipts.length,
      proof_receipt_count: proofReceipts.length,
      evidence_ids: evidenceReceipts.slice(0, 6).map((receipt) => receipt.evidence_id).filter(Boolean),
      proof_receipt_ids: proofReceipts.slice(0, 6).map((receipt) => receipt.receipt_id).filter(Boolean),
      proof_anchor_performed: false,
      preview_only: true,
    },
    revision_audit_reference: {
      revision_entry_count: revisionEntries.length,
      revision_ids: revisionEntries.slice(0, 6).map((entry) => entry.revision_id).filter(Boolean),
      decision_revision_required_later: true,
      rollback_execution_allowed: false,
      preview_only: true,
    },
    if_approved_route_preview: {
      selected_decision_outcome: selectedDecisionOutcome,
      next_route:
        decisionState === "approved" && selectedDecisionOutcome === "approve_closeout"
          ? "stage_closeout_archive_handoff_preview"
          : decisionState === "approved" && selectedDecisionOutcome === "approve_next_action"
            ? "stage_next_goal_loop_action_preview"
            : decisionState === "request_more_data"
              ? "return_to_measurement_and_evidence_preview"
              : decisionState === "adjust"
                ? "return_to_boardroom_adjustment_preview"
                : decisionState === "blocked"
                  ? "resolve_blockers_before_execution_preview"
                  : "hold_as_draft_decision_preview",
      execution_allowed_now: false,
      persistence_allowed_now: false,
      archive_allowed_now: false,
      external_action_allowed_now: false,
      preview_only: true,
    },
    boardroom_decision_record_preview: {
      review_id: `${decisionId}_review_record_preview`,
      review_type: "boardroom_goal_loop_decision_capture",
      decision_state: decisionState,
      selected_decision_outcome: selectedDecisionOutcome,
      decision_reason: String(
        options.decision_reason ||
        executivePackage.final_recommendation?.rationale ||
        "Boardroom decision capture preview generated from the executive package recommendation."
      ),
      auditable: true,
      evidence_required: true,
      proof_receipt_required_on_persistence: true,
      preview_only: true,
    },
    created_at_preview: now,
    preview_only: true,
    boardroom_decision_capture_preview_only: true,
    actual_decision_write_performed: false,
    actual_approval_write_performed: false,
    actual_execution_performed: false,
    actual_completion_write_performed: false,
    actual_archive_performed: false,
    actual_container_write_performed: false,
    graph_mutation_required: false,
    persistence_required: false,
    external_side_effects: false,
    connector_call_required: false,
    message_sent: false,
    booking_created: false,
    payment_created: false,
    creates_second_canvas: false,
    creates_second_pilot: false,
    provenance: {
      source: "goal_loop_executive_decision_package_preview",
      generated_by: "aion_goal_loop_phase_m2",
      generated_at: now,
      business_container_id: businessContainerId,
      goal_loop_id: goalLoopId,
      decision_id: decisionId,
      package_id: String(executivePackage.package_id || `${goalLoopId}_executive_decision_package_preview`),
    },
  };
}

