  const evidenceSatisfactionHash = boardroom.evidence_satisfaction_hash || lrmState.evidence_satisfaction_hash || "not_loaded";
  const payloadHash = pilotState.lrm_context_payload_hash || payload.payload_hash || "not_loaded";

