if (!window.__aionPhase24BSmallBusinessFoundationHandlersInstalled) {
  window.__aionPhase24BSmallBusinessFoundationHandlersInstalled = true;

  document.addEventListener("input", (event) => {
    const field = event.target?.closest?.("[data-aion-phase24b-foundation-field]");
    if (!field) return;

    const key = String(field.getAttribute("data-aion-phase24b-foundation-field") || "").trim();
    if (!key) return;

    const draft = getSmallBusinessFoundationDraft();
    draft[key] = field.value || "";
    state.smallBusinessFoundationPreviewReady = false;
  }, true);

  document.addEventListener("change", (event) => {
    const field = event.target?.closest?.("[data-aion-phase24b-foundation-field]");
    if (!field) return;

    const key = String(field.getAttribute("data-aion-phase24b-foundation-field") || "").trim();
    if (!key) return;

    const draft = getSmallBusinessFoundationDraft();
    draft[key] = field.value || "";
    state.smallBusinessFoundationPreviewReady = false;
  }, true);

  document.addEventListener("click", (event) => {
    const scanWebsite = event.target?.closest?.("[data-aion-small-business-foundation-scan-website]");
    if (scanWebsite) {
      event.preventDefault();
      event.stopPropagation();

      const draft = getSmallBusinessFoundationDraft();
      document.querySelectorAll("[data-aion-phase24b-foundation-field]").forEach((field) => {
        const key = String(field.getAttribute("data-aion-phase24b-foundation-field") || "").trim();
        if (key) draft[key] = field.value || "";
      });

      draft.website =
        typeof normaliseAionWebsiteUrlForScanV1 === "function"
          ? normaliseAionWebsiteUrlForScanV1(draft.website)
          : draft.website;

      document.querySelectorAll("[data-aion-phase24b-foundation-field='website']").forEach((field) => {
        field.value = draft.website || "";
      });

      try {
        scanWebsite.textContent = "Scanning...";
        scanWebsite.disabled = true;
      } catch {}

      Promise.resolve(applySmallBusinessWebsiteScanDraft(draft.website))
        .then(() => {
          try {
            scanWebsite.textContent = "Scan website";
            scanWebsite.disabled = false;
          } catch {}
          if (typeof render === "function") render();
        })
        .catch((error) => {
          console.error("[AION] Website scan failed", error);
          try {
            scanWebsite.textContent = "Scan failed";
            scanWebsite.disabled = false;
            setTimeout(() => { scanWebsite.textContent = "Scan website"; }, 1600);
          } catch {}
          if (typeof render === "function") render();
        });
      return;
    }

    const generate = event.target?.closest?.("[data-aion-phase24b-generate-foundation]");
    if (generate) {
      event.preventDefault();
      event.stopPropagation();

      const draft = getSmallBusinessFoundationDraft();
      document.querySelectorAll("[data-aion-phase24b-foundation-field]").forEach((field) => {
        const key = String(field.getAttribute("data-aion-phase24b-foundation-field") || "").trim();
        if (key) draft[key] = field.value || "";
      });

      state.smallBusinessFoundationPreviewReady =
        getSmallBusinessFoundationMissingRequired(draft).length === 0;

      if (typeof render === "function") render();
      return;
    }

    const approveFoundation = event.target?.closest?.("[data-aion-phase24c-approve-foundation]");
    if (approveFoundation) {
      event.preventDefault();
      event.stopPropagation();

      const draft = getSmallBusinessFoundationDraft();
      document.querySelectorAll("[data-aion-phase24b-foundation-field]").forEach((field) => {
        const key = String(field.getAttribute("data-aion-phase24b-foundation-field") || "").trim();
        if (key) draft[key] = field.value || "";
      });

      state.smallBusinessFoundationPreviewReady =
        getSmallBusinessFoundationMissingRequired(draft).length === 0;

      if (state.smallBusinessFoundationPreviewReady) {
        applySmallBusinessFoundationToBrandingAndBusinessContext(draft);
      }

      state.smallBusinessFoundationApproved = state.smallBusinessFoundationPreviewReady;
      state.smallBusinessFoundationApprovedAt = state.smallBusinessFoundationApproved
        ? new Date().toISOString()
        : "";

      if (state.smallBusinessFoundationApproved) {
        try {
          persistAionBusinessTwinFoundationSnapshotV1("foundation_approved");
        } catch {}
      }

      if (typeof render === "function") render();
      return;
    }

    const reviseFoundation = event.target?.closest?.("[data-aion-phase24c-revise-foundation]");
    if (reviseFoundation) {
      event.preventDefault();
      event.stopPropagation();

      state.smallBusinessFoundationApproved = false;
      state.smallBusinessFoundationApprovedAt = "";
      state.smallBusinessFoundationPreviewReady = false;

      if (typeof render === "function") render();
      return;
    }

    const continueButton = event.target?.closest?.("[data-aion-phase24b-continue-departments]");
    if (continueButton) {
      event.preventDefault();
      event.stopPropagation();

      applySmallBusinessFoundationToBrandingAndBusinessContext(getSmallBusinessFoundationDraft());
      state.smallBusinessFoundationApproved = true;
      state.smallBusinessFoundationBoardroomStarted = false;

      /*
       * Business Twin v1:
       * Do not route directly to Boardroom after initial foundation capture.
       * Existing businesses must complete Finance-first Live Agents discovery before
       * Boardroom activation is treated as planning/delegation-ready.
       */
      try {
        window.localStorage?.setItem("aion.smallBusinessFoundationBoardroomStarted", "false");
        window.localStorage?.setItem("aion.business_twin.boardroom_activation_status.v1", "blocked_until_finance_and_operating_base_discovery");
      } catch {}

      if (typeof routeAionBusinessTwinToLiveAgentsFinanceV1 === "function") {
        routeAionBusinessTwinToFinanceOnceV2();
      } else {
        state.activeTab = "live_agents";
        state.aionLiveAgentsFocusDepartment = "finance";
        state.aionLiveAgentsMode = "business_twin_discovery";
        if (typeof render === "function") render();
      }
    }
  }, true);
}


function normaliseAionBusinessTabAlias(tabKey) {
  const key = String(tabKey || "").trim().toLowerCase();
  if (key === "small_business_foundation") return "small_business_foundation";

  if (
    key === "business" ||
    key === "business_context" ||
    key === "business_profile" ||
    key === "brand" ||
    key === "branding" ||
    key === "brand_foundation"
  ) {
    return "business_context";
  }

  return tabKey;
}



