function setAionBusinessContextSubtab(rawKey = "key_business_info") {
  const key =
    typeof normaliseAionBusinessContextSubtabKey === "function"
      ? normaliseAionBusinessContextSubtabKey(rawKey)
      : String(rawKey || "key_business_info").trim().toLowerCase() || "key_business_info";

  try {
    state.activeBusinessContextSubtab = key;
    state.activeTab = "business_context";
  } catch {}

  try {
    window.__aionBusinessContextSubtab = key;
  } catch {}

  try {
    const restored = typeof getAionRestoredAppStateSafe === "function"
      ? getAionRestoredAppStateSafe()
      : null;
    if (restored && typeof restored === "object") {
      restored.activeBusinessContextSubtab = key;
    }
  } catch {}

  try {
    window.localStorage?.setItem("aion.activeBusinessContextSubtab", key);
  } catch {}

  return key;
}

if (typeof window !== "undefined") {
  window.setAionBusinessContextSubtab = setAionBusinessContextSubtab;
}
