function normaliseAionDepartmentPilotKey(departmentKey = "") {
  const key = String(departmentKey || "").trim().toLowerCase();
  if (["marketing", "sales", "finance", "operations", "support", "hr"].includes(key)) return key;
  return key || "marketing";
}

function getAionDepartmentPilotProfile(departmentKey = "") {
  const key = normaliseAionDepartmentPilotKey(departmentKey);
  return AION_DEPARTMENT_PILOT_PROFILES[key] || {
    title: `${runtimeShared.getDepartmentLabel(key)} Pilot`,
    purpose: "Scoped department discovery, planning and safe execution previews.",
    missing: ["department context", "goals", "current process", "known results"],
    nextAction: `Run ${runtimeShared.getDepartmentLabel(key)} discovery`,
  };
}

function getAionDepartmentPilotLedgerEntry(departmentKey = "") {
  const key = normaliseAionDepartmentPilotKey(departmentKey);
  const ledger =
    typeof getAionDepartmentIntelligence === "function"
      ? getAionDepartmentIntelligence()
      : {};
  return ledger[key] && typeof ledger[key] === "object" ? ledger[key] : {};
}

function getAionDepartmentPilotStatus(departmentKey = "") {
  const entry = getAionDepartmentPilotLedgerEntry(departmentKey);
  return entry.status || "needs_discovery";
}

function getAionDepartmentPilotBoardroomSummary(departmentKey = "") {
  const entry = getAionDepartmentPilotLedgerEntry(departmentKey);
  return entry.boardroom_summary || "No department intelligence has been captured yet.";
}

function renderAionDepartmentPilotMissingList(departmentKey = "") {
  const profile = getAionDepartmentPilotProfile(departmentKey);
  const entry = getAionDepartmentPilotLedgerEntry(departmentKey);
  const discovery = entry.discovery && typeof entry.discovery === "object" ? entry.discovery : {};
  const answered = Object.keys(discovery).filter((key) => String(discovery[key] || "").trim()).length;

  return `
    <div class="list-wrap" data-aion-department-pilot-missing-list="${escapeHtml(departmentKey)}">
      ${
        profile.missing.map((item) => `
          <div class="list-item">
            <div class="list-item-title">${escapeHtml(item)}</div>
            <div class="list-item-sub">
              ${answered > 0 ? "Discovery has started. This item can be refined by the department Pilot." : "Not captured yet."}
            </div>
          </div>
        `).join("")
      }
    </div>
  `;
}


/* AION GOAL LOOP CANVAS PHASE D2: Department Goal Context in Existing Department Pilots */
function getAionActiveGoalLoopGraphForDepartmentContext() {
  const graph =
    (typeof window !== "undefined" && window.__aionWorkflowGraph) ||
    (typeof window !== "undefined" && window.__aionGoalLoopWorkflowGraph) ||
    null;

  const isGoalLoop =
    graph?.canvas_type === "goal_loop" ||
    graph?.active_canvas_intent === "goal_loop" ||
    graph?.goal_loop_contract?.goal_loop_id;

  return isGoalLoop ? graph : null;
}

function getAionGoalLoopNodeDepartment(node = {}) {
  return String(
    node?.department ||
    node?.data?.department ||
    node?.meta?.department ||
    node?.config?.department ||
    node?.config?.department_goal?.department ||
    ""
  ).trim().toLowerCase();
}

function getAionGoalLoopNodeType(node = {}) {
  return String(
    node?.node_type ||
    node?.type ||
    node?.data?.node_type ||
    node?.data?.type ||
    ""
  ).trim();
}

function buildAionGoalLoopDepartmentPilotContextMap() {
  const graph = getAionActiveGoalLoopGraphForDepartmentContext();
  const nodes = Array.isArray(graph?.nodes) ? graph.nodes : [];
  const childCanvases = Array.isArray(graph?.department_child_canvases)
    ? graph.department_child_canvases
    : Array.isArray(graph?.goal_loop_contract?.department_child_canvases)
      ? graph.goal_loop_contract.department_child_canvases
      : [];
  const progressRollup = Array.isArray(graph?.department_progress_rollup)
    ? graph.department_progress_rollup
    : Array.isArray(graph?.goal_loop_contract?.department_progress_rollup)
      ? graph.goal_loop_contract.department_progress_rollup
      : [];

  const businessLabel =
    typeof getAionWorkflowCanvasHeaderBusinessLabel === "function"
      ? getAionWorkflowCanvasHeaderBusinessLabel()
      : "Business status pending verification";

  const businessContainer =
    typeof getAionWorkflowBusinessContainerId === "function"
      ? getAionWorkflowBusinessContainerId()
      : "business_not_registered";

  const contextMap = {};

  childCanvases.forEach((canvas) => {
    const key = normaliseAionDepartmentPilotKey(canvas.department || "");
    if (!key) return;

    contextMap[key] = {
      department: key,
      business_label: businessLabel,
      business_container: businessContainer,
      goal_loop_id: String(graph?.goal_loop_id || graph?.goal_loop_contract?.goal_loop_id || canvas.parent_goal_loop_id || "not_staged"),
      master_canvas_id: String(graph?.master_canvas_id || canvas.parent_canvas_id || ""),
      child_canvas_id: String(canvas.canvas_id || ""),
      parent_canvas_id: String(canvas.parent_canvas_id || graph?.master_canvas_id || ""),
      board_goal: graph?.goal_loop_contract?.board_goal || {},
      department_sub_goal: String(canvas.department_sub_goal || ""),
      owner_agent: String(canvas.owner_agent || `${key}_pilot`),
      open_department_canvas_action: canvas.open_department_canvas_action || null,
      progress_rollup: canvas.progress_rollup || progressRollup.find((item) => item?.department === key) || {},
      nodes: {
        assignment: null,
        sub_goal: null,
        plan: null,
        task: null,
        measurement: null,
        result: null,
        evaluation: null,
        ab_test: null,
      },
      preview_only: true,
      execution_blocked: true,
      persistence_required: false,
      route_mutation_required: false,
      uses_existing_department_pilot: true,
      creates_second_pilot: false,
      creates_second_canvas: false,
    };
  });

  nodes.forEach((node) => {
    const department = normaliseAionDepartmentPilotKey(getAionGoalLoopNodeDepartment(node));
    if (!department) return;

    if (!contextMap[department]) {
      contextMap[department] = {
        department,
        business_label: businessLabel,
        business_container: businessContainer,
        goal_loop_id: String(graph?.goal_loop_id || graph?.goal_loop_contract?.goal_loop_id || "not_staged"),
        master_canvas_id: String(graph?.master_canvas_id || ""),
        child_canvas_id: "",
        parent_canvas_id: String(graph?.master_canvas_id || ""),
        board_goal: graph?.goal_loop_contract?.board_goal || {},
        department_sub_goal: "",
        owner_agent: `${department}_pilot`,
        open_department_canvas_action: null,
        progress_rollup: {},
        nodes: {
          assignment: null,
          sub_goal: null,
          plan: null,
          task: null,
          measurement: null,
          result: null,
          evaluation: null,
          ab_test: null,
        },
        preview_only: true,
        execution_blocked: true,
        persistence_required: false,
        route_mutation_required: false,
        uses_existing_department_pilot: true,
        creates_second_pilot: false,
        creates_second_canvas: false,
      };
    }

    const type = getAionGoalLoopNodeType(node);
    if (type === "department_assignment") contextMap[department].nodes.assignment = node;
    if (type === "department_sub_goal") contextMap[department].nodes.sub_goal = node;
    if (type === "department_plan") contextMap[department].nodes.plan = node;
    if (type === "agent_task") contextMap[department].nodes.task = node;
    if (type === "measurement_plan") contextMap[department].nodes.measurement = node;
    if (type === "execution_result") contextMap[department].nodes.result = node;
    if (type === "evaluation") contextMap[department].nodes.evaluation = node;
    if (type === "ab_test") contextMap[department].nodes.ab_test = node;

    if (!contextMap[department].child_canvas_id && node?.child_canvas_id) {
      contextMap[department].child_canvas_id = String(node.child_canvas_id);
    }

    if (!contextMap[department].open_department_canvas_action && node?.open_department_canvas_action) {
      contextMap[department].open_department_canvas_action = node.open_department_canvas_action;
    }

    if (!contextMap[department].department_sub_goal && type === "department_sub_goal") {
      contextMap[department].department_sub_goal = String(node?.title || node?.label || "");
    }
  });

  return contextMap;
}

function getAionActiveGoalLoopDepartmentContext(departmentKey = "") {
  const key = normaliseAionDepartmentPilotKey(departmentKey);
  const contextMap = buildAionGoalLoopDepartmentPilotContextMap();
  const context = contextMap[key] || null;

  if (!context) {
    return {
      department: key,
      active: false,
      status: "no_goal_loop_assignment",
      message: "No active Goal Loop assignment is staged for this department.",
      preview_only: true,
      execution_blocked: true,
      persistence_required: false,
      route_mutation_required: false,
      uses_existing_department_pilot: true,
      creates_second_pilot: false,
      creates_second_canvas: false,
    };
  }

  const nodeCount = Object.values(context.nodes || {}).filter(Boolean).length;

  return {
    ...context,
    active: true,
    status: "goal_loop_assignment_ready",
    node_count: nodeCount,
    has_assignment: Boolean(context.nodes.assignment),
    has_sub_goal: Boolean(context.nodes.sub_goal),
    has_plan: Boolean(context.nodes.plan),
    has_task: Boolean(context.nodes.task),
    has_measurement: Boolean(context.nodes.measurement),
    has_result: Boolean(context.nodes.result),
    has_evaluation: Boolean(context.nodes.evaluation),
    has_ab_test: Boolean(context.nodes.ab_test),
  };
}

