/* AION PATCH: Department Intelligence bare helper function v3 */
function getAionDepartmentIntelligence() {
  try {
    const raw = localStorage.getItem("aion.departmentIntelligence.v1");
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function setAionDepartmentIntelligence(nextLedger) {
  const ledger = nextLedger && typeof nextLedger === "object" && !Array.isArray(nextLedger)
    ? nextLedger
    : {};
  try {
    localStorage.setItem("aion.departmentIntelligence.v1", JSON.stringify(ledger));
  } catch {}
  return ledger;
}

function getAionDepartmentLedgerEntry(departmentKey) {
  const key = String(departmentKey || "finance").trim().toLowerCase() || "finance";
  const ledger = getAionDepartmentIntelligence();
  return ledger[key] && typeof ledger[key] === "object" && !Array.isArray(ledger[key])
    ? ledger[key]
    : {};
}

function updateAionDepartmentIntelligence(departmentKey, patch) {
  const key = String(departmentKey || "finance").trim().toLowerCase() || "finance";
  const ledger = getAionDepartmentIntelligence();
  const current = ledger[key] && typeof ledger[key] === "object" && !Array.isArray(ledger[key])
    ? ledger[key]
    : {};
  ledger[key] = {
    ...current,
    ...(patch && typeof patch === "object" && !Array.isArray(patch) ? patch : {}),
    department: key,
    updated_at: new Date().toISOString(),
  };
  setAionDepartmentIntelligence(ledger);
  return ledger[key];
}

