/* AION PATCH: Founder Feedback Interpreter v1
 * Purpose:
 * - Replace fragile one-off wording checks with a generic interpretation layer.
 * - Current mode is deterministic/local fallback.
 * - Future mode can route this same contract through Gemma/default AI/provider router.
 */
function getAionFounderFeedbackStoreV1() {
  if (typeof getAionBoardroomRoundFeedbackV3 === "function") {
    return getAionBoardroomRoundFeedbackV3();
  }
  if (!window.__aionBoardroomRoundFeedbackV3) {
    window.__aionBoardroomRoundFeedbackV3 = {
      ask_board: [],
      debate_plan: [],
      department_tasks: [],
      delegation: [],
    };
  }
  return window.__aionBoardroomRoundFeedbackV3;
}

function getAionFounderFeedbackEntriesV1(roundKey = "ask_board") {
  const store = getAionFounderFeedbackStoreV1();
  return safeArray(store?.[roundKey]).filter((entry) => String(entry?.text || "").trim());
}

function normalizeAionFounderTextV1(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[>]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function inferAionFeedbackTargetIndexV1(textValue) {
  const text = normalizeAionFounderTextV1(textValue);
  const itemMatch = text.match(/(?:item|task|point|number|no\.?)\s*(\d+)/i);
  if (itemMatch?.[1]) {
    const index = Number(itemMatch[1]);
    if (Number.isFinite(index) && index > 0) return index;
  }

  if (
    text.includes("ad bucket") ||
    text.includes("advert bucket") ||
    text.includes("campaign bucket") ||
    text.includes("facebook") ||
    text.includes("marketing")
  ) {
    return 1;
  }

  return null;
}

function inferAionBucketCountFromFeedbackV1(textValue) {
  const raw = String(textValue || "");
  const text = normalizeAionFounderTextV1(raw);

  const numericPatterns = [
    /(?:prepare|produce|create|make|build|use|do|structure)\s+(\d+)\s+(?:ad\s+|advert\s+|campaign\s+)?buckets?/i,
    /(\d+)\s+(?:ad\s+|advert\s+|campaign\s+)?buckets?\s+(?:and\s+)?(?:not|instead\s+of|rather\s+than)\s+(\d+)/i,
    /(\d+)\s+(?:instead\s+of|rather\s+than|not)\s+(\d+)/i,
  ];

  for (const pattern of numericPatterns) {
    const match = raw.match(pattern);
    if (match?.[1]) {
      const parsed = Number(match[1]);
      if (Number.isFinite(parsed) && parsed > 0 && parsed <= 24) return parsed;
    }
  }

  const words = {
    one: 1,
    two: 2,
    three: 3,
    four: 4,
    five: 5,
    six: 6,
    seven: 7,
    eight: 8,
    nine: 9,
    ten: 10,
  };

  for (const [word, count] of Object.entries(words)) {
    if (
      text.includes(`${word} ad bucket`) ||
      text.includes(`${word} advert bucket`) ||
      text.includes(`${word} campaign bucket`) ||
      text.includes(`${word} instead of`) ||
      text.includes(`${word} rather than`)
    ) {
      return count;
    }
  }

  if (text.includes("founder requested revision") || text.includes("5 buckets") || text.includes("5 not 3") || text.includes("not 3")) {
    return 5;
  }

  return null;
}

function interpretAionSingleFounderFeedbackV1(entry, sourceRound = "ask_board") {
  const raw = String(entry?.text || "").trim();
  const text = normalizeAionFounderTextV1(raw);
  const patches = [];
  const constraints = [];
  const new_context = [];
  const questions = [];

  const targetIndex = inferAionFeedbackTargetIndexV1(raw);
  const bucketCount = inferAionBucketCountFromFeedbackV1(raw);

  if (bucketCount) {
    patches.push({
      patch_id: `patch_bucket_count_${Date.now()}`,
      target_type: "plan_item",
      target_index: targetIndex || 1,
      operation: "modify_quantity",
      field: "plan_item",
      from: "original plan item",
      to: `${bucketCount} ad buckets`,
      instruction: `Change campaign bucket count to ${bucketCount}.`,
      reason: "founder_feedback",
      confidence: 0.9,
      requires_redebate: true,
    });
  }

  if (
    text.includes("don't do facebook") ||
    text.includes("dont do facebook") ||
    text.includes("no facebook") ||
    text.includes("not facebook") ||
    text.includes("avoid facebook")
  ) {
    patches.push({
      patch_id: `patch_channel_${Date.now()}`,
      target_type: "campaign_channel",
      target_index: targetIndex || 1,
      operation: "replace_or_remove_channel",
      field: "channel",
      from: "Facebook",
      to: "non-Facebook / channel to be reselected",
      instruction: "Do not assume Facebook as the campaign channel.",
      reason: "founder_feedback",
      confidence: 0.82,
      requires_redebate: true,
    });

    questions.push({
      question_id: `question_channel_${Date.now()}`,
      question: "Do you want to cancel the campaign, switch to another channel, or prepare a non-lead-generation plan?",
      required_before_execution: true,
    });
  }

  const budgetMatch = raw.match(/(?:budget|spend|cap|max|maximum)\D{0,12}(?:€|eur|euro|euros)?\s*(\d+)/i);
  if (budgetMatch?.[1]) {
    constraints.push({
      constraint_id: `constraint_budget_${Date.now()}`,
      type: "budget_limit",
      value: Number(budgetMatch[1]),
      currency: "EUR",
      instruction: `Use a maximum campaign budget of €${budgetMatch[1]}.`,
      confidence: 0.86,
    });
  }

  const townNegatives = ["configured operating region", "configured operating region", "configured operating region", "configured operating region", "configured operating region", "configured operating region", "configured operating region", "configured operating region"];
  townNegatives.forEach((town) => {
    if (
      text.includes(`don't target ${town}`) ||
      text.includes(`dont target ${town}`) ||
      text.includes(`not ${town}`) ||
      text.includes(`avoid ${town}`)
    ) {
      constraints.push({
        constraint_id: `constraint_exclude_town_${town}_${Date.now()}`,
        type: "exclude_location",
        value: town,
        instruction: `Exclude ${town} from the targeting plan unless founder later approves it.`,
        confidence: 0.78,
      });
    }
  });

  if (
    text.includes("we already have photos") ||
    text.includes("already have before") ||
    text.includes("have before/after") ||
    text.includes("have before and after")
  ) {
    new_context.push({
      context_id: `context_photos_${Date.now()}`,
      type: "proof_assets_available",
      value: "Founder says proof photos/before-after assets are available.",
      confidence: 0.78,
    });
  }

  if (
    text.includes("rebecca") &&
    (
      text.includes("answer") ||
      text.includes("reply") ||
      text.includes("respond") ||
      text.includes("messages")
    )
  ) {
    patches.push({
      patch_id: `patch_sales_owner_${Date.now()}`,
      target_type: "department_task",
      target_department: "sales",
      operation: "assign_owner",
      field: "lead_response_owner",
      from: "unknown",
      to: "Rebecca",
      instruction: "Set Rebecca as lead response owner for inbound messages.",
      reason: "founder_feedback",
      confidence: 0.82,
      requires_redebate: false,
    });
  }

  if (!patches.length && !constraints.length && !new_context.length && !questions.length) {
    new_context.push({
      context_id: `context_founder_note_${Date.now()}`,
      type: "unclassified_founder_feedback",
      value: raw,
      confidence: 0.45,
    });
    questions.push({
      question_id: `question_clarify_${Date.now()}`,
      question: "Founder feedback captured. Use the Discovery Question Inbox answer-type selector to classify it as context, correction, task change, blocker resolved, or still unknown.",
      required_before_execution: false,
    });
  }

  return {
    source_feedback_id: entry?.id || `feedback_${Date.now()}`,
    source_round: sourceRound,
    raw_feedback: raw,
    interpretation_mode: "deterministic_local_fallback",
    future_provider_role: "founder_intent_interpreter",
    patches,
    constraints,
    new_context,
    questions,
    confidence: Math.max(
      ...[
        ...patches.map((p) => p.confidence || 0),
        ...constraints.map((c) => c.confidence || 0),
        ...new_context.map((c) => c.confidence || 0),
        0.45,
      ]
    ),
    requires_redebate: patches.some((patch) => patch.requires_redebate),
  };
}

function runAionFounderFeedbackInterpreterV1(roundKey = "ask_board") {
  const entries = getAionFounderFeedbackEntriesV1(roundKey);
  const interpretations = entries.map((entry) => interpretAionSingleFounderFeedbackV1(entry, roundKey));

  const result = {
    schema_version: "aion.founder_feedback_interpretation.v1",
    generated_at: new Date().toISOString(),
    source_round: roundKey,
    interpretation_mode: "deterministic_local_fallback",
    provider_status: {
      live_provider_fanout: false,
      default_ai_used: false,
      simulated_or_deterministic: true,
      note: "This is a local deterministic interpreter. Future versions can route the same contract through Gemma/default AI.",
    },
    interpretations,
    patches: interpretations.flatMap((item) => safeArray(item.patches)),
    constraints: interpretations.flatMap((item) => safeArray(item.constraints)),
    new_context: interpretations.flatMap((item) => safeArray(item.new_context)),
    questions: interpretations.flatMap((item) => safeArray(item.questions)),
    requires_redebate: interpretations.some((item) => item.requires_redebate),
  };

  try {
    result.result_hash =
      typeof stableAionHash === "function"
        ? stableAionHash(result)
        : `sha256:feedback_interpretation_${Date.now()}`;
  } catch {
    result.result_hash = `sha256:feedback_interpretation_${Date.now()}`;
  }

  if (!window.__aionFounderFeedbackInterpretationsV1) {
    window.__aionFounderFeedbackInterpretationsV1 = {};
  }
  window.__aionFounderFeedbackInterpretationsV1[roundKey] = result;

  return result;
}

function getAionFounderFeedbackInterpretationV1(roundKey = "ask_board") {
  if (!window.__aionFounderFeedbackInterpretationsV1) {
    window.__aionFounderFeedbackInterpretationsV1 = {};
  }
  return window.__aionFounderFeedbackInterpretationsV1[roundKey] || null;
}

function applyAionFounderPatchesToPlanLinesV1(planLines, roundKey = "ask_board") {
  const interpretation =
    getAionFounderFeedbackInterpretationV1(roundKey) ||
    runAionFounderFeedbackInterpreterV1(roundKey);

  const patches = safeArray(interpretation?.patches);
  const constraints = safeArray(interpretation?.constraints);
  const lines = safeArray(planLines).map((line) => String(line || ""));

  return lines.map((line, index) => {
    let next = String(line || "");

    patches.forEach((patch) => {
      const targetIndex = Number(patch.target_index || 0);
      const appliesToLine = targetIndex ? targetIndex === index + 1 : true;

      if (!appliesToLine) return;

      if (patch.operation === "modify_quantity" && patch.to) {
        next = next
          .replace(/prepare\s+\d+\s+ad\s+buckets/gi, `prepare ${patch.to}`)
          .replace(/\b\d+\s+ad\s+buckets\b/gi, patch.to)
          .replace(/three advert buckets/gi, patch.to.replace("ad buckets", "advert buckets"))
          .replace(/three ad buckets/gi, patch.to);

        if (next === line && /ad\s+buckets/i.test(next)) {
          next = next.replace(/ad\s+buckets/i, patch.to);
        }
      }

      if (patch.operation === "replace_or_remove_channel") {
        next = next
          .replace(/lead-generation plan/gi, "lead-generation campaign")
          .replace(/lead-generation plan/gi, "lead-generation campaign")
          .replace(/Facebook/gi, "non-Facebook");
      }
    });

    constraints.forEach((constraint) => {
      if (constraint.type === "budget_limit" && index === 0) {
        if (!/budget/i.test(next)) {
          next = `${next} · Budget cap: €${constraint.value}`;
        }
      }
    });

    return next;
  });
}

function renderAionFounderFeedbackInterpretationHtmlV1(roundKey = "ask_board") {
  const result = getAionFounderFeedbackInterpretationV1(roundKey);
  if (!result || !safeArray(result.interpretations).length) return "";

  return `
    <div
      data-aion-founder-feedback-interpretation="${escapeHtml(roundKey)}"
      style="
        margin-top:10px;
        border:1px solid rgba(216,180,254,0.5);
        background:rgba(59,7,100,0.34);
        color:#f3e8ff;
        padding:12px;
        font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,'Liberation Mono',monospace;
        font-size:12px;
        line-height:1.48;
      "
    >
      <div style="font-weight:900;color:#d8b4fe;letter-spacing:0.08em;text-transform:uppercase;">
        &gt; Founder feedback interpreted
      </div>
      <div>&gt; Mode: ${escapeHtml(result.interpretation_mode || "")} · live AI: no</div>
      <div>&gt; Result hash: ${escapeHtml(result.result_hash || "")}</div>

      ${safeArray(result.patches).length ? `
        <div style="margin-top:8px;color:#ffffff;font-weight:900;">&gt; Plan patches</div>
        ${safeArray(result.patches).map((patch) => `
          <div>&gt; ${escapeHtml(patch.operation || "")} · target ${escapeHtml(patch.target_type || "")}${patch.target_index ? ` ${escapeHtml(patch.target_index)}` : ""}</div>
          <div style="color:#e9d5ff;">&gt; ${escapeHtml(patch.from || "")} → ${escapeHtml(patch.to || "")}</div>
          <div style="color:#c4b5fd;">&gt; ${escapeHtml(patch.instruction || "")}</div>
        `).join("")}
      ` : ""}

      ${safeArray(result.constraints).length ? `
        <div style="margin-top:8px;color:#fbbf24;font-weight:900;">&gt; Constraints</div>
        ${safeArray(result.constraints).map((constraint) => `<div>&gt; ${escapeHtml(constraint.instruction || constraint.value || "")}</div>`).join("")}
      ` : ""}

      ${safeArray(result.new_context).length ? `
        <div style="margin-top:8px;color:#111111;font-weight:900;">&gt; New context</div>
        ${safeArray(result.new_context).map((ctx) => `<div>&gt; ${escapeHtml(ctx.value || "")}</div>`).join("")}
      ` : ""}

      ${safeArray(result.questions).length ? `
        <div style="margin-top:8px;color:#fbbf24;font-weight:900;">&gt; Clarifying questions</div>
        ${safeArray(result.questions).map((q) => `<div>&gt; ? ${escapeHtml(q.question || "")}</div>`).join("")}
      ` : ""}
    </div>
  `;
}
/* END AION PATCH: Founder Feedback Interpreter v1 */


function getAionCurrentBoardResultForDebateV2() {
  return (
    window.__aionVisibleAskBoardResult ||
    window.__aionBoardroomCouncilResult ||
    null
  );
}

function inferAionDepartmentFromPlanLineV2(line) {
  const value = String(line || "").toLowerCase();
  if (value.includes("marketing")) return "marketing";
  if (value.includes("sales")) return "sales";
  if (value.includes("finance")) return "finance";
  if (value.includes("operations")) return "operations";
  if (value.includes("support")) return "support";
  if (value.includes("boardroom")) return "boardroom";
  if (value.includes("pilot")) return "pilot";
  return "unassigned";
}

function buildAionPlanItemDebateV2(planLine, index, sourceResult) {
  return {
    item_index: index + 1,
    plan_item: String(planLine || "").trim(),
    department:
      typeof inferAionDepartmentFromTextV3 === "function"
        ? inferAionDepartmentFromTextV3(planLine)
        : "boardroom",
    status: "legacy_disabled",
    provider_mode: "legacy_disabled",
    live_provider_fanout: false,
    positions: [],
    concerns: [],
    required_inputs: [],
    verdict: "legacy_disabled_use_live_debate_plan",
    next_action: "Run live Debate Plan. Deterministic simulated debate responses are disabled.",
  };
}


/* AION PATCH: Live Boardroom Debate Plan bridge v1
 * Purpose:
 * - Stop Round 2 using legacy deterministic debate.
 * - Debate Plan now calls /api/boardroom/ask with the real Round 1 provider output.
 * - Missing providers stay unavailable; no fake Claude/Grok/Gemini responses.
 */
function extractAionLiveProviderStructuredJsonV1(response = {}) {
  if (typeof parseAionProviderJsonContentV1 === "function") {
    return parseAionProviderJsonContentV1(response.content || "");
  }

  try {
    return JSON.parse(String(response.content || "").trim());
  } catch {
    return null;
  }
}

function getAionCurrentLiveRoundOneResultV1() {
  return (
    window.__aionVisibleAskBoardResult ||
    window.__aionBoardroomCouncilResult ||
    null
  );
}

function pickAionLiveProviderViewForPlanItemV1(parsed = {}, raw = {}, index = 0) {
  const recommendations = safeArray(parsed?.recommendations);
  const risks = safeArray(parsed?.risks);
  const missing = safeArray(parsed?.missing_inputs || parsed?.missing_data);

  return (
    recommendations[index] ||
    recommendations[0] ||
    parsed?.position ||
    risks[index] ||
    risks[0] ||
    missing[index] ||
    missing[0] ||
    String(raw?.content || "").replace(/```json|```/g, "").trim().slice(0, 600) ||
    "Provider returned no usable debate position."
  );
}

function buildAionLiveDebateItemV1(planLine, index, providerResponses = []) {
  const item = String(planLine || "").trim();
  const department =
    typeof inferAionDepartmentFromPlanLineV2 === "function"
      ? inferAionDepartmentFromPlanLineV2(item)
      : "unassigned";

  const succeeded = safeArray(providerResponses).filter((response) => response.status === "succeeded");
  const parsedSucceeded = succeeded.map((response) => ({
    response,
    parsed: extractAionLiveProviderStructuredJsonV1(response) || {},
  }));

  const allProviderRisks = parsedSucceeded.flatMap(({ parsed }) => safeArray(parsed.risks)).filter(Boolean);
  const allProviderMissing = parsedSucceeded
    .flatMap(({ parsed }) => safeArray(parsed.missing_inputs || parsed.missing_data))
    .filter(Boolean);

  const departmentDefaults = getAionDepartmentDefaultInputsV1(department);

  const concerns = filterAionLinesForDepartmentOrItemV1(
    allProviderRisks,
    department,
    item,
    [`${department} item requires owner/input/output/metric validation before delegation.`]
  );

  const requiredInputs = filterAionLinesForDepartmentOrItemV1(
    allProviderMissing,
    department,
    item,
    departmentDefaults
  );

  const positions = parsedSucceeded.map(({ response, parsed }) => ({
    member: response.label || response.provider_id || "Provider",
    provider_id: response.provider_id || "",
    stance: "live_provider",
    view: pickAionLiveProviderViewForPlanItemV1(parsed, response, index),
  }));

  if (!positions.length) {
    positions.push({
      member: "AION",
      stance: "blocked",
      view: "No live provider response was available to debate this plan item.",
    });
  }

  const verdict =
    concerns.length || requiredInputs.length
      ? "keep_with_live_provider_conditions"
      : "keep_ready_for_task_build";

  const nextAction =
    department === "marketing"
      ? "Marketing Pilot should turn this into founder-reviewable campaign output."
      : department === "sales"
        ? "Sales Pilot should define conversion, qualification and response-time rules."
        : department === "operations"
          ? "Operations Pilot should verify engineer capacity, coverage radius and job-size boundaries."
          : department === "finance"
            ? "Finance Pilot should attach budget, margin and spend-limit checks."
            : department === "support"
              ? "Support Pilot should define customer handover, updates and response process."
              : "Boardroom should assign a department owner before delegation.";

  return {
    item_index: index + 1,
    plan_item: item,
    department,
    status: "debated_by_live_providers",
    provider_mode: "live_provider_fanout",
    live_provider_fanout: true,
    positions,
    concerns,
    required_inputs: requiredInputs,
    verdict,
    next_action: nextAction,
  };
}

async function runAionLiveDebatePlanRoundV1(runId = "") {
  if (runId && !isAionBoardroomCurrentRunV1("debate", runId)) return null;

  const sourceResult = getAionCurrentLiveRoundOneResultV1();

  if (!sourceResult) {
    const blocked = {
      schema_version: "aion.boardroom_debate_round.live.v1",
      status: "blocked",
      reason: "No Round 1 live board result found. Run Ask the Board first.",
      generated_at: new Date().toISOString(),
      provider_mode: "live_provider_fanout",
      live_provider_fanout: false,
      debate_items: [],
      consensus_score: 0,
      next_round: "ask_the_board",
    };
    window.__aionBoardroomDebateRound = blocked;
    window.__aionCouncilTerminalExpanded = true;
    return blocked;
  }

  const rawPlan =
    safeArray(sourceResult?.consensus?.plan).length > 0
      ? safeArray(sourceResult.consensus.plan)
      : safeArray(sourceResult?.consensus?.recommended_plan).map((step) =>
          typeof step === "string"
            ? step
            : `${step.owner || step.department || "Unassigned"}: ${step.title || ""} ${step.action || ""}`.trim()
        );

  const plan = rawPlan.length
    ? rawPlan
    : safeArray(sourceResult?.council_responses).map((item) => item.action || item.view).filter(Boolean).slice(0, 6);

  const founderFeedback =
    typeof getAionAllFounderFeedbackForNextRoundV3 === "function"
      ? getAionAllFounderFeedbackForNextRoundV3()
      : {};

  const payload = {
    business_id:
      typeof getAionBoardroomBusinessContainerId === "function"
        ? getAionBoardroomBusinessContainerId()
        : "home-fixed",
    session_type: "debate_plan",
    requested_providers: getAionSelectedBoardroomProviderIdsV1(["openai", "gemini", "claude", "grok", "kimi", "meta", "mistral", "deepseek"]),
    objective: [
      "Round 2 Boardroom Debate Plan.",
      "Debate the actual Round 1 provider consensus and plan items.",
      "Challenge weak assumptions, identify missing owner/input/output/metric boundaries, and return JSON only.",
      "Do not create fake provider opinions.",
      "Return keys: position, recommendations, risks, missing_inputs, plan_changes, confidence."
    ].join(" "),
    context_packet: {
      round: 2,
      source_round_1_result: sourceResult,
      source_session_id: sourceResult.session_id || null,
      plan_items: plan,
      existing_consensus: sourceResult.consensus || {},
      provider_responses_round_1: safeArray(sourceResult.backend_payload?.responses),
      missing_or_unavailable_round_1: safeArray(sourceResult.missing_or_unavailable),
      instruction:
        "Debate each plan item using live provider reasoning. Focus on whether it is actionable, owned by a department, safe, measurable, and approval-gated.",
    },
    founder_feedback: founderFeedback,
  };

  const response = await fetch("http://127.0.0.1:8080/api/boardroom/ask", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Accept": "application/json",
    },
    body: JSON.stringify(payload),
  });

  const backendPayload = await response.json().catch(() => ({}));
  if (!response.ok || backendPayload?.error || backendPayload?.detail) {
    throw new Error(backendPayload?.error || backendPayload?.detail || `Live Debate Plan failed: HTTP ${response.status}`);
  }

  if (runId && !isAionBoardroomCurrentRunV1("debate", runId)) {
    return null;
  }

  const providerResponses = safeArray(backendPayload.responses);
  const debateItems = plan.map((line, index) => buildAionLiveDebateItemV1(line, index, providerResponses));

  const openQuestions = Array.from(new Set(
    providerResponses
      .filter((response) => response.status === "succeeded")
      .flatMap((response) => {
        const parsed = extractAionLiveProviderStructuredJsonV1(response) || {};
        return safeArray(parsed.missing_inputs || parsed.missing_data);
      })
      .filter(Boolean)
  ));

  const risks = Array.from(new Set(
    providerResponses
      .filter((response) => response.status === "succeeded")
      .flatMap((response) => {
        const parsed = extractAionLiveProviderStructuredJsonV1(response) || {};
        return safeArray(parsed.risks);
      })
      .filter(Boolean)
  ));

  const missingInputs = Array.from(new Set(
    debateItems.flatMap((item) => safeArray(item.required_inputs)).filter(Boolean)
  ));

  const succeededCount = Number(backendPayload.succeeded_count || providerResponses.filter((r) => r.status === "succeeded").length || 0);
  const providerCount = Number(backendPayload.provider_count || providerResponses.length || 0);
  const consensusScore = providerCount ? Math.max(0.35, Math.min(0.92, 0.48 + (succeededCount / providerCount) * 0.34 - Math.min(0.18, missingInputs.length * 0.01))) : 0.35;

  const result = {
    schema_version: "aion.boardroom_debate_round.live.v1",
    round: 2,
    generated_at: new Date().toISOString(),
    source_session_id: sourceResult.session_id || null,
    business_name: sourceResult.business_name || "Business status pending verification",
    department_focus: sourceResult.department || "boardroom",
    provider_mode: "live_provider_fanout",
    live_provider_fanout: true,
    simulated_responses: backendPayload.simulated_responses === true,
    succeeded_count: succeededCount,
    provider_count: providerCount,
    backend_payload: backendPayload,
    status: consensusScore >= 0.70 ? "ready_for_task_build" : "needs_more_debate",
    consensus_score: Number(consensusScore.toFixed(2)),
    debate_items: debateItems,
    missing_inputs: missingInputs,
    unresolved: [
      ...openQuestions.slice(0, 10).map((q) => `open_question: ${q}`),
      ...risks.slice(0, 10).map((r) => `risk: ${r}`),
    ],
    missing_or_unavailable: safeArray(backendPayload.missing_or_unavailable),
    next_round: consensusScore >= 0.70 ? "build_department_tasks" : "focused_live_debate_or_founder_clarification",
    founder_question:
      consensusScore >= 0.70
        ? ""
        : "The live providers still raised unresolved inputs or risks. Should the board continue debating, reduce scope, or ask the founder to choose?",
    approval_boundary:
      "Live provider debate round only. No live adverts, bookings, payments, customer messages, or external execution.",
    founder_feedback: founderFeedback,
  };

  try {
    result.result_hash =
      typeof stableAionHash === "function"
        ? stableAionHash(result)
        : `sha256:live_boardroom_debate_${Date.now()}`;
  } catch {
    result.result_hash = `sha256:live_boardroom_debate_${Date.now()}`;
  }

  window.__aionBoardroomDebateRound = result;
  window.__aionBoardroomDepartmentTasks = null;
  window.__aionCouncilTerminalExpanded = true;
  window.__aionCouncilContextInputOpen = false;
  clearAionBoardroomLiveRunStatusV1(runId);
  window.aionStageBoardroomPackagesToDepartmentPilotsO14A?.();

  return result;
}
/* END AION PATCH: Live Boardroom Debate Plan bridge v1 */


