async function buildAionLiveDepartmentTasksFromDebateV1(runId = "") {
  if (runId && !isAionBoardroomCurrentRunV1("build", runId)) return null;

  const debate = window.__aionBoardroomDebateRound;
  if (!debate || !safeArray(debate.debate_items).length) {
    const blocked = {
      schema_version: "aion.department_task_build.live.v1",
      status: "blocked",
      reason: "No Debate Plan round found. Run Debate Plan first.",
      generated_at: new Date().toISOString(),
      provider_mode: "live_provider_fanout",
      live_provider_fanout: false,
      tasks: [],
    };
    window.__aionBoardroomDepartmentTasks = blocked;
    window.__aionCouncilTerminalExpanded = true;
    return blocked;
  }

  const payload = {
    business_id:
      typeof getAionBoardroomBusinessContainerId === "function"
        ? getAionBoardroomBusinessContainerId()
        : "home-fixed",
    session_type: "build_department_tasks",
    requested_providers: getAionSelectedBoardroomProviderIdsV1(["openai", "gemini", "claude", "grok", "kimi", "meta", "mistral", "deepseek"]),
    objective: [
      "Round 3 Build Department Tasks.",
      "Use the live Debate Plan output and founder feedback to produce department-owned task drafts.",
      "Do not use template tasks. Do not invent business-specific facts.",
      "Return JSON only.",
      "Required JSON shape: { task_drafts: [{ department, owner, title, objective, inputs_needed, blockers, output_required, success_metric }], risks: [], missing_inputs: [], confidence }.",
      "Each task must be approval-gated and must not execute adverts, bookings, payments, customer messages, or external side effects."
    ].join(" "),
    context_packet: {
      round: 3,
      source_debate_round: debate,
      debate_items: safeArray(debate.debate_items),
      missing_inputs: safeArray(debate.missing_inputs),
      unresolved: safeArray(debate.unresolved),
      instruction:
        "Convert the live debated items into clear department tasks with owner, objective, inputs needed, blockers, output required, success metric, and approval boundary.",
    },
    founder_feedback:
      typeof getAionAllFounderFeedbackForNextRoundV3 === "function"
        ? getAionAllFounderFeedbackForNextRoundV3()
        : {},
    discovery_answers:
      typeof getAionDiscoveryAnswersForProviderContextV1 === "function"
        ? getAionDiscoveryAnswersForProviderContextV1()
        : [],
  };

  const response = await fetch("http://127.0.0.1:8080/api/boardroom/ask", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Accept": "application/json",
    },
    body: JSON.stringify(payload),
  });

  const backendPayload = await response.json().catch(() => ({}));
  if (!response.ok || backendPayload?.error || backendPayload?.detail) {
    throw new Error(backendPayload?.error || backendPayload?.detail || `Live Build Dept Tasks failed: HTTP ${response.status}`);
  }

  if (runId && !isAionBoardroomCurrentRunV1("build", runId)) {
    return null;
  }

  const succeeded = safeArray(backendPayload.responses).filter((response) => response.status === "succeeded");
  const parsed = succeeded.map((response) => ({
    response,
    parsed:
      typeof extractAionLiveProviderStructuredJsonV1 === "function"
        ? extractAionLiveProviderStructuredJsonV1(response) || {}
        : {},
  }));

  const providerRisks = Array.from(new Set(
    parsed.flatMap(({ parsed }) => safeArray(parsed.risks)).filter(Boolean)
  ));

  const providerMissing = Array.from(new Set(
    parsed.flatMap(({ parsed }) => safeArray(parsed.missing_inputs || parsed.missing_data)).filter(Boolean)
  ));

  const providerTaskDrafts = extractAionProviderTaskDraftsV1(backendPayload);

  const fallbackDrafts = providerTaskDrafts.length
    ? []
    : safeArray(debate.debate_items).map((item) => ({
        department: item.department || "boardroom",
        title: item.plan_item || item.next_action || "Debated plan item",
        objective: item.next_action || item.plan_item || "Prepare founder-reviewable task draft.",
        inputs_needed: safeArray(item.required_inputs),
        blockers: safeArray(item.concerns),
        output_required: "Founder-reviewable draft output.",
        source_provider: "fallback_from_debate_item",
        source_provider_label: "Debate item fallback",
      }));

  const tasks = [...providerTaskDrafts, ...fallbackDrafts].map((task, index) =>
    normaliseAionLiveTaskDraftV1(task, index)
  );

  const genericTaskStagingPack = buildAionGenericTaskStagingPackV1({
    tasks,
    debate,
    backendPayload,
  });

  const result = {
    schema_version: "aion.department_task_build.live.v1",
    generic_task_staging_pack: genericTaskStagingPack,
    pilot_ledgers: safeArray(genericTaskStagingPack.pilot_ledgers),
    security_manifest: {
      operational_state: genericTaskStagingPack.operational_state,
      routing_mode: genericTaskStagingPack.routing_mode,
      structural_execution_boundary: genericTaskStagingPack.structural_execution_boundary,
      approval_required_before_write: true,
      pilot_file_write_status: "not_written_preview_only",
    },
    round: 3,
    generated_at: new Date().toISOString(),
    source_debate_hash: debate.result_hash || null,
    business_name: debate.business_name || "Business status pending verification",
    provider_mode: "live_provider_fanout",
    live_provider_fanout: true,
    simulated_responses: backendPayload.simulated_responses === true,
    succeeded_count: backendPayload.succeeded_count || succeeded.length,
    provider_count: backendPayload.provider_count || safeArray(backendPayload.responses).length,
    backend_payload: backendPayload,
    approval_gated: true,
    status: "tasks_ready_for_delegation_preview",
    tasks,
    missing_or_unavailable: safeArray(backendPayload.missing_or_unavailable),
    delegation_boundary:
      "Live provider task build only. Tasks are prepared for department ledgers only. No live execution until founder approval.",
    founder_feedback:
      typeof getAionAllFounderFeedbackForNextRoundV3 === "function"
        ? getAionAllFounderFeedbackForNextRoundV3()
        : {},
  };

  try {
    result.result_hash =
      typeof stableAionHash === "function"
        ? stableAionHash(result)
        : `sha256:live_department_tasks_${Date.now()}`;
  } catch {
    result.result_hash = `sha256:live_department_tasks_${Date.now()}`;
  }

  window.__aionBoardroomDepartmentTasks = result;
  window.__aionCouncilTerminalExpanded = true;
  window.__aionCouncilContextInputOpen = false;
  clearAionBoardroomLiveRunStatusV1(runId);
  window.aionStageBoardroomPackagesToDepartmentPilotsO14A?.();

  return result;
}
/* END AION PATCH: Live Department Task Build bridge v1 */

