function getAionBoardroomRoundFeedbackV3() {
  if (!window.__aionBoardroomRoundFeedbackV3 || typeof window.__aionBoardroomRoundFeedbackV3 !== "object") {
    window.__aionBoardroomRoundFeedbackV3 = {
      ask_board: [],
      debate_plan: [],
      department_tasks: [],
      delegation: [],
    };
  }
  return window.__aionBoardroomRoundFeedbackV3;
}

function addAionBoardroomRoundFeedbackV3(roundKey, textValue) {
  const value = String(textValue || "").trim();
  if (!value) return null;

  const store = getAionBoardroomRoundFeedbackV3();
  const key = String(roundKey || "ask_board");
  if (!Array.isArray(store[key])) store[key] = [];

  const entry = {
    id: `feedback_${key}_${Date.now()}`,
    round: key,
    text: value,
    created_at: new Date().toISOString(),
    source: "founder_terminal_feedback",
  };

  store[key].push(entry);
  window.__aionBoardroomRoundFeedbackV3 = store;

  return entry;
}

function getAionBoardroomFeedbackTextV3(roundKey) {
  const store = getAionBoardroomRoundFeedbackV3();
  return safeArray(store?.[roundKey]).map((entry) => entry.text).filter(Boolean);
}

