function getAionFinanceBusinessTwinContextV2() {
  function readJson(key, fallback = {}) {
    try {
      return JSON.parse(window.localStorage.getItem(key) || "") || fallback;
    } catch {
      return fallback;
    }
  }

  const latest = readJson("aion.business_twin.latest.v1", {});
  const foundation = readJson("aion.business_twin.foundation_snapshot.v1", {});
  const setup = readJson("aion.business_twin_setup.v1", {});
  const draft =
    foundation.foundation_draft ||
    latest.foundation_draft ||
    latest.business_twin_setup ||
    setup ||
    {};

  return {
    business_name: draft.business_name || foundation.business_name || latest.business_name || "Business",
    industry: draft.industry || foundation.industry || latest.industry || "Finance discovery",
    service_area: draft.service_area || draft.region || foundation.service_area || "",
    website: draft.website || foundation.website || "",
  };
}

