function normaliseAionO14DDepartmentKey(departmentKey) {
  const key = String(departmentKey || "").trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(AION_O14D_DEPARTMENT_121_CONFIG, key) ? key : "finance";
}

function getAionO14DDepartment121Config(departmentKey) {
  return AION_O14D_DEPARTMENT_121_CONFIG[normaliseAionO14DDepartmentKey(departmentKey)] || AION_O14D_DEPARTMENT_121_CONFIG.finance;
}

function buildAionDepartment121BoardroomSnapshotO14D(departmentKey) {
  const key = normaliseAionO14DDepartmentKey(departmentKey);
  const config = getAionO14DDepartment121Config(key);
  const business =
    typeof getAionFinanceBusinessTwinContextV2 === "function"
      ? getAionFinanceBusinessTwinContextV2()
      : { business_name: "Business", industry: "Department discovery", service_area: "" };
  const now = new Date().toISOString();
  const seatId = `seat_${key === "operations" ? "ops" : key}`;

  return {
    workspace: {
      id: `business_twin_${key}_121`,
      name: business.business_name,
      status: config.status,
      industry: business.industry,
      service_area: business.service_area,
    },
    active_zone: key,
    activeZone: key,
    selected_seat_id: seatId,
    selectedSeatId: seatId,
    selectedInspectorTarget: { kind: "seat", seatId },
    departments: [
      {
        key,
        label: key === "hr" ? "HR" : key.charAt(0).toUpperCase() + key.slice(1),
        status: config.status,
        state: "warning",
        summary: config.summary,
      },
    ],
    seats: [
      {
        id: seatId,
        key,
        department_key: key,
        label: key === "hr" ? "HR" : key.charAt(0).toUpperCase() + key.slice(1),
        role: config.role,
        status: "needs_discovery",
        state: "warning",
        summary: config.summary,
        kpis: config.kpis.map(([label, value]) => ({ label, value })),
      },
    ],
    pulse: {
      [key]: {
        state: "warning",
        label: config.status,
        updated_at: now,
      },
    },
    runtime: {
      runs: [],
      approvals: [],
      audit: [],
    },
    metadata: {
      source: `department_121_live_agents_real_renderer_o14d`,
      department_key: key,
      business_name: business.business_name,
      industry: business.industry,
      service_area: business.service_area,
      generated_at: now,
      live_external_side_effect: false,
    },
  };
}

