function mountAionRealFinance121BoardroomRendererV2() {
  if (String(state.activeTab || "") !== "live_agents") return;

  const mount = document.getElementById("aionFinance121SpatialBoardroomMount");
  if (!mount || !window.TessarisDesktopBoardroomRenderer) return;

  const signature = "real_finance_121_v2";
  if (mount.dataset.aionRendererMounted === signature) return;
  mount.dataset.aionRendererMounted = signature;

  const snapshot = buildAionFinance121BoardroomSnapshotV2();

  window.TessarisDesktopBoardroomRenderer.mountBoardroom(mount, {
    snapshot,
    viewMode: "spatial",
    activeZone: "finance",
    selectedSeatId: "seat_finance",
    selectedInspectorTarget: { kind: "seat", seatId: "seat_finance" },
    boardroomTeamMode: "finance_121",
    visibleDepartments: ["finance"],
    cameraMode: "finance_121",
    requestRender: null,
    onActiveZoneChange: null,
    onSeatSelect: null,
    onInspectorTargetChange: null,
  });
}

if (!window.__aionFinanceDataSetupHandlersV2) {
  window.__aionFinanceDataSetupHandlersV2 = true;

  document.addEventListener("click", (event) => {
    const focus = event.target?.closest?.("[data-aion-finance-focus-data-setup]");
    if (focus) {
      event.preventDefault();
      document.getElementById("aionFinanceDataSetupPanel")?.scrollIntoView?.({ behavior: "smooth", block: "start" });
      return;
    }

    const add = event.target?.closest?.("[data-aion-finance-provider-add]");
    if (!add) return;

    event.preventDefault();
    event.stopPropagation();

    const select = document.querySelector("[data-aion-finance-provider-select]");
    const note = document.querySelector("[data-aion-finance-provider-note]");
    const items = getAionFinanceStagedDataPointsV2();

    items.push({
      id: `finance_data_${Date.now()}`,
      label: String(select?.value || "Finance data point"),
      note: String(note?.value || "").trim(),
      status: "staged_discovery",
      created_at: new Date().toISOString(),
      live_external_side_effect: false,
    });

    setAionFinanceStagedDataPointsV2(items);
    if (note) note.value = "";
    if (typeof requestRender === "function") requestRender();
  }, true);

  document.addEventListener("change", (event) => {
    const input = event.target?.closest?.("[data-aion-finance-upload]");
    if (!input) return;

    const items = getAionFinanceStagedDataPointsV2();

    Array.from(input.files || []).forEach((file) => {
      items.push({
        id: `finance_file_${Date.now()}_${Math.random().toString(16).slice(2)}`,
        label: file.name,
        note: `${file.type || "unknown file type"} · ${file.size || 0} bytes`,
        status: "local_file_selected",
        created_at: new Date().toISOString(),
        live_external_side_effect: false,
      });
    });

    setAionFinanceStagedDataPointsV2(items);
    if (typeof requestRender === "function") requestRender();
  }, true);
}


