function renderAionCustomDepartmentWorkspaceV1(departmentKey) {
  const department = getAionDesktopCustomDepartmentsV1().find((item) => String(item?.id || "").toLowerCase() === String(departmentKey || "").toLowerCase());
  if (!department) return "";
  const name = String(department.name || "Department");
  const title = String(department.pilot_title || `${name} Director`);
  const mandate = String(department.mandate || "Set the mandate for this department Pilot.");
  return `
    <section class="surface-shell aion-custom-department-workspace" data-aion-custom-department-workspace="${escapeHtml(department.id)}">
      <div class="surface-header">
        <div>
          <div class="surface-eyebrow">CUSTOM DEPARTMENT · PAIRED WORKSPACE</div>
          <div class="surface-title">${escapeHtml(name)}</div>
          <div class="surface-subtitle">${escapeHtml(title)} · a dedicated Pilot workspace for this business function.</div>
        </div>
      </div>
      <div class="aion-custom-department-workspace-grid">
        <article class="panel large-panel"><div class="panel-title">Pilot mandate</div><p>${escapeHtml(mandate)}</p><button class="secondary-btn" data-aion-custom-department-edit-mandate="${escapeHtml(department.id)}">Refine mandate</button></article>
        <article class="panel large-panel"><div class="panel-title">Department conversation</div><p>Start a focused conversation with the ${escapeHtml(title)}. Tasks and recommendations stay within this department.</p><button class="primary-btn" data-aion-custom-department-open-chat="${escapeHtml(department.id)}">Open ${escapeHtml(name)} chat</button></article>
      </div>
    </section>
  `;
}

function renderLiveAgentsWorkspaceBody(selectedRuns, selectedAgentCard) {
  const activeView = getLiveAgentsView();
  const departmentKey = getSelectedLiveDepartmentKey();

  /*
   * PHASE 25J HOTFIX:
   * The Live Agents department tab is the source of truth for department scope.
   * Do not let a stale selectedAgentCard from another department render Finance inside Marketing,
   * Sales inside Operations, etc.
   */
  const scopedSelectedAgentCard =
    selectedAgentCard && typeof selectedAgentCard === "object"
      ? {
          ...selectedAgentCard,
          departmentKey,
          department: departmentKey,
        }
      : selectedAgentCard;

  const customDepartmentWorkspace = renderAionCustomDepartmentWorkspaceV1(departmentKey);
  if (customDepartmentWorkspace) return customDepartmentWorkspace;

  if (departmentKey === "aion") {
    if (activeView === LIVE_AGENT_VIEWS.APPROVALS) {
      return renderDepartmentApprovalsSurface(departmentKey, scopedSelectedAgentCard);
    }

    return renderAionWorkspaceSurface(selectedRuns, scopedSelectedAgentCard);
  }

  if (departmentKey === "pilot") {
    if (activeView === LIVE_AGENT_VIEWS.APPROVALS) {
      return renderDepartmentApprovalsSurface(departmentKey, scopedSelectedAgentCard);
    }

    return renderAionWorkspaceSurface(selectedRuns, scopedSelectedAgentCard);
  }

  if (activeView === LIVE_AGENT_VIEWS.APPROVALS) {
    return renderDepartmentApprovalsSurface(departmentKey, scopedSelectedAgentCard);
  }

  if (departmentKey === "marketing") {
    if (activeView === LIVE_AGENT_VIEWS.CALENDAR) {
      return renderLiveAgentCalendarView(selectedRuns, scopedSelectedAgentCard);
    }

    if (activeView === LIVE_AGENT_VIEWS.RUNS) {
      return renderLiveAgentRunsView(selectedRuns, scopedSelectedAgentCard);
    }

    if (activeView === LIVE_AGENT_VIEWS.SETTINGS) {
      return renderLiveAgentSettingsView(scopedSelectedAgentCard);
    }

    return renderPilotMarketingWorkspaceSurface(selectedRuns, scopedSelectedAgentCard);
  }

  if (activeView === LIVE_AGENT_VIEWS.SETTINGS) {
    return renderLiveAgentSettingsView(scopedSelectedAgentCard);
  }

  if (activeView === LIVE_AGENT_VIEWS.RUNS) {
    return renderLiveAgentRunsView(selectedRuns, scopedSelectedAgentCard);
  }

  if (departmentKey === "finance") {
    return renderFinanceWorkspaceSurface(selectedRuns, scopedSelectedAgentCard);
  }

  if (departmentKey === "products_services") {
    if (window.AionOperatingModelWorkspace && typeof window.AionOperatingModelWorkspace.render === "function") {
      return `<section data-aion-shared-department-pilot="true" data-aion-shared-department="products_services">${window.AionOperatingModelWorkspace.render()}</section>`;
    }
    return renderGenericDepartmentWorkspaceSurface(departmentKey, selectedAgentCard);
  }

  if (departmentKey === "support") {
    return renderSupportWorkspaceSurface(selectedRuns, scopedSelectedAgentCard);
  }

  if (departmentKey === "sales") {
    return renderSalesWorkspaceSurface(selectedRuns, scopedSelectedAgentCard);
  }

  if (departmentKey === "operations") {
    return renderOperationsWorkspaceSurface(selectedRuns, scopedSelectedAgentCard);
  }

  if (departmentKey === "hr") {
    return renderHRWorkspaceSurface(selectedRuns, scopedSelectedAgentCard);
  }

  if (departmentKey === "builder") {
    return renderGenericDepartmentWorkspaceSurface("builder", selectedAgentCard);
  }

  return renderGenericDepartmentWorkspaceSurface(departmentKey, selectedAgentCard);
}

function renderLiveAgentRunRow(run) {
  const workflowName = runtimeShared.getRunWorkflowLabel(run);
  const agentLabel = runtimeShared.getRunAgentLabel(run);
  const runId = run?.id || run?.queue_item_id || "";
  const isSelectedRun = runId && state.selectedLiveRunId === String(runId);
  const rowId = runId ? getSelectedRunElementId(runId) : "";
  const updatedAt = formatDateTime(run?.updated_at || run?.created_at);
  const departmentLabel = run?.department_key
    ? prettify(run.department_key)
    : "—";

  return `
    <div
      ${rowId ? `id="${escapeHtml(rowId)}"` : ""}
      class="minimal-run-row ${isSelectedRun ? "minimal-run-row-selected run-row-selected" : ""}"
      style="
        border:1px solid rgba(15,23,42,0.18);
        background:#ffffff;
        padding:14px 16px;
        display:grid;
        gap:10px;
        margin-bottom:10px;
      "
    >
      <div style="
        display:flex;
        align-items:flex-start;
        justify-content:space-between;
        gap:10px;
        flex-wrap:wrap;
      ">
        <div style="min-width:0;">
          <div style="
            font-size:14px;
            font-weight:700;
            line-height:1.25;
            color:#111111;
            word-break:break-word;
          ">
            ${escapeHtml(workflowName)}
          </div>

          <div style="
            font-size:12px;
            color:rgba(17,17,17,0.68);
            margin-top:4px;
            word-break:break-word;
          ">
            ${escapeHtml(agentLabel)} · ${escapeHtml(departmentLabel)}
          </div>
        </div>

        <div class="badge-row">
          ${renderStatusBadge(run?.status || "unknown")}
        </div>
      </div>

      <div style="
        display:flex;
        align-items:center;
        justify-content:space-between;
        gap:10px;
        flex-wrap:wrap;
      ">
        <div style="
          font-size:12px;
          color:rgba(17,17,17,0.72);
        ">
          Updated ${escapeHtml(updatedAt)}
        </div>

        ${
          runId
            ? `
              <button
                class="minimal-run-row-action live-run-select-btn"
                data-run-id="${escapeHtml(runId)}"
                style="
                  appearance:none;
                  -webkit-appearance:none;
                  border:1px solid rgba(15,23,42,0.18);
                  background:#ffffff;
                  color:#111111;
                  padding:8px 14px;
                  font-weight:700;
                  cursor:pointer;
                "
              >
                ${isSelectedRun ? "Open" : "Inspect"}
              </button>
            `
            : ""
        }
      </div>
    </div>
  `;
}

