if (!window.__aionO17EMarketingCockpitHandlersInstalled) {
  window.__aionO17EMarketingCockpitHandlersInstalled = true;

  document.addEventListener("click", (event) => {
    const plan = event.target?.closest?.("[data-aion-o17e-marketing-build-plan='true']");
    const queue = event.target?.closest?.("[data-aion-o17e-marketing-build-queue='true']");
    const run = event.target?.closest?.("[data-aion-o17e-marketing-run-safe-task='true']");
    const voice = event.target?.closest?.("[data-aion-o17e-marketing-terminal-voice='true']");

    if (!plan && !queue && !run && !voice) return;

    event.preventDefault();
    event.stopPropagation();

    try {
      const record = {
        status: plan ? "plan_ready" : queue ? "queue_ready" : run ? "safe_task_preview_ready" : "voice_capture_preview",
        source: "o17e_marketing_pilot_cockpit",
        department: "marketing",
        live_external_actions_blocked: true,
        execution_boundary: "approval_gated",
        storage_state: "frontend_preview_only",
        updated_at: new Date().toISOString(),
      };

      window.__aionO17EMarketingPilotCockpitLastAction = record;
      window.localStorage?.setItem("aion.departmentIntelligence.marketing", JSON.stringify(record, null, 2));
    } catch {}

    if (typeof safeAionDesktopPatch === "function") {
      safeAionDesktopPatch({
        message: plan
          ? "Marketing Pilot plan preview staged."
          : queue
            ? "Marketing Pilot safe queue preview staged."
            : run
              ? "Marketing Pilot safe task preview staged. No external action taken."
              : "Marketing voice capture placeholder staged.",
        messageTone: "success",
      });
    }

    if (typeof requestRender === "function") requestRender();
  }, true);
}

