function renderLiveAgentsSurface() {
  if (typeof document !== "undefined") {
    document.documentElement.style.background = "#ffffff";
    document.body.style.background = "#ffffff";
    document.body.classList.add("aion-phase23y-live-agents-white");

    /*
     * O14R: Live Agents must use the same square left sidebar chrome as Boardroom.
     * Do not add aion-phase24a-entry-visible here; that class activates the
     * rounded floating Phase 25K sidebar rules at aion-main-left-sidebar-phase25k.
     */
    document.body.classList.remove("aion-phase24a-entry-visible");
    document.body.classList.remove("aion-workflow-sidebar-expanded");
    document.body.classList.remove("aion-phase19c-workflow-visible");

    const appRoot = document.getElementById("app");
    if (appRoot) {
      appRoot.style.background = "#ffffff";
      appRoot.style.backgroundColor = "#ffffff";
    }
  }

  const selectedRuns = getRunsForSelectedLiveAgent();
  const selectedAgentCard = getSelectedLiveAgentCard();
  const departmentKey = getSelectedLiveDepartmentKey();
  const commandCentreWidth = departmentKey === "operations";

  return `
    <div
      class="surface-shell aion-phase23y-live-agents-white-shell"
      data-aion-o14p-live-agents-shell="true"
      ${departmentKey === "operations" ? 'data-aion-o14p-operations-full-bleed="true"' : ""}
      style="
        min-height:100vh;
        ${commandCentreWidth ? "max-width:none !important;margin:0 !important;padding:32px 32px 96px 32px" : "padding:32px 48px 96px 96px"};
        background:#ffffff;
        background-color:#ffffff;
      "
    >
      ${renderAppTabs()}
      ${renderLiveAgentsExecutiveDepartmentNavO14P(departmentKey)}
      ${departmentKey === "marketing" ? renderLiveAgentsSubviewTabs() : ""}

      <div class="dashboard-shell" data-aion-o14p-live-agents-dashboard="true">
        ${renderLiveAgentsWorkspaceBody(selectedRuns, selectedAgentCard)}
      </div>
    </div>
  `;
}

