function installAionWorkflowSidebarToggle() {
  const shell =
    document.querySelector(".aion-workflow-canvas-shell") ||
    document.querySelector(".surface-shell:has(.aion-main-sidebar)") ||
    document.querySelector(".dashboard-shell:has(.aion-main-sidebar)") ||
    document.body;

  const buttons = document.querySelectorAll("[data-aion-workflow-sidebar-toggle='true']");

  if (!buttons.length) return;

  if (window.__aionWorkflowSidebarOpen === undefined) {
    window.__aionWorkflowSidebarOpen = false;
  }

  const apply = () => {
    const expanded = window.__aionWorkflowSidebarOpen === true;

    /*
     * Sidebar state contract:
     * - Workflow canvas still uses the workflow shell when present.
     * - Main app sidebar uses body class so the global left rail can expand.
     * - The old collapsed class is removed so legacy styles.css collapsed icon rules cannot win.
     */
    shell?.classList?.remove?.("aion-workflow-sidebar-collapsed");
    shell?.classList?.toggle?.("aion-workflow-sidebar-expanded", expanded);
    document.body.classList.toggle("aion-workflow-sidebar-expanded", expanded);
  };

  buttons.forEach((button) => {
    if (button.dataset.aionSidebarBound === "true") return;
    button.dataset.aionSidebarBound = "true";

    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();

      window.__aionWorkflowSidebarOpen = !window.__aionWorkflowSidebarOpen;
      apply();

      window.setTimeout(() => {
        if (typeof installAionWorkflowCanvasZoomControls === "function") {
          installAionWorkflowCanvasZoomControls();
        }
      }, 80);
    });
  });

  apply();
}


