        item.tiers ||
        item.tier_summary ||
        {};

      const tiers = Array.isArray(tierSource)
        ? Object.fromEntries(
            tierSource.map((row) => [
              row.tier || row.name || row.memory_tier || "unknown",
              row.count ?? row.records ?? row.total ?? 0,
            ]),
          )
        : tierSource;

      const tierText = Object.entries(tiers || {})
