    const withoutDuplicate = existing.filter((item) => item && item.dedupeKey !== dedupeKey);
    const nextHistory = [{ ...snapshot, dedupeKey }, ...withoutDuplicate].slice(0, 25);
    writeAionGoalEngineMultiAgentReplayHistoryV1(nextHistory);
    return nextHistory;
