/* AION PATCH: Phase 25K workflow title input syncs active tab name */
(function installAionPhase25KWorkflowTitleToTabNameSync() {
  const STORAGE_KEY = "aion.workflow_builder.workflow_tabs.v1";

  function currentTitleFromInput() {
    const input =
      document.querySelector(".aion-workflow-title-input") ||
      document.querySelector("[data-aion-workflow-title-input='true']") ||
      document.querySelector("[data-aion-workflow-title='true']");

    if (!input) return "";

    const raw =
      typeof input.value === "string"
        ? input.value
        : input.textContent;

    return String(raw || "").trim();
  }

  function persistTabs() {
    try {
      const tabs = Array.isArray(window.__aionWorkflowTabs) ? window.__aionWorkflowTabs : [];
      localStorage.setItem(STORAGE_KEY, JSON.stringify({
        active_id: window.__aionActiveWorkflowTabId || tabs[0]?.id || "",
        tabs: tabs.map((tab) => ({
          id: tab.id,
          title: tab.title,
          closable: true,
          graph: tab.graph,
        })),
        saved_at: new Date().toISOString(),
      }));
    } catch (error) {
      console.warn("[AION] Phase25K title/tab sync persist skipped", error);
    }
  }

  function syncTitleToActiveWorkflowTab() {
    const title = currentTitleFromInput();
    if (!title) return;

    const tabs = Array.isArray(window.__aionWorkflowTabs) ? window.__aionWorkflowTabs : [];
    if (!tabs.length) return;

    const activeId = String(window.__aionActiveWorkflowTabId || tabs[0]?.id || "");
    const tab = tabs.find((item) => String(item.id) === activeId) || tabs[0];
    if (!tab) return;

    tab.title = title;
    tab.closable = true;
    tab.graph = {
      ...(tab.graph || {}),
      name: title,
      display_name: title,
      dirty: true,
      dirty_reason: "workflow_title_tab_sync",
      updated_at: new Date().toISOString(),
    };

    window.__aionWorkflowMainGraph = tab.graph;
    window.__aionWorkflowGraph = tab.graph;

    persistTabs();

    if (typeof window.__aionRenderWorkflowCanvasTabs === "function") {
      window.__aionRenderWorkflowCanvasTabs();
    }
  }

  let timer = null;
  function scheduleSync() {
    window.clearTimeout(timer);
    timer = window.setTimeout(syncTitleToActiveWorkflowTab, 120);
  }

  document.addEventListener("input", (event) => {
    if (event.target?.closest?.(".aion-workflow-title-input, [data-aion-workflow-title-input='true'], [data-aion-workflow-title='true']")) {
      scheduleSync();
    }
  }, true);

  document.addEventListener("change", (event) => {
    if (event.target?.closest?.(".aion-workflow-title-input, [data-aion-workflow-title-input='true'], [data-aion-workflow-title='true']")) {
      scheduleSync();
    }
  }, true);

  document.addEventListener("blur", (event) => {
    if (event.target?.closest?.(".aion-workflow-title-input, [data-aion-workflow-title-input='true'], [data-aion-workflow-title='true']")) {
      syncTitleToActiveWorkflowTab();
    }
  }, true);

  document.addEventListener("keydown", (event) => {
    if (event.key !== "Enter") return;
    if (event.target?.closest?.(".aion-workflow-title-input, [data-aion-workflow-title-input='true'], [data-aion-workflow-title='true']")) {
      syncTitleToActiveWorkflowTab();
    }
  }, true);

  window.__aionPhase25KSyncWorkflowTitleToActiveTab = syncTitleToActiveWorkflowTab;
})();



