(function installAionWorkflowTabbarHardPersistentRouteSyncLock() {
  if (window.__aionWorkflowTabbarHardPersistentRouteSyncLockInstalled === true) return;
  window.__aionWorkflowTabbarHardPersistentRouteSyncLockInstalled = true;

  const TABBAR_ID = "aion-glyph-workflow-top-tabs-v2";
  const STYLE_ID = "aion-workflow-tabbar-hard-persistent-route-sync-style";

  function activeRoute() {
    try {
      return String(
        (typeof state !== "undefined" && state && state.activeTab) ||
        window.__aionActiveBusinessTab ||
        ""
      ).toLowerCase();
    } catch (_) {
      return String(window.__aionActiveBusinessTab || "").toLowerCase();
    }
  }

  function isWorkflowRoute() {
    const route = activeRoute();
    return route === "operations_agents" || route === "workflow";
  }

  function getSidebarEdge() {
    const sidebar =
      document.querySelector(".aion-main-sidebar") ||
      document.querySelector("[data-aion-main-sidebar='true']");

    const rect = sidebar?.getBoundingClientRect?.();
    const right = Math.ceil(Number(rect?.right || 0));
    return right >= 40 && right <= 180 ? right : 64;
  }

  function getSharedExecutiveHeaderHeight() {
    const header = document.querySelector(
      '[data-aion-shared-page-executive-header="true"] [data-aion-boardroom-sticky-team-header="true"]'
    );
    const rect = header?.getBoundingClientRect?.();
    const height = Math.ceil(Number(rect?.height || 0));
    return height >= 54 && height <= 140 ? height : 70;
  }

  function installStyle() {
    if (document.getElementById(STYLE_ID)) return;

    const style = document.createElement("style");
    style.id = STYLE_ID;
    style.textContent = `
      html body:not(.aion-phase19c-workflow-visible) #${TABBAR_ID} {
        display: none !important;
        visibility: hidden !important;
        opacity: 0 !important;
        pointer-events: none !important;
      }

      html body.aion-phase19c-workflow-visible #${TABBAR_ID} {
        display: flex !important;
        visibility: visible !important;
        opacity: 1 !important;
        pointer-events: auto !important;
        position: fixed !important;
        left: var(--aion-tabbar-sidebar-edge, 64px) !important;
        right: 0 !important;
        top: calc(var(--aion-shared-executive-header-h, 70px) + 42px) !important;
        width: calc(100vw - var(--aion-tabbar-sidebar-edge, 64px)) !important;
        max-width: calc(100vw - var(--aion-tabbar-sidebar-edge, 64px)) !important;
        height: 34px !important;
        min-height: 34px !important;
        max-height: 34px !important;
        margin: 0 !important;
        padding: 0 !important;
        transform: none !important;
        box-sizing: border-box !important;
        z-index: 999997 !important;
        overflow: hidden !important;
      }

      html body.aion-phase19c-workflow-visible .aion-workflow-canvas-shell {
        top: var(--aion-shared-executive-header-h, 70px) !important;
        height: calc(100vh - var(--aion-shared-executive-header-h, 70px)) !important;
        min-height: calc(100vh - var(--aion-shared-executive-header-h, 70px)) !important;
      }

      html body.aion-phase19c-workflow-visible .aion-workflow-topbar {
        top: 0 !important;
        height: 42px !important;
        min-height: 42px !important;
        max-height: 42px !important;
        padding: 0 16px !important;
      }

      html body.aion-phase19c-workflow-visible .aion-workflow-document-strip {
        height: 42px !important;
        min-height: 42px !important;
        margin: 0 !important;
        border-top: 0 !important;
      }

      html body.aion-phase19c-workflow-visible .aion-workflow-layout {
        top: 76px !important;
        height: calc(100% - 76px) !important;
        min-height: calc(100% - 76px) !important;
      }

      html body.aion-phase19c-workflow-visible #${TABBAR_ID} .aion-phase19b-workflow-tab,
      html body.aion-phase19c-workflow-visible #${TABBAR_ID} .aion-glyph-top-tab {
        height: 34px !important;
        min-height: 34px !important;
        max-height: 34px !important;
        box-sizing: border-box !important;
      }

      html body.aion-phase19c-workflow-visible #${TABBAR_ID} .aion-phase19b-workflow-plus-tab,
      html body.aion-phase19c-workflow-visible #${TABBAR_ID} [data-aion-phase19b-workflow-plus='true'],
      html body.aion-phase19c-workflow-visible #${TABBAR_ID} button[title='New workflow canvas'] {
        width: 46px !important;
        min-width: 46px !important;
        max-width: 46px !important;
        flex: 0 0 46px !important;
      }
    `;
    document.head.appendChild(style);
  }

  function forceSync() {
    installStyle();

    const workflow = isWorkflowRoute();
    const edge = getSidebarEdge();
    const edgeValue = `${edge}px`;
    const sharedHeaderHeight = getSharedExecutiveHeaderHeight();
    const sharedHeaderHeightValue = `${sharedHeaderHeight}px`;
    const tabbarTop = sharedHeaderHeight + 42;

    if (document.documentElement.style.getPropertyValue("--aion-tabbar-sidebar-edge") !== edgeValue) {
      document.documentElement.style.setProperty("--aion-tabbar-sidebar-edge", edgeValue);
    }
    if (document.body.style.getPropertyValue("--aion-tabbar-sidebar-edge") !== edgeValue) {
      document.body.style.setProperty("--aion-tabbar-sidebar-edge", edgeValue);
    }
    if (document.documentElement.style.getPropertyValue("--aion-shared-executive-header-h") !== sharedHeaderHeightValue) {
      document.documentElement.style.setProperty("--aion-shared-executive-header-h", sharedHeaderHeightValue);
    }
    if (document.body.style.getPropertyValue("--aion-shared-executive-header-h") !== sharedHeaderHeightValue) {
      document.body.style.setProperty("--aion-shared-executive-header-h", sharedHeaderHeightValue);
    }

    if (document.body.classList.contains("aion-phase19c-workflow-visible") !== workflow) {
      document.body.classList.toggle("aion-phase19c-workflow-visible", workflow);
    }
    if (document.body.classList.contains("aion-phase19c-workflow-hidden") === workflow) {
      document.body.classList.toggle("aion-phase19c-workflow-hidden", !workflow);
    }

    const tabbar = document.getElementById(TABBAR_ID);
    if (!tabbar) return;

    if (!workflow) {
      tabbar.style.setProperty("display", "none", "important");
      tabbar.style.setProperty("visibility", "hidden", "important");
      tabbar.style.setProperty("opacity", "0", "important");
      tabbar.style.setProperty("pointer-events", "none", "important");
      return;
    }

    tabbar.style.setProperty("display", "flex", "important");
    tabbar.style.setProperty("visibility", "visible", "important");
    tabbar.style.setProperty("opacity", "1", "important");
    tabbar.style.setProperty("pointer-events", "auto", "important");
    tabbar.style.setProperty("position", "fixed", "important");
    tabbar.style.setProperty("left", `${edge}px`, "important");
    tabbar.style.setProperty("right", "0px", "important");
    tabbar.style.setProperty("top", `${tabbarTop}px`, "important");
    tabbar.style.setProperty("width", `calc(100vw - ${edge}px)`, "important");
    tabbar.style.setProperty("max-width", `calc(100vw - ${edge}px)`, "important");
    tabbar.style.setProperty("height", "34px", "important");
    tabbar.style.setProperty("min-height", "34px", "important");
    tabbar.style.setProperty("max-height", "34px", "important");
    tabbar.style.setProperty("margin", "0px", "important");
    tabbar.style.setProperty("padding", "0px", "important");
    tabbar.style.setProperty("transform", "none", "important");
    tabbar.style.setProperty("box-sizing", "border-box", "important");
    tabbar.style.setProperty("z-index", "999997", "important");
  }

  function syncBurst() {
    if (window.__aionWorkflowTabbarSyncScheduled) return;
    window.__aionWorkflowTabbarSyncScheduled = true;
    requestAnimationFrame(() => {
      window.__aionWorkflowTabbarSyncScheduled = false;
      forceSync();
    });
  }

  const previousRequestRender = window.requestRender;
  if (typeof previousRequestRender === "function" && previousRequestRender.__aionHardPersistentTabbarRouteSyncWrapped !== true) {
    const wrapped = function requestRenderWithHardPersistentTabbarRouteSync(...args) {
      const result = previousRequestRender.apply(this, args);
      syncBurst();
      return result;
    };
    wrapped.__aionHardPersistentTabbarRouteSyncWrapped = true;
    window.requestRender = wrapped;
  }

  const observer = new MutationObserver(() => {
    if (isWorkflowRoute()) syncBurst();
  });
  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });

  syncBurst();
  setTimeout(syncBurst, 250);
  setTimeout(syncBurst, 1000);

  setInterval(() => {
    if (isWorkflowRoute()) forceSync();
  }, 1000);

  window.addEventListener("resize", syncBurst);
  window.addEventListener("click", syncBurst, true);
  window.addEventListener("pointerdown", syncBurst, true);
  window.addEventListener("aion:workflow-rendered", syncBurst);
})();


