function normaliseAionGoalLoopDepartmentKey(value = "") {
  const key = String(value || "").trim().toLowerCase().replace(/[^a-z0-9_-]/g, "_");
  if (!key) return "boardroom";
  if (key === "aion") return "pilot";
  return key;
}

