/* BEGIN AION O12C GOAL SHEET RENDER SOURCE OF TRUTH */
function isAionGoalSheetGraphO12C(graph) {
  if (!graph || typeof graph !== "object") return false;

  const workflowId = String(graph.workflow_id || graph.id || "").toLowerCase();
  const name = String(graph.name || graph.title || "").toLowerCase();
  const canvasType = String(graph.canvas_type || graph.active_canvas_intent || "").toLowerCase();

  if (canvasType.includes("goal_loop")) return true;
  if (workflowId.includes("goal_loop") || workflowId.includes("goal_sheet")) return true;
  if (name.includes("goal loop") || name.includes("goal sheet") || name.includes("boardroom goal")) return true;
  if (graph.goal_loop_id || graph.goal_sheet_id || graph.goal_loop_contract) return true;

  const nodes = Array.isArray(graph.nodes) ? graph.nodes : [];
  return nodes.some((node) => {
    const hay = [
      node?.id,
      node?.title,
      node?.label,
      node?.type,
      node?.node_type,
      node?.kind,
      node?.summary,
      node?.description,
    ].map((item) => String(item || "").toLowerCase()).join(" ");

    return (
      hay.includes("board meeting minutes") ||
      hay.includes("board decision") ||
      hay.includes("actual goal") ||
      hay.includes("success criteria") ||
      hay.includes("linked department sheets") ||
      hay.includes("pilot queue preview")
    );
  });
}

function getAionActiveGoalSheetWorkflowGraphO12C() {
  if (window.__aionWorkflowTabsAllowEmpty === true && (!Array.isArray(window.__aionWorkflowTabs) || window.__aionWorkflowTabs.length === 0)) {
    return null;
  }
  const selectedWorkflowId = String(
    window.__aionSelectedWorkflowId ||
    window.__aionActiveWorkflowId ||
    ""
  ).trim();

  const activeCandidates = [
    window.__aionWorkflowGraph,
    window.__aionWorkflowMainGraph,
    window.__aionActiveWorkflowGraph,
    window.__aionGoalSheetWorkflowGraph,
  ];

  if (selectedWorkflowId) {
    for (const graph of activeCandidates) {
      const graphId = String(graph?.workflow_id || graph?.id || "").trim();
      if (
        graphId === selectedWorkflowId &&
        isAionGoalSheetGraphO12C(graph) &&
        Array.isArray(graph.nodes) &&
        graph.nodes.length > 0
      ) {
        return graph;
      }
    }
  }

  const openTabs = Array.isArray(window.__aionWorkflowTabs) ? window.__aionWorkflowTabs : [];
  const activeOpenTab = openTabs.find(
    (tab) => String(tab?.id || "") === String(window.__aionActiveWorkflowTabId || ""),
  );
  if (activeOpenTab?.graph && !isAionGoalSheetGraphO12C(activeOpenTab.graph)) {
    return null;
  }

  const candidates = [
    window.__aionWorkflowGraph,
    window.__aionWorkflowMainGraph,
    window.__aionActiveWorkflowGraph,
    window.__aionGoalSheetWorkflowGraph,
    window.__aionO12BActiveGoalSheetGraph,
    window.__aionBoardroomGoalSheetGraph,
    window.__aionGoalLoopWorkflowGraph,
    window.__aionPendingGoalLoopFromBoardroomO12B,
    window.__aionPendingGoalLoopFromBoardroomO8,
  ];

  for (const graph of candidates) {
    if (isAionGoalSheetGraphO12C(graph) && Array.isArray(graph.nodes) && graph.nodes.length > 0) {
      return graph;
    }
  }

  return null;
}

function syncAionGoalSheetGraphIntoWorkflowStateO12C(graph) {
  if (!graph || typeof graph !== "object") return null;

  graph.canvas_type = graph.canvas_type || "goal_loop";
  graph.active_canvas_intent = graph.active_canvas_intent || "goal_loop";
  graph.preview_only = graph.preview_only !== false;
  graph.creates_second_canvas = false;
  graph.creates_second_pilot = false;
  graph.execution_allowed_now = false;
  graph.connector_call_required = false;
  graph.external_side_effects = false;
  graph.actual_live_execution_performed = false;

  window.__aionWorkflowGraph = graph;
  window.__aionGoalLoopWorkflowGraph = graph;
  window.__aionO12BActiveGoalSheetGraph = graph;
  window.__aionWorkflowSelectedNodeId =
    window.__aionWorkflowSelectedNodeId ||
    graph.nodes?.[0]?.id ||
    null;

  try {
    if (typeof compileAndAttachAionWorkflowGlyph === "function") {
      compileAndAttachAionWorkflowGlyph(graph);
    }
  } catch (error) {
    console.warn("[AION] O12C Goal Sheet compile skipped", error);
  }

  return graph;
}

function getAionWorkflowRenderGraphO12C() {
  const goalSheet = getAionActiveGoalSheetWorkflowGraphO12C();
  if (goalSheet) {
    return syncAionGoalSheetGraphIntoWorkflowStateO12C(goalSheet);
  }

  const draft =
    (typeof getAionWorkflowDraftState === "function" && getAionWorkflowDraftState()) ||
    window.__aionWorkflowGraph ||
    { nodes: [], edges: [] };

  return draft;
}

function fitAionGoalSheetWorkflowOnceO12C(graph) {
  if (!graph || !Array.isArray(graph.nodes) || !graph.nodes.length) return;
  if (window.__aionGoalSheetViewportFitDoneO12C === graph.workflow_id) return;

  window.__aionGoalSheetViewportFitDoneO12C = graph.workflow_id;

  window.setTimeout(() => {
    try {
      if (typeof fitAionWorkflowCanvasToGeneratedNodes === "function") {
        fitAionWorkflowCanvasToGeneratedNodes(graph.nodes);
      } else if (typeof updateAionWorkflowCanvasTransform === "function") {
        updateAionWorkflowCanvasTransform();
      }
    } catch (error) {
      console.warn("[AION] O12C Goal Sheet viewport fit failed", error);
    }
  }, 80);
}

(function installAionGoalSheetRenderSourceOfTruthO12C() {
  if (window.__aionGoalSheetRenderSourceOfTruthInstalledO12C === true) return;
  window.__aionGoalSheetRenderSourceOfTruthInstalledO12C = true;

  console.info("[AION] O12C Goal Sheet render source of truth installed");

  document.addEventListener("click", () => {
    window.setTimeout(() => {
      const graph = getAionActiveGoalSheetWorkflowGraphO12C();
      if (graph) syncAionGoalSheetGraphIntoWorkflowStateO12C(graph);
    }, 40);
  }, true);
})();
