  function registerGoalSheetsInMemory(boardGraph) {
    window.__aionGoalLoopBoardroomGoalSheet = boardGraph;
    window.__aionGoalLoopDepartmentGoalSheets = Array.isArray(boardGraph.department_goal_sheets)
      ? boardGraph.department_goal_sheets
      : [];
    window.__aionGoalLoopPilotQueuePreview = boardGraph.pilot_queue_preview || null;

    /*
     * File-cabinet bridge:
     * Keep this as an in-memory registry for now. It is intentionally not
     * a backend write and not a connector call.
     */
    window.__aionGoalLoopLinkedWorkflowRegistry = {
      schema_version: "aion.goal_loop_linked_workflow_registry.v1",
      business_container: boardGraph.business_container,
      boardroom_workflow_id: boardGraph.workflow_id,
      department_workflow_ids: boardGraph.linked_workflow_ids || [],
      records: [
        boardGraph,
        ...(Array.isArray(boardGraph.department_goal_sheets) ? boardGraph.department_goal_sheets : []),
      ],
      preview_only: true,
      updated_at: nowIso(),
    };

    return window.__aionGoalLoopLinkedWorkflowRegistry;
  }

  function fitBoardroomGoalSheetViewport(graph) {
    const nodes = Array.isArray(graph?.nodes) ? graph.nodes : [];
    if (!nodes.length) return;

    const xs = nodes.map((node) => Number(node.x || node.position?.x || 0));
    const ys = nodes.map((node) => Number(node.y || node.position?.y || 0));

    const minX = Math.min(...xs);
    const maxX = Math.max(...xs);
    const minY = Math.min(...ys);
    const maxY = Math.max(...ys);

    const canvas =
      document.querySelector(".aion-workflow-canvas") ||
      document.querySelector(".aion-workflow-canvas-shell") ||
      document.body;

    const rect = canvas.getBoundingClientRect ? canvas.getBoundingClientRect() : { width: window.innerWidth, height: window.innerHeight };

    const graphWidth = Math.max(1, maxX - minX + 360);
    const graphHeight = Math.max(1, maxY - minY + 260);

    const availableWidth = Math.max(900, Number(rect.width || window.innerWidth || 1400) - 140);
    const availableHeight = Math.max(460, Number(rect.height || window.innerHeight || 760) - 180);

    const zoom = Math.max(0.48, Math.min(0.86, availableWidth / graphWidth, availableHeight / graphHeight));

    if (typeof setAionWorkflowCanvasViewport === "function") {
      setAionWorkflowCanvasViewport({
        zoom,
        x: Math.round(110 - minX * zoom),
        y: Math.round(150 - minY * zoom),
      });
    } else {
      window.__aionWorkflowCanvasView = {
        zoom,
        x: Math.round(110 - minX * zoom),
        y: Math.round(150 - minY * zoom),
      };
      window.__aionWorkflowZoom = zoom;
      window.__aionWorkflowPan = {
        x: window.__aionWorkflowCanvasView.x,
        y: window.__aionWorkflowCanvasView.y,
      };
    }

    if (typeof updateAionWorkflowCanvasTransform === "function") {
      updateAionWorkflowCanvasTransform();
    }
  }

  function stageBoardroomGoalSheet() {
    resetWorkflowStatusDismissal();
    const boardGraph = buildBoardroomGoalSheetGraph();
    registerGoalSheetsInMemory(boardGraph);

    window.__aionWorkflowGraph = boardGraph;
    window.__aionGoalLoopWorkflowGraph = boardGraph;
    window.__aionPendingGoalLoopFromBoardroomO8 = boardGraph;
    window.__aionWorkflowSelectedNodeId = "goal_sheet_actual_goal";
    window.__aionWorkflowInspectorOpen = false;
    window.__aionGoalSheetInspectorOpen = null;

    if (typeof compileAndAttachAionWorkflowGlyph === "function") {
      compileAndAttachAionWorkflowGlyph(boardGraph);
    }

    if (typeof persistAionWorkflowDraftState === "function") {
      persistAionWorkflowDraftState();
    }

    window.__aionO8NativeGoalLoopStagingReceipt = {
      staged_at: nowIso(),
      workflow_id: boardGraph.workflow_id,
      node_count: boardGraph.nodes.length,
      edge_count: boardGraph.edges.length,
      department_sheet_count: boardGraph.department_goal_sheets.length,
      used_existing_canvas: true,
      creates_second_canvas: false,
      creates_second_pilot: false,
      preview_only: true,
      connector_call_required: false,
      external_side_effects: false,
      booking_created: false,
      payment_created: false,
      customer_message_sent: false,
      architecture: "aion.o12b.boardroom_goal_sheet_with_linked_department_sheets",
    };

    
      if (typeof syncAionGoalSheetGraphIntoWorkflowStateO12C === "function") {
        syncAionGoalSheetGraphIntoWorkflowStateO12C(graph || graph || window.__aionGoalLoopWorkflowGraph);
      }

      console.info("[AION] O12B staged Boardroom Goal Sheet", window.__aionO8NativeGoalLoopStagingReceipt);

    if (typeof requestRender === "function") {
      requestRender();
      window.setTimeout(() => fitBoardroomGoalSheetViewport(boardGraph), 40);
      window.setTimeout(() => fitBoardroomGoalSheetViewport(boardGraph), 160);
    } else {
      fitBoardroomGoalSheetViewport(boardGraph);
    }

    return boardGraph;
  }

  function isBoardroomView() {
    const text = document.body?.innerText || "";
    return text.includes("SPATIAL BOARDROOM") || text.includes("BOARDROOM TERMINAL") || text.includes("3D BOARDROOM") || text.includes("Boardroom");
  }

  function isWorkflowView() {
    const text = document.body?.innerText || "";
    return text.includes("AION WORKFLOW BUILDER") || text.includes("Execute workflow") || !!document.querySelector(".aion-workflow-canvas");
  }

