/* BEGIN AION O14K7 REMOVE TOP DUPLICATE PACKAGE DOCK */
(function installAionO14K7RemoveTopDuplicatePackageDock() {
  function isLiveAgentsRouteO14K7() {
    try {
      return String(window.state?.activeTab || state?.activeTab || "") === "live_agents";
    } catch {
      return false;
    }
  }

  function isProtectedO14KPackageO14K7(el) {
    try {
      return !!(
        el.closest("[data-aion-o14k-collapsed-package-dock]") ||
        el.closest("[data-aion-o14k-package-content]") ||
        el.closest("[data-aion-o14k-full-package-panel]")
      );
    } catch {
      return false;
    }
  }

  function looksLikePackageDockO14K7(el) {
    if (!el) return false;

    try {
      const attrText = Array.from(el.attributes || [])
        .map((attr) => `${attr.name}=${attr.value}`)
        .join(" ")
        .toLowerCase();

      if (
        attrText.includes("package-dock") ||
        attrText.includes("department-pilot-package") ||
        attrText.includes("incoming-package") ||
        attrText.includes("boardroom-package")
      ) {
        return true;
      }

      const text = String(el.innerText || "");
      return (
        text.includes("Department Pilot Package Dock") &&
        text.includes("Boardroom assignment active") &&
        text.includes("boardroom_goal_sheet")
      );
    } catch {
      return false;
    }
  }

  function isBeforeLiveAgentsHeaderO14K7(el) {
    try {
      const all = Array.from(document.body.querySelectorAll("*"));
      const elIndex = all.indexOf(el);
      if (elIndex < 0) return false;

      const liveHeader = all.find((node) => {
        const text = String(node.innerText || "").trim();
        return text === "Live Agents" || text.startsWith("Live Agents\n");
      });

      const headerIndex = liveHeader ? all.indexOf(liveHeader) : -1;
      return headerIndex > -1 && elIndex < headerIndex;
    } catch {
      return false;
    }
  }

  function removeTopDuplicatePackageDockO14K7() {
    if (!isLiveAgentsRouteO14K7()) return;

    try {
      const candidates = Array.from(document.querySelectorAll([
        "[data-aion-o14a-department-pilot-package-dock]",
        "[data-aion-o14a1-department-pilot-incoming-package]",
        "[data-aion-o14a-stable-department-pilot-package-dock]",
        "[data-aion-o14a7-department-pilot-package-dock]",
        "[data-aion-department-pilot-package-dock]",
        "[data-aion-boardroom-package]",
        ".department-pilot-package-dock",
        ".aion-department-pilot-package-dock"
      ].join(",")));

      const extraCandidates = Array.from(document.querySelectorAll("section.panel, section, div"))
        .filter((el) => looksLikePackageDockO14K7(el))
        .slice(0, 20);

      [...candidates, ...extraCandidates].forEach((el) => {
        if (!el || isProtectedO14KPackageO14K7(el)) return;
        if (!looksLikePackageDockO14K7(el)) return;
        if (!isBeforeLiveAgentsHeaderO14K7(el)) return;

        el.setAttribute("data-aion-o14k7-top-duplicate-package-removed", "true");
        el.style.setProperty("display", "none", "important");
        el.style.setProperty("visibility", "hidden", "important");
        el.style.setProperty("height", "0", "important");
        el.style.setProperty("min-height", "0", "important");
        el.style.setProperty("margin", "0", "important");
        el.style.setProperty("padding", "0", "important");
        el.style.setProperty("overflow", "hidden", "important");
      });
    } catch {}
  }

  function scheduleO14K7() {
    window.requestAnimationFrame(removeTopDuplicatePackageDockO14K7);
    window.setTimeout(removeTopDuplicatePackageDockO14K7, 50);
    window.setTimeout(removeTopDuplicatePackageDockO14K7, 180);
    window.setTimeout(removeTopDuplicatePackageDockO14K7, 500);
  }

  document.addEventListener("DOMContentLoaded", scheduleO14K7, true);
  document.addEventListener("click", scheduleO14K7, true);
  document.addEventListener("scroll", scheduleO14K7, true);

  try {
    const observer = new MutationObserver(() => scheduleO14K7());
    observer.observe(document.documentElement || document.body, {
      childList: true,
      subtree: true,
    });
    window.__aionO14K7RemoveTopDuplicatePackageDockObserver = observer;
  } catch {}

  window.removeTopDuplicatePackageDockO14K7 = scheduleO14K7;
  scheduleO14K7();

  console.log("[AION] O14K.7 top duplicate package dock remover installed");
})();
/* END AION O14K7 REMOVE TOP DUPLICATE PACKAGE DOCK */




