/* ============================================================
 * AION O21E — Live mic capture to local STT transcript bridge
 * ============================================================
 * Preview-safe bridge:
 * - uses existing startup/conversation terminal
 * - requests browser microphone permission
 * - records short MediaRecorder chunks
 * - posts audio to /api/aion/voice/stt
 * - appends transcript text into the existing terminal transcript surface
 * - does not create another overlay
 * - does not mutate Business Twin fields yet
 * - does not call ElevenLabs or browser speech
 */

const AION_O21E_STT_ENDPOINT = "http://127.0.0.1:8080/api/aion/voice/stt";
const AION_O21E_MIC_STATE_KEY = "__aionO21ELiveMicTranscriptState";

function getAionO21ELiveMicTranscriptState() {
  if (!window[AION_O21E_MIC_STATE_KEY]) {
    window[AION_O21E_MIC_STATE_KEY] = {
      schema_version: "aion.o21e.live_mic_transcript.v0.1",
      status: "idle",
      recording: false,
      permission: "unknown",
      provider: "faster_whisper",
      endpoint: AION_O21E_STT_ENDPOINT,
      chunks_sent: 0,
      transcripts: [],
      last_error: null,
      media_stream_active: false,
      business_twin_mutation_enabled: false,
      no_overlay_created: true,
      no_elevenlabs_call: true,
      no_browser_speech_fallback: true,
    };
  }
  return window[AION_O21E_MIC_STATE_KEY];
}

function setAionO21ELiveMicStatus(patch = {}) {
  const state = getAionO21ELiveMicTranscriptState();
  Object.assign(state, patch);
  syncAionO21ELiveMicTranscriptPanel();

  try {
    const recording = state.recording === true;
    const transcribing = state.status === "transcribing";
    const requesting = state.status === "requesting_microphone";
    const pilotSpeaking = state.status === "pilot_speaking";
    const pilotThinking = state.status === "pilot_thinking";
    const failed = ["blocked", "error"].includes(state.status) || Boolean(state.last_error);
    const button = document.querySelector(
      "[data-aion-o25e-talk-toggle='true']"
    );

    if (button) {
      button.classList.toggle("is-recording", recording);
      button.setAttribute(
        "data-aion-o25e-talk-state",
        recording ? "listening" : "idle"
      );
      button.setAttribute(
        "aria-pressed",
        recording ? "true" : "false"
      );

      const label = button.querySelector(
        "[data-aion-o25e-talk-label='true']"
      );

      if (label) {
        label.textContent = recording
          ? "Stop talking"
          : "Reply to AION";
      }

      const icon = button.querySelector(
        "[data-aion-o25e-talk-icon='true']"
      );

      if (icon) {
        icon.innerHTML = recording
          ? '<rect x="7" y="7" width="10" height="10" rx="1.5"></rect>'
          : '<rect x="9" y="3" width="6" height="11" rx="3"></rect><path d="M5.5 11.5a6.5 6.5 0 0 0 13 0"></path><path d="M12 18v3"></path><path d="M9 21h6"></path>';
      }
    }

    document.querySelectorAll("[data-aion-pilot-record-meeting]").forEach((meetingButton) => {
      const meetingMode = state.pilot_flow_mode === "meeting";
      meetingButton.classList.toggle("is-recording", recording && meetingMode);
      meetingButton.disabled = transcribing || requesting || pilotSpeaking || pilotThinking;
      const label = meetingButton.querySelector("[data-aion-pilot-meeting-label]");
      if (label) label.textContent = recording && meetingMode
        ? "🔴 Stop meeting"
        : transcribing && meetingMode
          ? "… Preparing minutes"
          : "▣ Record meeting";
    });

    document.querySelectorAll("[data-aion-customer-scoped-pilot-runtime] [data-aion-pilot-dictate]").forEach((customerButton) => {
      customerButton.classList.toggle("is-recording", recording);
      customerButton.setAttribute("aria-pressed", recording ? "true" : "false");
      customerButton.setAttribute("aria-label", recording ? "Stop talking" : "Start talking");
      customerButton.setAttribute("title", recording ? "Stop talking and transcribe" : "Start talking");
      customerButton.disabled = transcribing || requesting || pilotSpeaking || pilotThinking;
      const customerLabel = customerButton.querySelector("[data-aion-pilot-dictate-label]");
      if (customerLabel) customerLabel.textContent = recording
        ? "🔴 Stop talking"
        : transcribing
          ? "… Transcribing"
          : requesting
            ? "… Opening microphone"
            : pilotSpeaking
              ? "🔊 Pilot is talking"
              : pilotThinking
                ? "… Pilot is updating quote"
            : "🎙 Start talking";
    });

    document.querySelectorAll("[data-srw-pilot-open]").forEach((customerButton) => {
      customerButton.classList.toggle("is-recording", recording);
      customerButton.setAttribute("aria-pressed", recording ? "true" : "false");
      customerButton.disabled = transcribing || requesting || pilotSpeaking || pilotThinking;
      customerButton.textContent = recording
        ? "🔴 Stop talking"
        : transcribing
          ? "… Transcribing"
          : requesting
            ? "… Opening microphone"
            : pilotSpeaking
              ? "🔊 Pilot is talking"
              : pilotThinking
                ? "… Pilot is updating quote"
            : "🎙 Talk to Pilot";
    });

    document.querySelectorAll("[data-aion-customer-pilot-voice-status]").forEach((customerStatus) => {
      customerStatus.classList.toggle("is-recording", recording);
      customerStatus.classList.toggle("is-transcribing", transcribing || requesting || pilotSpeaking || pilotThinking);
      customerStatus.classList.toggle("is-error", failed);
      customerStatus.setAttribute("data-state", String(state.status || "idle"));
      const title = customerStatus.querySelector("[data-aion-customer-pilot-voice-title]");
      const detail = customerStatus.querySelector("[data-aion-customer-pilot-voice-detail]");
      if (title) title.textContent = failed
        ? "Microphone unavailable"
        : recording
          ? "Listening now"
          : transcribing
            ? "Transcribing your request"
          : requesting
              ? "Opening microphone"
              : pilotSpeaking
                ? "Pilot is talking"
                : pilotThinking
                  ? "Pilot is updating the quotation"
              : "Microphone ready";
      if (detail) detail.textContent = failed
        ? String(state.last_error_message || "Check microphone permission and try again.")
          : recording
          ? window.__aionPilotAutoTurnTaking === true
            ? "Speak naturally. Pilot will respond after you pause, or click Stop talking."
            : "Speak naturally, then click the red Stop talking button."
          : transcribing
            ? "Pilot will add your words to this customer conversation when transcription finishes."
            : requesting
              ? "Tessaris is requesting microphone access."
              : pilotSpeaking
                ? "Your quotation is updating. Pilot will listen again when the question finishes."
                : pilotThinking
                  ? "Your last answer is being cleaned and converted into structured quote fields."
              : "Click Talk to Pilot or Start talking, speak, then stop to send it to Pilot.";
    });

    const bar = document.querySelector(
      "[data-aion-o25e-voice-bar='true']"
    );

    if (bar && state.recording === true) {
      bar.classList.add("is-active");
      bar.classList.remove("is-speaking");
      bar.setAttribute(
        "data-aion-o25e-voice-activity",
        "listening"
      );
    } else if (
      bar &&
      bar.getAttribute("data-aion-o25e-voice-activity") === "listening"
    ) {
      bar.classList.remove("is-active");
      bar.setAttribute(
        "data-aion-o25e-voice-activity",
        "idle"
      );
    }

    document.dispatchEvent(
      new CustomEvent("aion:o21e-mic-state-changed", {
        detail: {
          status: state.status || "idle",
          recording,
          permission: state.permission || "unknown",
        },
      })
    );
  } catch {}

  return state;
}

function getAionO21ETranscriptContainer() {
  return (
    document.querySelector("[data-aion-o21e-live-transcript-log]") ||
    document.querySelector("[data-aion-startup-transcript-log]") ||
    document.querySelector("[data-aion-o20c-conversation-transcript]") ||
    document.querySelector("[data-aion-conversation-transcript]") ||
    document.querySelector(".aion-startup-terminal-transcript") ||
    document.querySelector(".aion-conversation-transcript")
  );
}

function appendAionO21ETranscript(text, meta = {}) {
  const clean = String(text || "").trim();
  if (!clean) return null;

  const state = getAionO21ELiveMicTranscriptState();
  const item = {
    id: `o21e_transcript_${Date.now()}_${Math.random().toString(16).slice(2)}`,
    text: clean,
    provider: meta.provider || "faster_whisper",
    language: meta.language || null,
    created_at: new Date().toISOString(),
    business_twin_mutation_enabled: false,
  };

  state.transcripts.push(item);
  state.last_transcript = clean;

  const container = getAionO21ETranscriptContainer();
  if (container) {
    const row = document.createElement('div');
    row.className = "aion-o21e-live-transcript-row";
    row.setAttribute("data-aion-o21e-live-transcript-row", item.id);
    row.innerHTML = `
      <div class="aion-o21e-live-transcript-speaker">You · local STT</div>
      <div class="aion-o21e-live-transcript-text"></div>
    `;
    const textEl = row.querySelector(".aion-o21e-live-transcript-text");
    if (textEl) textEl.textContent = clean;
    container.appendChild(row);
    container.scrollTop = container.scrollHeight;
  }

  syncAionO21ELiveMicTranscriptPanel();
  try {
    document.dispatchEvent(new CustomEvent("aion:pilot-flow-transcript", {
      detail: { text: clean, ...item },
    }));
  } catch {}
  return item;
}

async function postAionO21EAudioChunkToStt(blob) {
  const state = getAionO21ELiveMicTranscriptState();

  if (!blob || !blob.size) {
    setAionO21ELiveMicStatus({
      last_error: "empty_audio_chunk",
      status: "recording",
    });
    return null;
  }

  const form = new FormData();
  form.append("file", blob, `aion-o21e-mic-${Date.now()}.webm`);

  state.chunks_sent += 1;
  syncAionO21ELiveMicTranscriptPanel();

  const response = await fetch(AION_O21E_STT_ENDPOINT, {
    method: "POST",
    body: form,
  });

  let payload = null;
  try {
    payload = await response.json();
  } catch (error) {
    payload = {
      ok: false,
      provider: "faster_whisper",
      reason: "invalid_stt_json",
      message: String(error && error.message ? error.message : error),
    };
  }

  if (!response.ok || !payload || payload.ok === false) {
    setAionO21ELiveMicStatus({
      status: state.recording ? "recording" : "idle",
      last_error: payload?.reason || `stt_http_${response.status}`,
      last_error_message: payload?.message || null,
      provider: payload?.provider || "faster_whisper",
    });
    return payload;
  }

  appendAionO21ETranscript(payload.text || "", {
    provider: payload.provider || "faster_whisper",
    language: payload.language || null,
  });

  setAionO21ELiveMicStatus({
    status: state.recording ? "recording" : "transcribed",
    last_error: null,
    provider: payload.provider || "faster_whisper",
  });

  return payload;
}

async function startAionO21ELiveMicTranscriptCapture() {
  const state = getAionO21ELiveMicTranscriptState();

  if (state.recording && state.media_recorder) {
    return setAionO21ELiveMicStatus({
      status: "recording",
      recording: true,
    });
  }

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    return setAionO21ELiveMicStatus({
      status: "blocked",
      recording: false,
      permission: "unsupported",
      last_error: "browser_microphone_api_unavailable",
    });
  }

  try {
    setAionO21ELiveMicStatus({
      status: "requesting_microphone",
      last_error: null,
    });

    if (typeof window.aionDesktop?.requestMicrophonePermission === "function") {
      const permissionResult = await window.aionDesktop.requestMicrophonePermission();
      if (permissionResult?.granted !== true) {
        throw new Error(`Microphone permission is ${permissionResult?.status || "unavailable"}`);
      }
    }

    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    const preferredMimeType = typeof MediaRecorder.isTypeSupported === "function" && MediaRecorder.isTypeSupported("audio/webm;codecs=opus")
      ? "audio/webm;codecs=opus"
      : typeof MediaRecorder.isTypeSupported === "function" && MediaRecorder.isTypeSupported("audio/webm")
        ? "audio/webm"
        : "";
    const recorder = preferredMimeType
      ? new MediaRecorder(stream, { mimeType: preferredMimeType })
      : new MediaRecorder(stream);

    state.media_stream = stream;
    state.media_recorder = recorder;
    state.media_stream_active = true;
    state.permission = "granted";

    // One microphone session represents one complete answer.
    state.session_audio_chunks = [];
    state.session_audio_mime_type =
      recorder.mimeType || "audio/webm";
    state.session_started_at =
      new Date().toISOString();

    recorder.ondataavailable = (event) => {
      if (
        event &&
        event.data &&
        event.data.size > 0
      ) {
        state.session_audio_chunks.push(
          event.data
        );
      }
    };

    recorder.onerror = (event) => {
      setAionO21ELiveMicStatus({
        status: "error",
        recording: false,
        last_error: "media_recorder_error",
        last_error_message: String(
          event?.error?.message ||
          event?.message ||
          "MediaRecorder failed"
        ),
      });
    };

    recorder.onstop = async () => {
      const answerChunks = Array.isArray(
        state.session_audio_chunks
      )
        ? [...state.session_audio_chunks]
        : [];

      state.session_audio_chunks = [];

      setAionO21ELiveMicStatus({
        status: answerChunks.length
          ? "transcribing"
          : "idle",
        recording: false,
        media_stream_active: false,
      });

      if (!answerChunks.length) {
        return;
      }

      const completeAnswerBlob = new Blob(
        answerChunks,
        {
          type:
            state.session_audio_mime_type ||
            "audio/webm",
        }
      );

      try {
        await postAionO21EAudioChunkToStt(
          completeAnswerBlob
        );
      } catch (error) {
        setAionO21ELiveMicStatus({
          status: "idle",
          recording: false,
          last_error: "stt_post_failed",
          last_error_message: String(
            error && error.message
              ? error.message
              : error
          ),
        });
      }
    };

    // Small chunks allow the conversation mode to finish a turn after natural silence.
    recorder.start(250);
    startAionPilotSilenceTurnMonitor(stream, state);

    return setAionO21ELiveMicStatus({
      status: "recording",
      recording: true,
      last_error: null,
      provider: "faster_whisper",
      endpoint: AION_O21E_STT_ENDPOINT,
    });
  } catch (error) {
    return setAionO21ELiveMicStatus({
      status: "blocked",
      recording: false,
      permission: "denied_or_failed",
      last_error: "microphone_permission_failed",
      last_error_message: String(error && error.message ? error.message : error),
    });
  }
}

function stopAionPilotSilenceTurnMonitor(state = getAionO21ELiveMicTranscriptState()) {
  if (state.silence_monitor_frame) cancelAnimationFrame(state.silence_monitor_frame);
  state.silence_monitor_frame = null;
  try { state.silence_audio_context?.close?.(); } catch {}
  state.silence_audio_context = null;
}

function startAionPilotSilenceTurnMonitor(stream, state = getAionO21ELiveMicTranscriptState()) {
  stopAionPilotSilenceTurnMonitor(state);
  if (window.__aionPilotAutoTurnTaking !== true) return;
  const AudioContextConstructor = window.AudioContext || window.webkitAudioContext;
  if (!AudioContextConstructor) return;
  try {
    const audioContext = new AudioContextConstructor();
    const analyser = audioContext.createAnalyser();
    analyser.fftSize = 1024;
    audioContext.createMediaStreamSource(stream).connect(analyser);
    const samples = new Uint8Array(analyser.fftSize);
    const startedAt = performance.now();
    let heardSpeech = false;
    let lastSpeechAt = startedAt;
    state.silence_audio_context = audioContext;
    const inspect = () => {
      if (!state.recording || state.media_stream !== stream) return stopAionPilotSilenceTurnMonitor(state);
      analyser.getByteTimeDomainData(samples);
      let energy = 0;
      for (let index = 0; index < samples.length; index += 1) {
        const normalized = (samples[index] - 128) / 128;
        energy += normalized * normalized;
      }
      const volume = Math.sqrt(energy / samples.length);
      const now = performance.now();
      if (volume >= 0.018) { heardSpeech = true; lastSpeechAt = now; }
      if ((heardSpeech && now - lastSpeechAt >= 1600) || now - startedAt >= 45000) {
        stopAionO21ELiveMicTranscriptCapture();
        return;
      }
      state.silence_monitor_frame = requestAnimationFrame(inspect);
    };
    state.silence_monitor_frame = requestAnimationFrame(inspect);
  } catch { stopAionPilotSilenceTurnMonitor(state); }
}

function stopAionO21ELiveMicTranscriptCapture() {
  const state = getAionO21ELiveMicTranscriptState();
  stopAionPilotSilenceTurnMonitor(state);

  try {
    if (state.media_recorder && state.media_recorder.state !== "inactive") {
      state.media_recorder.stop();
    }
  } catch (error) {
    state.last_error = "media_recorder_stop_failed";
    state.last_error_message = String(error && error.message ? error.message : error);
  }

  try {
    if (state.media_stream && state.media_stream.getTracks) {
      state.media_stream.getTracks().forEach((track) => track.stop());
    }
  } catch (error) {
    state.last_error = "media_stream_stop_failed";
    state.last_error_message = String(error && error.message ? error.message : error);
  }

  state.media_stream = null;
  state.media_recorder = null;

  return setAionO21ELiveMicStatus({
    status: "transcribing",
    recording: false,
    media_stream_active: false,
  });
}

function toggleAionO21ELiveMicTranscriptCapture() {
  const state = getAionO21ELiveMicTranscriptState();
  if (state.recording) return stopAionO21ELiveMicTranscriptCapture();
  return startAionO21ELiveMicTranscriptCapture();
}

function renderAionO21ELiveMicTranscriptPanel() {
  const state = getAionO21ELiveMicTranscriptState();
  const status = state.status || "idle";
  const recording = !!state.recording;
  const provider = state.provider || "faster_whisper";
  const cloudVoice = "off";
  const localStt = provider === "faster_whisper" ? "Local Whisper" : provider;

  return `
    <section class="aion-o21e-live-mic-panel" data-aion-o21e-live-mic-panel>
      <div class="aion-o21e-live-mic-head">
        <div>
          <div class="aion-o21e-live-mic-title">Live voice input</div>
          <div class="aion-o21e-live-mic-subtitle">STT: ${localStt} · Cloud voice: ${cloudVoice}</div>
        </div>
        <button
          type="button"
          class="aion-o21e-live-mic-toggle"
          data-aion-o21e-live-mic-toggle
          onclick="window.toggleAionO21ELiveMicTranscriptCapture && window.toggleAionO21ELiveMicTranscriptCapture()"
        >${recording ? "Stop listening" : "Start listening"}</button>
      </div>
      <div class="aion-o21e-live-mic-status" data-aion-o21e-live-mic-status>
        ${recording ? "Listening locally..." : `Mic status: ${status}`}
      </div>
      <div class="aion-o21e-live-mic-flags">
        <span>chunks: ${state.chunks_sent || 0}</span>
        <span>transcripts: ${(state.transcripts || []).length}</span>
        <span>Business Twin mutation: off</span>
      </div>
      ${
        state.last_error
          ? `<div class="aion-o21e-live-mic-error" data-aion-o21e-live-mic-error>${state.last_error}</div>`
          : `<div class="aion-o21e-live-mic-note" data-aion-o21e-live-mic-note>No hidden paid voice usage.</div>`
      }
      <div class="aion-o21e-live-transcript-log" data-aion-o21e-live-transcript-log></div>
    </section>
  `;
}

function ensureAionO21ELiveMicTranscriptPanel() {
  if (document.querySelector("[data-aion-o21e-live-mic-panel]")) return;

  const terminal =
    document.querySelector("[data-aion-o20c-conversation-terminal]") ||
    document.querySelector("[data-aion-startup-conversation-terminal]") ||
    document.querySelector("[data-aion-business-entry-mode-selector]") ||
    document.querySelector("#app") ||
    document.body;

  if (!terminal) return;

  const wrapper = document.createElement('div');
  wrapper.setAttribute("data-aion-o21e-live-mic-panel-host", "true");
  wrapper.innerHTML = renderAionO21ELiveMicTranscriptPanel();
  terminal.appendChild(wrapper);
}

function syncAionO21ELiveMicTranscriptPanel() {
  const panel = document.querySelector("[data-aion-o21e-live-mic-panel]");
  if (!panel) return;

  const state = getAionO21ELiveMicTranscriptState();

  const statusEl = panel.querySelector("[data-aion-o21e-live-mic-status]");
  if (statusEl) {
    statusEl.textContent = state.recording ? "Listening locally..." : `Mic status: ${state.status || "idle"}`;
  }

  const button = panel.querySelector("[data-aion-o21e-live-mic-toggle]");
  if (button) {
    button.textContent = state.recording ? "Stop listening" : "Start listening";
  }

  const errorEl = panel.querySelector("[data-aion-o21e-live-mic-error]");
  if (errorEl && state.last_error) {
    errorEl.textContent = state.last_error;
  }
}

